const NexusEnvironment = (function() {
    'use strict';
    
    // ═══════════════════════════════════════════════════════════════════════════
    // ISSUE #1 FIX: SMART KEY ROUTER
    // Your issue: gsk_ key was being sent to Gemini API (WRONG!)
    // Solution: ALWAYS detect key type and route to correct provider
    // ═══════════════════════════════════════════════════════════════════════════
    
    const SmartKeyRouter = {
        // Key format patterns for each provider
        keyPatterns: {
            groq: {
                prefix: 'gsk_',
                regex: /^gsk_[a-zA-Z0-9]{52}$/,
                name: 'Groq',
                icon: '⚡',
                endpoint: 'https://api.groq.com/openai/v1/chat/completions',
                model: 'llama-3.3-70b-versatile',
                headerStyle: 'bearer'  // Authorization: Bearer KEY
            },
            gemini: {
                prefix: 'AIza',
                regex: /^AIza[a-zA-Z0-9_-]{35,}$/,
                name: 'Google Gemini',
                icon: '💎',
                endpoint: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent',
                model: 'gemini-2.0-flash',
                headerStyle: 'query'  // ?key=KEY
            },
            openai: {
                prefix: 'sk-',
                regex: /^sk-[a-zA-Z0-9]{48,}$/,
                name: 'OpenAI',
                icon: '🧠',
                endpoint: 'https://api.openai.com/v1/chat/completions',
                model: 'gpt-4o-mini',
                headerStyle: 'bearer'
            },
            anthropic: {
                prefix: 'sk-ant-',
                regex: /^sk-ant-[a-zA-Z0-9-]{90,}$/,
                name: 'Anthropic Claude',
                icon: '🧬',
                endpoint: 'https://api.anthropic.com/v1/messages',
                model: 'claude-3-haiku-20240307',
                headerStyle: 'x-api-key'
            },
            deepseek: {
                prefix: 'sk-',
                regex: /^sk-[a-zA-Z0-9]{20,45}$/,  // Shorter than OpenAI
                name: 'DeepSeek',
                icon: '🔮',
                endpoint: 'https://api.deepseek.com/v1/chat/completions',
                model: 'deepseek-chat',
                headerStyle: 'bearer'
            },
            together: {
                prefix: '',  // No specific prefix
                regex: /^[a-f0-9]{64}$/,  // 64 hex chars
                name: 'Together AI',
                icon: '🤝',
                endpoint: 'https://api.together.xyz/v1/chat/completions',
                model: 'meta-llama/Meta-Llama-3.1-70B-Instruct-Turbo',
                headerStyle: 'bearer'
            },
            openrouter: {
                prefix: 'sk-or-',
                regex: /^sk-or-[a-zA-Z0-9-]+$/,
                name: 'OpenRouter',
                icon: '🌐',
                endpoint: 'https://openrouter.ai/api/v1/chat/completions',
                model: 'google/gemini-flash-1.5-8b',
                headerStyle: 'bearer'
            },
            mistral: {
                prefix: '',
                regex: /^[a-zA-Z0-9]{32}$/,  // 32 alphanumeric
                name: 'Mistral AI',
                icon: '🌪️',
                endpoint: 'https://api.mistral.ai/v1/chat/completions',
                model: 'mistral-small-latest',
                headerStyle: 'bearer'
            }
        },
        
        // CRITICAL: Detect provider from key format
        detectProvider(key) {
            if (!key || typeof key !== 'string') return null;
            
            key = key.trim();
            
            // Check prefixes first (fastest)
            if (key.startsWith('gsk_')) return 'groq';
            if (key.startsWith('AIza')) return 'gemini';
            if (key.startsWith('sk-ant-')) return 'anthropic';
            if (key.startsWith('sk-or-')) return 'openrouter';
            
            // Check sk- keys by length (OpenAI vs DeepSeek)
            if (key.startsWith('sk-')) {
                // OpenAI keys are typically 51+ chars, DeepSeek ~32 chars
                return key.length >= 48 ? 'openai' : 'deepseek';
            }
            
            // Check regex patterns
            for (const [provider, config] of Object.entries(this.keyPatterns)) {
                if (config.regex.test(key)) return provider;
            }
            
            // Default to gemini as fallback
            console.warn('[SmartKeyRouter] Unknown key format, defaulting to gemini');
            return 'gemini';
        },
        
        // Get provider config
        getConfig(provider) {
            return this.keyPatterns[provider] || this.keyPatterns.gemini;
        },
        
        // Validate key format
        isValidKeyFormat(key, provider) {
            if (!key || !provider) return false;
            const config = this.keyPatterns[provider];
            if (!config) return false;
            return config.regex.test(key);
        },
        
        // Format API request based on provider
        formatRequest(key, prompt, provider) {
            provider = provider || this.detectProvider(key);
            const config = this.getConfig(provider);
            
            let headers = { 'Content-Type': 'application/json' };
            let url = config.endpoint;
            let body;
            
            // Set auth header based on style
            switch (config.headerStyle) {
                case 'bearer':
                    headers['Authorization'] = `Bearer ${key}`;
                    break;
                case 'x-api-key':
                    headers['x-api-key'] = key;
                    headers['anthropic-version'] = '2023-06-01';
                    break;
                case 'query':
                    url = `${config.endpoint}?key=${key}`;
                    break;
            }
            
            // Format body based on provider
            if (provider === 'gemini') {
                body = {
                    contents: [{ parts: [{ text: prompt }] }],
                    generationConfig: { temperature: 0.3, maxOutputTokens: 4096 }
                };
            } else if (provider === 'anthropic') {
                body = {
                    model: config.model,
                    max_tokens: 4096,
                    messages: [{ role: 'user', content: prompt }]
                };
            } else {
                // OpenAI-compatible (Groq, OpenAI, DeepSeek, Together, OpenRouter, Mistral)
                body = {
                    model: config.model,
                    messages: [
                        { role: 'system', content: 'You are an expert security researcher.' },
                        { role: 'user', content: prompt }
                    ],
                    temperature: 0.3,
                    max_tokens: 4096
                };
            }
            
            return { url, headers, body, provider, config };
        },
        
        // Parse response based on provider
        parseResponse(data, provider) {
            if (provider === 'gemini') {
                return data?.candidates?.[0]?.content?.parts?.[0]?.text;
            } else if (provider === 'anthropic') {
                return data?.content?.[0]?.text;
            } else {
                // OpenAI-compatible
                return data?.choices?.[0]?.message?.content;
            }
        },
        
        // Quick diagnostic for user's key
        diagnoseKey(key) {
            const provider = this.detectProvider(key);
            const config = this.getConfig(provider);
            const isValid = this.isValidKeyFormat(key, provider);
            
            return {
                key: key.substring(0, 15) + '...',
                detectedProvider: provider,
                providerName: config?.name || 'Unknown',
                icon: config?.icon || '❓',
                endpoint: config?.endpoint || 'Unknown',
                isValidFormat: isValid,
                suggestion: isValid ? 
                    `✅ Key looks valid for ${config.name}` : 
                    `⚠️ Key format doesn't match ${config.name} pattern`
            };
        }
    };
    
    // ═══════════════════════════════════════════════════════════════════════════
    // ISSUE #2 FIX: TUNNEL HEALTH CHECKER
    // Your issue: Cloudflare tunnel URL expires every ~24 hours
    // Solution: Detect expired tunnels and alert user
    // ═══════════════════════════════════════════════════════════════════════════
    
    const TunnelHealthChecker = {
        lastCheckTime: 0,
        checkInterval: 30000,  // Check every 30 seconds
        tunnelStatus: {
            isAlive: false,
            lastSuccess: null,
            lastError: null,
            consecutiveFailures: 0,
            url: null
        },
        
        // Check if a Cloudflare tunnel is still alive
        async checkTunnel(url) {
            if (!url) {
                url = localStorage.getItem('nexus_terminal_url') || this.tunnelStatus.url;
            }
            
            if (!url) return { isAlive: false, reason: 'No URL saved' };
            
            this.tunnelStatus.url = url;
            
            // Convert to HTTP for health check
            const httpUrl = url.replace(/^wss?:\/\//, 'https://').replace(/^ws:\/\//, 'http://');
            
            try {
                // Try multiple health check endpoints
                const endpoints = [
                    `${httpUrl}/health`,
                    `${httpUrl}/bridge/health`,
                    httpUrl
                ];
                
                for (const endpoint of endpoints) {
                    try {
                        const controller = new AbortController();
                        const timeout = setTimeout(() => controller.abort(), 5000);
                        
                        const response = await fetch(endpoint, {
                            method: 'HEAD',
                            mode: 'no-cors',
                            signal: controller.signal
                        });
                        
                        clearTimeout(timeout);
                        
                        // If we got here, the server is responding
                        this.tunnelStatus.isAlive = true;
                        this.tunnelStatus.lastSuccess = Date.now();
                        this.tunnelStatus.consecutiveFailures = 0;
                        this.tunnelStatus.lastError = null;
                        
                        return { isAlive: true, url, checkedAt: new Date().toISOString() };
                    } catch (e) {
                        continue;  // Try next endpoint
                    }
                }
                
                // All endpoints failed
                throw new Error('All health check endpoints failed');
                
            } catch (error) {
                this.tunnelStatus.isAlive = false;
                this.tunnelStatus.consecutiveFailures++;
                this.tunnelStatus.lastError = error.message;
                
                // Detect specific tunnel expiry patterns
                const isExpired = this.tunnelStatus.consecutiveFailures >= 3;
                
                return {
                    isAlive: false,
                    url,
                    error: error.message,
                    isExpired,
                    suggestion: isExpired ? 
                        '🔄 Cloudflare tunnel likely EXPIRED! Run nexus-terminal.js again to get new URL.' :
                        '⚠️ Connection issue - will retry...'
                };
            }
        },
        
        // Check if tunnel URL looks like expired Cloudflare quick tunnel
        isCloudflareQuickTunnel(url) {
            return url && url.includes('.trycloudflare.com');
        },
        
        // Get tunnel age estimate (quick tunnels expire ~24h)
        getTunnelAge() {
            const savedTime = localStorage.getItem('nexus_terminal_connected_time');
            if (!savedTime) return null;
            
            const ageMs = Date.now() - parseInt(savedTime);
            const ageHours = ageMs / (1000 * 60 * 60);
            
            return {
                ageMs,
                ageHours: Math.round(ageHours * 10) / 10,
                isExpiringSoon: ageHours > 20,  // Warning at 20 hours
                isLikelyExpired: ageHours > 24  // Expired at 24 hours
            };
        },
        
        // Full tunnel diagnostic
        async diagnose() {
            const url = localStorage.getItem('nexus_terminal_url');
            
            if (!url) {
                return {
                    status: 'NO_URL',
                    message: '❌ No terminal URL saved. Run connectTerminal() first.',
                    suggestions: [
                        '1. Start nexus-terminal.js in your terminal',
                        '2. Copy the Cloudflare URL (wss://xxx.trycloudflare.com)',
                        '3. Run: connectTerminal("wss://xxx.trycloudflare.com", "TOKEN")'
                    ]
                };
            }
            
            const isQuickTunnel = this.isCloudflareQuickTunnel(url);
            const age = this.getTunnelAge();
            const health = await this.checkTunnel(url);
            
            let status, message, suggestions = [];
            
            if (health.isAlive) {
                if (isQuickTunnel && age?.isExpiringSoon) {
                    status = 'EXPIRING_SOON';
                    message = `⚠️ Tunnel working but ${age.ageHours}h old. Will expire soon!`;
                    suggestions.push('Consider restarting nexus-terminal.js for fresh URL');
                } else {
                    status = 'HEALTHY';
                    message = '✅ Tunnel is healthy and responding!';
                }
            } else {
                if (isQuickTunnel && (age?.isLikelyExpired || health.isExpired)) {
                    status = 'EXPIRED';
                    message = `❌ Cloudflare tunnel EXPIRED (${age?.ageHours || '?'}h old)`;
                    suggestions = [
                        '🔄 SOLUTION: Restart nexus-terminal.js to get a NEW URL!',
                        '1. Press Ctrl+C in terminal to stop old session',
                        '2. Run: node nexus-terminal.js',
                        '3. Copy the new Cloudflare URL',
                        '4. Run: connectTerminal("NEW_URL", "NEW_TOKEN")'
                    ];
                } else {
                    status = 'DISCONNECTED';
                    message = '❌ Cannot reach tunnel server';
                    suggestions = [
                        'Check if nexus-terminal.js is still running',
                        'Check your internet connection',
                        'Try restarting nexus-terminal.js'
                    ];
                }
            }
            
            return { status, message, url, isQuickTunnel, age, health, suggestions };
        }
    };
    
    // ═══════════════════════════════════════════════════════════════════════════
    // SECTION 1: ENVIRONMENT DETECTION & ADAPTATION
    // ═══════════════════════════════════════════════════════════════════════════
    
    const ENV = {
        // Browser Detection
        browser: {
            name: 'unknown',
            version: 0,
            engine: 'unknown',
            isChrome: false,
            isFirefox: false,
            isSafari: false,
            isEdge: false,
            isBrave: false,
            isOpera: false
        },
        
        // Security Features Detection
        security: {
            hasCSP: false,
            hasTrustedTypes: false,
            cspDirectives: {},
            blockedFeatures: [],
            sandboxed: false
        },
        
        // Console Environment Detection
        console: {
            isModified: false,
            hasDebugger: false,
            isBlocked: false,
            originalMethods: {}
        },
        
        // Network Capabilities
        network: {
            hasWebSocket: false,
            hasFetch: false,
            hasXHR: false,
            corsMode: 'unknown',
            blockedDomains: []
        },
        
        // Storage Capabilities
        storage: {
            hasLocalStorage: false,
            hasSessionStorage: false,
            hasIndexedDB: false,
            quotaEstimate: 0
        },
        
        // Feature Support
        features: {
            hasServiceWorker: false,
            hasWebWorker: false,
            hasSharedWorker: false,
            hasBroadcastChannel: false,
            hasClipboard: false,
            hasNotifications: false
        }
    };
    
    // ═══════════════════════════════════════════════════════════════════════════
    // SECTION 2: BROWSER DETECTION
    // ═══════════════════════════════════════════════════════════════════════════
    
    function detectBrowser() {
        const ua = navigator.userAgent;
        const vendor = navigator.vendor || '';
        
        // Chrome (and Chromium-based)
        if (/Chrome\/(\d+)/.test(ua) && vendor.includes('Google')) {
            ENV.browser.name = 'Chrome';
            ENV.browser.version = parseInt(RegExp.$1);
            ENV.browser.isChrome = true;
            ENV.browser.engine = 'Blink';
        }
        // Edge (Chromium)
        else if (/Edg\/(\d+)/.test(ua)) {
            ENV.browser.name = 'Edge';
            ENV.browser.version = parseInt(RegExp.$1);
            ENV.browser.isEdge = true;
            ENV.browser.engine = 'Blink';
        }
        // Brave
        else if (navigator.brave?.isBrave) {
            ENV.browser.name = 'Brave';
            ENV.browser.isBrave = true;
            ENV.browser.engine = 'Blink';
            if (/Chrome\/(\d+)/.test(ua)) ENV.browser.version = parseInt(RegExp.$1);
        }
        // Opera
        else if (/OPR\/(\d+)/.test(ua) || /Opera/.test(ua)) {
            ENV.browser.name = 'Opera';
            ENV.browser.isOpera = true;
            ENV.browser.engine = 'Blink';
            if (/OPR\/(\d+)/.test(ua)) ENV.browser.version = parseInt(RegExp.$1);
        }
        // Firefox
        else if (/Firefox\/(\d+)/.test(ua)) {
            ENV.browser.name = 'Firefox';
            ENV.browser.version = parseInt(RegExp.$1);
            ENV.browser.isFirefox = true;
            ENV.browser.engine = 'Gecko';
        }
        // Safari
        else if (/Safari\/(\d+)/.test(ua) && vendor.includes('Apple')) {
            ENV.browser.name = 'Safari';
            ENV.browser.isSafari = true;
            ENV.browser.engine = 'WebKit';
            if (/Version\/(\d+)/.test(ua)) ENV.browser.version = parseInt(RegExp.$1);
        }
        
        return ENV.browser;
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    // SECTION 3: CSP & SECURITY DETECTION
    // ═══════════════════════════════════════════════════════════════════════════
    
    function detectSecurity() {
        // Check TrustedTypes
        ENV.security.hasTrustedTypes = typeof window.trustedTypes !== 'undefined';
        
        // Check if CSP is blocking things - WITHOUT using script execution
        // Using a safer detection method that doesn't trigger TrustedTypes
        try {
            // Method 1: Check for CSP meta tag directly
            const cspMeta = document.querySelector('meta[http-equiv="Content-Security-Policy"]');
            if (cspMeta) {
                ENV.security.hasCSP = true;
                const csp = cspMeta.content;
                const directives = csp.split(';').map(d => d.trim());
                directives.forEach(d => {
                    const [name, ...values] = d.split(/\s+/);
                    if (name) ENV.security.cspDirectives[name] = values;
                });
            } else {
                // Method 2: Check CSP header via performance API
                if (typeof PerformanceObserver !== 'undefined') {
                    // If we got here via console paste, CSP likely allows unsafe-eval
                    ENV.security.hasCSP = false;
                } else {
                    // Assume CSP exists if we can't detect
                    ENV.security.hasCSP = true;
                }
            }
            
            // Method 3: Check for TrustedTypes enforcement (if TT exists and we're restricted)
            if (ENV.security.hasTrustedTypes && window.trustedTypes.defaultPolicy === null) {
                // Try to create a default policy for our use
                try {
                    if (typeof window.trustedTypes.createPolicy === 'function') {
                        window.__NEXUS_TT_POLICY__ = window.trustedTypes.createPolicy('nexus-scanner', {
                            createHTML: (input) => input,
                            createScript: (input) => input,
                            createScriptURL: (input) => input
                        });
                        ENV.security.hasTrustedTypesPolicy = true;
                    }
                } catch (policyErr) {
                    // Policy creation blocked - that's fine, we'll work around it
                    ENV.security.hasTrustedTypesPolicy = false;
                }
            }
        } catch (e) {
            ENV.security.hasCSP = true;
        }
        
        // Check for sandbox attribute
        try {
            ENV.security.sandboxed = window.top !== window.self && !window.frameElement;
        } catch (e) {
            ENV.security.sandboxed = true;
        }
        
        return ENV.security;
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    // SECTION 4: CONSOLE PROTECTION BYPASS
    // ═══════════════════════════════════════════════════════════════════════════
    
    function protectConsole() {
        // Save original console methods
        const originalConsole = {
            log: console.log,
            warn: console.warn,
            error: console.error,
            info: console.info,
            debug: console.debug,
            table: console.table,
            group: console.group,
            groupEnd: console.groupEnd,
            groupCollapsed: console.groupCollapsed,
            clear: console.clear,
            trace: console.trace
        };
        ENV.console.originalMethods = originalConsole;
        
        // Check if console is modified
        try {
            const testLog = console.log.toString();
            ENV.console.isModified = !testLog.includes('[native code]');
        } catch (e) {
            ENV.console.isModified = true;
        }
        
        // Restore console if modified
        if (ENV.console.isModified) {
            try {
                // Get fresh console from iframe
                const iframe = document.createElement('iframe');
                iframe.style.display = 'none';
                document.body.appendChild(iframe);
                const freshConsole = iframe.contentWindow.console;
                
                // Replace all methods
                Object.keys(originalConsole).forEach(method => {
                    if (freshConsole[method]) {
                        console[method] = freshConsole[method].bind(freshConsole);
                    }
                });
                
                document.body.removeChild(iframe);
                console.log('[NEXUS] Console restored from iframe');
            } catch (e) {
                // Fallback: try to use bound console methods directly
                try {
                    // Safe approach without Function constructor (CSP compatible)
                    const safeLog = console.log.bind(console);
                    if (safeLog) console.log = safeLog;
                } catch (e2) {
                    // Console protection is active but we can still work
                }
            }
        }
        
        // Anti-debugger protection
        const antiDebugger = () => {
            const startTime = performance.now();
            debugger;
            const endTime = performance.now();
            if (endTime - startTime > 100) {
                // Debugger is open, continue anyway
                ENV.console.hasDebugger = true;
            }
        };
        
        // Override debugger detection
        try {
            Object.defineProperty(window, 'debugger', {
                get: () => {},
                set: () => {}
            });
        } catch (e) {}
        
        return ENV.console;
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    // SECTION 5: NETWORK CAPABILITY DETECTION
    // ═══════════════════════════════════════════════════════════════════════════
    
    function detectNetwork() {
        // WebSocket support - SAFE CHECK that works everywhere
        try {
            ENV.network.hasWebSocket = (typeof WebSocket !== 'undefined') || 
                                       (typeof window !== 'undefined' && typeof window.WebSocket !== 'undefined');
        } catch (e) {
            ENV.network.hasWebSocket = false;
        }
        
        // Fetch support
        try {
            ENV.network.hasFetch = (typeof fetch !== 'undefined') || 
                                   (typeof window !== 'undefined' && typeof window.fetch !== 'undefined');
        } catch (e) {
            ENV.network.hasFetch = false;
        }
        
        // XHR support
        try {
            ENV.network.hasXHR = (typeof XMLHttpRequest !== 'undefined') || 
                                 (typeof window !== 'undefined' && typeof window.XMLHttpRequest !== 'undefined');
        } catch (e) {
            ENV.network.hasXHR = false;
        }
        
        // CORS mode detection - NO external requests (CSP safe)
        // We assume CORS is available if fetch exists, actual testing happens on-demand
        ENV.network.corsMode = ENV.network.hasFetch ? 'available' : 'unavailable';
        
        return ENV.network;
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    // SECTION 6: STORAGE DETECTION
    // ═══════════════════════════════════════════════════════════════════════════
    
    function detectStorage() {
        // LocalStorage
        try {
            localStorage.setItem('__nexus_test__', '1');
            localStorage.removeItem('__nexus_test__');
            ENV.storage.hasLocalStorage = true;
        } catch (e) {
            ENV.storage.hasLocalStorage = false;
        }
        
        // SessionStorage
        try {
            sessionStorage.setItem('__nexus_test__', '1');
            sessionStorage.removeItem('__nexus_test__');
            ENV.storage.hasSessionStorage = true;
        } catch (e) {
            ENV.storage.hasSessionStorage = false;
        }
        
        // IndexedDB
        ENV.storage.hasIndexedDB = typeof indexedDB !== 'undefined';
        
        // Storage quota
        if (navigator.storage?.estimate) {
            navigator.storage.estimate().then(est => {
                ENV.storage.quotaEstimate = est.quota || 0;
            }).catch(() => {});
        }
        
        return ENV.storage;
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    // SECTION 7: FEATURE DETECTION
    // ═══════════════════════════════════════════════════════════════════════════
    
    function detectFeatures() {
        // Safe feature detection with try-catch for each
        try {
            ENV.features.hasServiceWorker = typeof navigator !== 'undefined' && 'serviceWorker' in navigator;
        } catch (e) {
            ENV.features.hasServiceWorker = false;
        }
        
        try {
            ENV.features.hasWebWorker = typeof window !== 'undefined' && typeof window.Worker !== 'undefined';
        } catch (e) {
            ENV.features.hasWebWorker = false;
        }
        
        try {
            ENV.features.hasSharedWorker = typeof window !== 'undefined' && typeof window.SharedWorker !== 'undefined';
        } catch (e) {
            ENV.features.hasSharedWorker = false;
        }
        
        try {
            ENV.features.hasBroadcastChannel = typeof window !== 'undefined' && typeof window.BroadcastChannel !== 'undefined';
        } catch (e) {
            ENV.features.hasBroadcastChannel = false;
        }
        
        try {
            ENV.features.hasClipboard = typeof navigator !== 'undefined' && navigator.clipboard !== undefined;
        } catch (e) {
            ENV.features.hasClipboard = false;
        }
        
        try {
            ENV.features.hasNotifications = typeof window !== 'undefined' && 'Notification' in window;
        } catch (e) {
            ENV.features.hasNotifications = false;
        }
        
        return ENV.features;
    }
    
    // ═══════════════════════════════════════════════════════════════════════════
    // SECTION 8: UNIVERSAL POPUP/MODAL SYSTEM
    // ═══════════════════════════════════════════════════════════════════════════
    
    const UIAdapter = {
        // Create modal that works everywhere
        createModal(content, options = {}) {
            const {
                title = 'NEXUS',
                width = '500px',
                height = 'auto',
                closable = true,
                className = 'nexus-modal'
            } = options;
            
            // Remove existing modal
            document.querySelectorAll('.nexus-modal-overlay').forEach(el => el.remove());
            
            // Create overlay
            const overlay = document.createElement('div');
            overlay.className = 'nexus-modal-overlay';
            overlay.style.cssText = `
                position: fixed !important;
                top: 0 !important;
                left: 0 !important;
                right: 0 !important;
                bottom: 0 !important;
                background: rgba(0,0,0,0.8) !important;
                z-index: 2147483647 !important;
                display: flex !important;
                align-items: center !important;
                justify-content: center !important;
                font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif !important;
            `;
            
            // Create modal container
            const modal = document.createElement('div');
            modal.className = className;
            modal.style.cssText = `
                background: linear-gradient(145deg, #1a1f2e, #0d1117) !important;
                border: 2px solid rgba(139, 92, 246, 0.4) !important;
                border-radius: 16px !important;
                padding: 24px !important;
                width: ${width} !important;
                max-width: 95vw !important;
                max-height: 90vh !important;
                overflow-y: auto !important;
                box-shadow: 0 25px 80px rgba(0,0,0,0.5) !important;
                color: #e2e8f0 !important;
            `;
            
            // Build modal content using DOM (TrustedTypes safe)
            if (title) {
                const header = document.createElement('div');
                header.style.cssText = 'display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;padding-bottom:12px;border-bottom:1px solid rgba(255,255,255,0.1);';
                
                const titleEl = document.createElement('h3');
                titleEl.style.cssText = 'margin:0;color:#e2e8f0;font-size:18px;font-weight:700;';
                titleEl.textContent = title;
                header.appendChild(titleEl);
                
                if (closable) {
                    const closeBtn = document.createElement('button');
                    closeBtn.style.cssText = 'background:rgba(255,255,255,0.1);border:none;color:#94a3b8;width:32px;height:32px;border-radius:8px;cursor:pointer;font-size:18px;';
                    closeBtn.textContent = '×';
                    closeBtn.onclick = () => overlay.remove();
                    header.appendChild(closeBtn);
                }
                
                modal.appendChild(header);
            }
            
            // Add content
            const contentContainer = document.createElement('div');
            if (typeof content === 'string') {
                // Use safe innerHTML
                if (typeof window.__NEXUS_SET_HTML__ === 'function') {
                    window.__NEXUS_SET_HTML__(contentContainer, content);
                } else {
                    // DOMParser fallback
                    try {
                        const parser = new DOMParser();
                        const doc = parser.parseFromString(`<body>${content}</body>`, 'text/html');
                        Array.from(doc.body.childNodes).forEach(node => {
                            contentContainer.appendChild(document.importNode(node, true));
                        });
                    } catch (e) {
                        contentContainer.textContent = content.replace(/<[^>]*>/g, '');
                    }
                }
            } else if (content instanceof HTMLElement) {
                contentContainer.appendChild(content);
            }
            modal.appendChild(contentContainer);
            
            overlay.appendChild(modal);
            
            // Close on overlay click
            if (closable) {
                overlay.onclick = (e) => {
                    if (e.target === overlay) overlay.remove();
                };
            }
            
            // Add to page using multiple methods
            try {
                document.body.appendChild(overlay);
            } catch (e) {
                try {
                    document.documentElement.appendChild(overlay);
                } catch (e2) {
                    // Use shadow DOM if available
                    const host = document.createElement('div');
                    const shadow = host.attachShadow({ mode: 'open' });
                    shadow.appendChild(overlay);
                    document.body.appendChild(host);
                }
            }
            
            return { overlay, modal, close: () => overlay.remove() };
        },
        
        // Show notification toast
        toast(message, type = 'info', duration = 3000) {
            const colors = {
                info: '#3b82f6',
                success: '#22c55e',
                warning: '#f59e0b',
                error: '#ef4444'
            };
            
            const toast = document.createElement('div');
            toast.style.cssText = `
                position: fixed !important;
                bottom: 20px !important;
                right: 20px !important;
                background: ${colors[type] || colors.info} !important;
                color: white !important;
                padding: 12px 20px !important;
                border-radius: 8px !important;
                font-family: -apple-system, sans-serif !important;
                font-size: 14px !important;
                z-index: 2147483647 !important;
                box-shadow: 0 4px 20px rgba(0,0,0,0.3) !important;
                animation: nexusSlideIn 0.3s ease !important;
            `;
            toast.textContent = message;
            
            // Add animation style
            if (!document.getElementById('nexus-toast-style')) {
                const style = document.createElement('style');
                style.id = 'nexus-toast-style';
                style.textContent = `
                    @keyframes nexusSlideIn {
                        from { transform: translateX(100%); opacity: 0; }
                        to { transform: translateX(0); opacity: 1; }
                    }
                `;
                document.head.appendChild(style);
            }
            
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), duration);
        }
    };
    
    // ═══════════════════════════════════════════════════════════════════════════
    // SECTION 9: ADVANCED AUTO-RECONNECT SYSTEM v2.0
    // Uses SmartKeyRouter and TunnelHealthChecker for smart reconnection
    // ═══════════════════════════════════════════════════════════════════════════
    
    const ConnectionManager = {
        // Terminal connection state
        terminal: {
            url: null,
            token: null,
            ws: null,
            retryCount: 0,
            maxRetries: 15,  // Increased
            retryDelay: 2000,  // Start slower
            isConnecting: false,
            lastError: null,
            connectedTime: null,
            healthCheckInterval: null
        },
        
        // AI connection state  
        ai: {
            provider: null,
            apiKey: null,
            retryCount: 0,
            maxRetries: 5,
            lastError: null,
            isValidated: false,
            lastValidation: null
        },
        
        // Save connection info persistently
        saveTerminalCredentials(url, token) {
            if (url) {
                localStorage.setItem('nexus_terminal_url', url);
                this.terminal.url = url;
            }
            if (token) {
                localStorage.setItem('nexus_terminal_token', token);
                this.terminal.token = token;
            }
            localStorage.setItem('nexus_terminal_connected_time', Date.now().toString());
        },
        
        // CRITICAL FIX: Smart AI connect that ALWAYS uses correct provider
        async connectAI(apiKey, forceProvider = null) {
            const key = apiKey || localStorage.getItem('nexus_ai_key') || window.AIAgent?.config?.apiKey;
            
            if (!key) {
                console.log('%c[NEXUS] ❌ No AI API key found', 'color: #f43f5e;');
                return false;
            }
            
            // CRITICAL: Use SmartKeyRouter to detect correct provider
            const detectedProvider = SmartKeyRouter.detectProvider(key);
            const provider = forceProvider || detectedProvider;
            
            // Log the detection for debugging
            const diagnosis = SmartKeyRouter.diagnoseKey(key);
            console.log(`%c[NEXUS] 🔍 Key Analysis:`, 'color: #818cf8; font-weight: bold;');
            console.log(`%c   Key: ${diagnosis.key}`, 'color: #94a3b8;');
            console.log(`%c   Detected: ${diagnosis.icon} ${diagnosis.providerName}`, 'color: #22c55e;');
            console.log(`%c   Endpoint: ${diagnosis.endpoint}`, 'color: #94a3b8;');
            
            // Save to storage (DON'T test - may fail due to CSP)
            localStorage.setItem('nexus_ai_key', key);
            localStorage.setItem('nexus_ai_provider', provider);
            
            this.ai.apiKey = key;
            this.ai.provider = provider;
            this.ai.isValidated = true;  // Trust user's key without testing
            
            // Update AIAgent if it exists
            if (window.AIAgent) {
                window.AIAgent.config.apiKey = key;
                window.AIAgent.config.provider = provider;
                window.AIAgent.config.isActive = true;
                
                // Force the provider configuration
                const config = SmartKeyRouter.getConfig(provider);
                if (config && window.AIAgent.providers[provider]) {
                    window.AIAgent.providers[provider].model = config.model;
                }
            }
            
            // DON'T test connection - CSP will block it on most sites
            // AI will be tested when actually used
            console.log(`%c[NEXUS] ✅ AI Configured: ${diagnosis.icon} ${diagnosis.providerName}`, 'color: #22c55e; font-weight: bold;');
            console.log(`%c[NEXUS] ℹ️ Note: Direct API calls may be blocked by CSP on this site.`, 'color: #94a3b8;');
            console.log(`%c[NEXUS] ℹ️ Use Terminal Bridge to route AI through your server.`, 'color: #94a3b8;');
            return true;
        },
        
        // Test AI connection with correct endpoint
        async testAIConnection(key, provider) {
            const request = SmartKeyRouter.formatRequest(key, 'Say OK', provider);
            
            try {
                const response = await fetch(request.url, {
                    method: 'POST',
                    headers: request.headers,
                    body: JSON.stringify(request.body)
                });
                
                if (!response.ok) {
                    const errorText = await response.text();
                    return { success: false, error: `HTTP ${response.status}: ${errorText.substring(0, 100)}` };
                }
                
                const data = await response.json();
                const text = SmartKeyRouter.parseResponse(data, provider);
                
                if (text) {
                    return { success: true, response: text };
                } else {
                    return { success: false, error: 'Empty response from AI' };
                }
            } catch (e) {
                return { success: false, error: e.message };
            }
        },
        
        // Connect to terminal with smart retry and tunnel health checking
        async connectTerminal(url, token, options = {}) {
            const { forceReconnect = false, silent = false } = options;
            
            // Get credentials (priority: params > saved > existing)
            const targetUrl = url || localStorage.getItem('nexus_terminal_url') || this.terminal.url;
            const targetToken = token || localStorage.getItem('nexus_terminal_token') || this.terminal.token;
            
            if (!targetUrl || !targetToken) {
                if (!silent) {
                    console.log('%c[NEXUS] ❌ No terminal credentials', 'color: #f43f5e;');
                    console.log('%c   Run: connectTerminal("wss://xxx.trycloudflare.com", "TOKEN")', 'color: #94a3b8;');
                }
                return false;
            }
            
            // Check tunnel health first
            const tunnelHealth = await TunnelHealthChecker.checkTunnel(targetUrl);
            
            if (!tunnelHealth.isAlive) {
                if (!silent) {
                    console.log('%c[NEXUS] ⚠️ Tunnel health check failed:', 'color: #f59e0b;');
                    console.log(`%c   ${tunnelHealth.suggestion || tunnelHealth.error}`, 'color: #94a3b8;');
                    
                    if (tunnelHealth.isExpired) {
                        console.log('%c\n   🔄 SOLUTION: Restart nexus-terminal.js to get a NEW URL!', 'color: #22c55e; font-weight: bold;');
                    }
                }
                
                // Still try to connect (tunnel might be partially down)
            }
            
            // Check if already connected
            if (!forceReconnect && window.TerminalBridge?.isConnected?.()) {
                if (!silent) console.log('%c[NEXUS] ✅ Terminal already connected', 'color: #22c55e;');
                return true;
            }
            
            if (this.terminal.isConnecting) {
                return false;
            }
            
            this.terminal.isConnecting = true;
            
            // Save credentials for auto-reconnect
            this.saveTerminalCredentials(targetUrl, targetToken);
            
            try {
                // Use the main TerminalBridge.connect if available
                if (window.TerminalBridge?.connect) {
                    const result = await window.TerminalBridge.connect(targetUrl, targetToken);
                    this.terminal.isConnecting = false;
                    
                    if (result || window.TerminalBridge.isConnected?.()) {
                        this.terminal.retryCount = 0;
                        this.terminal.connectedTime = Date.now();
                        
                        // Setup health check interval
                        this.setupTerminalHealthCheck();
                        
                        if (!silent) console.log('%c[NEXUS] ✅ Terminal connected!', 'color: #22c55e; font-weight: bold;');
                        return true;
                    }
                }
                
                throw new Error('Connection failed');
                
            } catch (error) {
                this.terminal.lastError = error.message;
                this.terminal.retryCount++;
                this.terminal.isConnecting = false;
                
                if (this.terminal.retryCount < this.terminal.maxRetries) {
                    const delay = Math.min(this.terminal.retryDelay * Math.pow(1.5, this.terminal.retryCount), 60000);
                    if (!silent) {
                        console.log(`%c[NEXUS] Terminal retry ${this.terminal.retryCount}/${this.terminal.maxRetries} in ${Math.round(delay/1000)}s`, 'color: #f59e0b;');
                    }
                    setTimeout(() => this.connectTerminal(null, null, { silent: true }), delay);
                } else {
                    if (!silent) {
                        console.log('%c[NEXUS] ❌ Terminal connection failed after max retries', 'color: #f43f5e;');
                        console.log('%c   The Cloudflare tunnel may have expired (24h limit)', 'color: #94a3b8;');
                        console.log('%c   Run nexus-terminal.js again to get a new URL', 'color: #22c55e;');
                    }
                }
                
                return false;
            }
        },
        
        // Setup periodic health check for terminal
        setupTerminalHealthCheck() {
            // Clear existing interval
            if (this.terminal.healthCheckInterval) {
                clearInterval(this.terminal.healthCheckInterval);
            }
            
            // Check every 30 seconds
            this.terminal.healthCheckInterval = setInterval(async () => {
                if (!window.TerminalBridge?.isConnected?.()) {
                    console.log('%c[NEXUS] Terminal disconnected, attempting reconnect...', 'color: #f59e0b;');
                    this.terminal.retryCount = 0;  // Reset for fresh reconnect
                    await this.connectTerminal(null, null, { silent: false });
                }
            }, 30000);
        },
        
        // Auto-reconnect all with smarter logic
        async autoReconnect() {
            // Check AI first (quick)
            const savedKey = localStorage.getItem('nexus_ai_key');
            if (savedKey && !this.ai.isValidated) {
                await this.connectAI(savedKey);
            }
            
            // Check terminal
            if (!window.TerminalBridge?.isConnected?.()) {
                await this.connectTerminal(null, null, { silent: true });
            }
        },
        
        // Get connection status
        getStatus() {
            const terminalConnected = window.TerminalBridge?.isConnected?.() || false;
            const aiConnected = this.ai.isValidated && this.ai.apiKey;
            const tunnelAge = TunnelHealthChecker.getTunnelAge();
            
            return {
                terminal: {
                    connected: terminalConnected,
                    url: this.terminal.url,
                    retryCount: this.terminal.retryCount,
                    lastError: this.terminal.lastError,
                    tunnelAge: tunnelAge?.ageHours,
                    tunnelExpiringSoon: tunnelAge?.isExpiringSoon
                },
                ai: {
                    connected: aiConnected,
                    provider: this.ai.provider,
                    validated: this.ai.isValidated,
                    lastError: this.ai.lastError
                }
            };
        }
    };
    
    // ═══════════════════════════════════════════════════════════════════════════
    // SECTION 10: SUPER SELF-HEALING SYSTEM v2.0
    // Comprehensive diagnostics for AI, Terminal, and Environment issues
    // ═══════════════════════════════════════════════════════════════════════════
    
    const SelfHealer = {
        issues: [],
        fixes: [],
        lastDiagnosis: null,
        
        // COMPREHENSIVE DIAGNOSIS - checks EVERYTHING
        async diagnose() {
            this.issues = [];
            this.lastDiagnosis = Date.now();
            
            // ===== ENVIRONMENT ISSUES =====
            
            // Check TrustedTypes
            if (ENV.security.hasTrustedTypes && !window.__NEXUS_POLICY__) {
                this.issues.push({ 
                    id: 'trustedtypes',
                    category: 'environment',
                    severity: 'high',
                    message: '🔒 TrustedTypes blocking innerHTML',
                    fix: this.fixTrustedTypes,
                    autoFix: true
                });
            }
            
            // Check console
            if (ENV.console.isModified) {
                this.issues.push({
                    id: 'console',
                    category: 'environment',
                    severity: 'medium',
                    message: '📝 Console methods modified by site',
                    fix: this.fixConsole,
                    autoFix: true
                });
            }
            
            // Check storage
            if (!ENV.storage.hasLocalStorage) {
                this.issues.push({
                    id: 'storage',
                    category: 'environment',
                    severity: 'medium',
                    message: '💾 LocalStorage blocked',
                    fix: this.fixStorage,
                    autoFix: true
                });
            }
            
            // Check WebSocket
            if (!ENV.network.hasWebSocket) {
                this.issues.push({
                    id: 'websocket',
                    category: 'environment',
                    severity: 'high',
                    message: '🔌 WebSocket not available',
                    fix: this.fixWebSocket,
                    autoFix: false
                });
            }
            
            // Check DOM manipulation
            try {
                const testEl = document.createElement('div');
                testEl.style.cssText = 'position:fixed;z-index:9999;';
                document.body.appendChild(testEl);
                document.body.removeChild(testEl);
            } catch (e) {
                this.issues.push({
                    id: 'dom',
                    category: 'environment',
                    severity: 'high',
                    message: '🖼️ DOM manipulation blocked',
                    fix: this.fixDOM,
                    autoFix: true
                });
            }
            
            // ===== AI CONNECTION ISSUES =====
            
            const savedKey = localStorage.getItem('nexus_ai_key');
            const savedProvider = localStorage.getItem('nexus_ai_provider');
            
            if (savedKey) {
                // Check if key format matches provider
                const detectedProvider = SmartKeyRouter.detectProvider(savedKey);
                if (savedProvider && savedProvider !== detectedProvider) {
                    this.issues.push({
                        id: 'ai_mismatch',
                        category: 'ai',
                        severity: 'critical',
                        message: `🤖 API KEY MISMATCH! Key is ${SmartKeyRouter.getConfig(detectedProvider).name} but configured as ${SmartKeyRouter.getConfig(savedProvider).name}`,
                        fix: () => this.fixAIMismatch(savedKey, detectedProvider),
                        autoFix: true,
                        details: {
                            savedProvider,
                            detectedProvider,
                            suggestion: `Will auto-fix to use ${detectedProvider}`
                        }
                    });
                }
                
                // Check if AI is actually working (DON'T auto-test - causes CSP errors on some sites)
                if (!ConnectionManager.ai.isValidated) {
                    this.issues.push({
                        id: 'ai_not_validated',
                        category: 'ai',
                        severity: 'info',
                        message: '🤖 AI connection not tested yet',
                        fix: null,
                        autoFix: false,
                        details: {
                            suggestion: 'AI will be tested when you use it. CSP may block direct API calls.'
                        }
                    });
                }
            } else {
                this.issues.push({
                    id: 'ai_no_key',
                    category: 'ai',
                    severity: 'info',
                    message: '🤖 No AI API key configured',
                    fix: null,
                    autoFix: false,
                    details: {
                        suggestion: 'Run setAI("YOUR_API_KEY") to configure AI'
                    }
                });
            }
            
            // ===== TERMINAL CONNECTION ISSUES =====
            
            const savedUrl = localStorage.getItem('nexus_terminal_url');
            const savedToken = localStorage.getItem('nexus_terminal_token');
            
            if (savedUrl) {
                // Check if terminal is connected
                const isConnected = window.TerminalBridge?.isConnected?.() || false;
                
                if (!isConnected) {
                    // Check tunnel health
                    const tunnelDiagnosis = await TunnelHealthChecker.diagnose();
                    
                    if (tunnelDiagnosis.status === 'EXPIRED') {
                        this.issues.push({
                            id: 'tunnel_expired',
                            category: 'terminal',
                            severity: 'critical',
                            message: `🔌 Cloudflare tunnel EXPIRED (${tunnelDiagnosis.age?.ageHours || '?'}h old)`,
                            fix: null,
                            autoFix: false,
                            details: {
                                url: savedUrl,
                                suggestions: tunnelDiagnosis.suggestions
                            }
                        });
                    } else if (tunnelDiagnosis.status === 'EXPIRING_SOON') {
                        this.issues.push({
                            id: 'tunnel_expiring',
                            category: 'terminal',
                            severity: 'warning',
                            message: `⚠️ Tunnel expiring soon (${tunnelDiagnosis.age?.ageHours}h old)`,
                            fix: null,
                            autoFix: false,
                            details: {
                                suggestion: 'Run connectTerminal() to reconnect'
                            }
                        });
                    } else if (tunnelDiagnosis.status === 'DISCONNECTED') {
                        this.issues.push({
                            id: 'terminal_disconnected',
                            category: 'terminal',
                            severity: 'info',
                            message: '🔌 Terminal disconnected',
                            fix: null,
                            autoFix: false,
                            details: {
                                suggestion: 'Run connectTerminal("ws://...", "TOKEN") to connect'
                            }
                        });
                    }
                }
            } else {
                this.issues.push({
                    id: 'terminal_no_config',
                    category: 'terminal',
                    severity: 'info',
                    message: '🔌 No terminal URL configured',
                    fix: null,
                    autoFix: false,
                    details: {
                        suggestion: 'Run connectTerminal("wss://xxx.trycloudflare.com", "TOKEN")'
                    }
                });
            }
            
            return this.issues;
        },
        
        // Fix AI provider mismatch
        fixAIMismatch(key, correctProvider) {
            localStorage.setItem('nexus_ai_provider', correctProvider);
            if (window.AIAgent) {
                window.AIAgent.config.provider = correctProvider;
            }
            ConnectionManager.ai.provider = correctProvider;
            console.log(`%c[NEXUS] ✅ Fixed AI provider to: ${correctProvider}`, 'color: #22c55e;');
            return true;
        },
        
        // Fix TrustedTypes
        fixTrustedTypes() {
            try {
                if (window.trustedTypes?.createPolicy) {
                    const id = Date.now().toString(36) + Math.random().toString(36).substr(2);
                    window.__NEXUS_POLICY__ = window.trustedTypes.createPolicy('nexus-' + id, {
                        createHTML: s => s,
                        createScript: s => s,
                        createScriptURL: s => s
                    });
                    return true;
                }
            } catch (e) {}
            return false;
        },
        
        // Fix console
        fixConsole() {
            try {
                const iframe = document.createElement('iframe');
                iframe.style.display = 'none';
                document.body.appendChild(iframe);
                Object.keys(console).forEach(k => {
                    if (iframe.contentWindow.console[k]) {
                        console[k] = iframe.contentWindow.console[k].bind(iframe.contentWindow.console);
                    }
                });
                document.body.removeChild(iframe);
                return true;
            } catch (e) {}
            return false;
        },
        
        // Fix storage
        fixStorage() {
            if (!ENV.storage.hasLocalStorage) {
                window.__NEXUS_STORAGE__ = {};
                window.localStorage = {
                    getItem: (k) => window.__NEXUS_STORAGE__[k] || null,
                    setItem: (k, v) => window.__NEXUS_STORAGE__[k] = String(v),
                    removeItem: (k) => delete window.__NEXUS_STORAGE__[k],
                    clear: () => window.__NEXUS_STORAGE__ = {},
                    get length() { return Object.keys(window.__NEXUS_STORAGE__).length; },
                    key: (i) => Object.keys(window.__NEXUS_STORAGE__)[i] || null
                };
                return true;
            }
            return false;
        },
        
        // Fix WebSocket
        fixWebSocket() {
            if (!window.WebSocket) {
                console.warn('[NEXUS] WebSocket not available, features limited');
                return false;
            }
            return true;
        },
        
        // Fix DOM
        fixDOM() {
            try {
                const host = document.createElement('div');
                host.id = 'nexus-shadow-host';
                const shadow = host.attachShadow({ mode: 'open' });
                document.body.appendChild(host);
                window.__NEXUS_SHADOW__ = shadow;
                return true;
            } catch (e) {}
            return false;
        },
        
        // Heal all auto-fixable issues
        async healAll() {
            await this.diagnose();
            this.fixes = [];
            
            for (const issue of this.issues) {
                if (issue.autoFix && issue.fix) {
                    try {
                        const result = await Promise.resolve(issue.fix.call(this));
                        this.fixes.push({
                            issue: issue.id,
                            message: issue.message,
                            fixed: result
                        });
                    } catch (e) {
                        this.fixes.push({
                            issue: issue.id,
                            message: issue.message,
                            fixed: false,
                            error: e.message
                        });
                    }
                }
            }
            
            return this.fixes;
        },
        
        // Print detailed diagnostic report
        async printDiagnosticReport() {
            await this.diagnose();
            
            console.log('%c╔══════════════════════════════════════════════════════════════════╗', 'color: #818cf8;');
            console.log('%c║              🔧 NEXUS DIAGNOSTIC REPORT                          ║', 'color: #818cf8; font-weight: bold;');
            console.log('%c╚══════════════════════════════════════════════════════════════════╝', 'color: #818cf8;');
            
            // Group by category
            const categories = {
                environment: { name: '🌐 Environment', issues: [] },
                ai: { name: '🤖 AI Connection', issues: [] },
                terminal: { name: '🔌 Terminal', issues: [] }
            };
            
            for (const issue of this.issues) {
                const cat = categories[issue.category] || categories.environment;
                cat.issues.push(issue);
            }
            
            // Print each category
            for (const [catKey, cat] of Object.entries(categories)) {
                if (cat.issues.length === 0) {
                    console.log(`%c\n${cat.name}: ✅ All OK`, 'color: #22c55e; font-weight: bold;');
                } else {
                    console.log(`%c\n${cat.name}:`, 'color: #f59e0b; font-weight: bold;');
                    for (const issue of cat.issues) {
                        const sevColors = {
                            critical: '#f43f5e',
                            high: '#ef4444',
                            medium: '#f59e0b',
                            warning: '#f59e0b',
                            low: '#3b82f6',
                            info: '#94a3b8'
                        };
                        const color = sevColors[issue.severity] || '#94a3b8';
                        console.log(`%c   [${issue.severity.toUpperCase()}] ${issue.message}`, `color: ${color};`);
                        
                        if (issue.details?.suggestion) {
                            console.log(`%c      → ${issue.details.suggestion}`, 'color: #22c55e;');
                        }
                        if (issue.details?.suggestions) {
                            issue.details.suggestions.forEach(s => {
                                console.log(`%c      → ${s}`, 'color: #94a3b8;');
                            });
                        }
                    }
                }
            }
            
            // Summary
            const criticalCount = this.issues.filter(i => i.severity === 'critical').length;
            const autoFixable = this.issues.filter(i => i.autoFix).length;
            
            console.log('%c\n═══════════════════════════════════════════════════════════════════', 'color: #475569;');
            console.log(`%c   Total Issues: ${this.issues.length} | Critical: ${criticalCount} | Auto-fixable: ${autoFixable}`, 'color: #94a3b8;');
            
            if (autoFixable > 0) {
                console.log('%c   Run heal() to auto-fix issues', 'color: #22c55e; font-weight: bold;');
            }
            
            return this.issues;
        },
        
        // Quick status check
        getStatus() {
            return {
                lastDiagnosis: this.lastDiagnosis,
                issueCount: this.issues.length,
                criticalIssues: this.issues.filter(i => i.severity === 'critical'),
                fixResults: this.fixes
            };
        }
    };
    
    // ═══════════════════════════════════════════════════════════════════════════
    // SECTION 11: INITIALIZATION & GLOBAL EXPORTS
    // ═══════════════════════════════════════════════════════════════════════════
    
    function init() {
        // Detect everything (silently)
        try { detectBrowser(); } catch(e) {}
        try { detectSecurity(); } catch(e) {}
        try { protectConsole(); } catch(e) {}
        try { detectNetwork(); } catch(e) {}
        try { detectStorage(); } catch(e) {}
        try { detectFeatures(); } catch(e) {}
        
        // DON'T auto-connect on load - user must manually call connectTerminal()
        // This prevents CSP errors and unwanted connection attempts
        
        // Log environment info
        console.log(`%c[NEXUS] Environment: ${ENV.browser.name} v${ENV.browser.version} (${ENV.browser.engine})`, 'color: #818cf8;');
        console.log(`%c[NEXUS] Security: CSP=${ENV.security.hasCSP}, TrustedTypes=${ENV.security.hasTrustedTypes}`, 'color: #818cf8;');
        
        return { ENV, UIAdapter, ConnectionManager, SelfHealer, SmartKeyRouter, TunnelHealthChecker };
    }
    
    // Initialize and export
    const instance = init();
    
    // Global exports - all components accessible
    window.__NEXUS_ENV__ = ENV;
    window.__NEXUS_UI__ = UIAdapter;
    window.__NEXUS_CONNECTION__ = ConnectionManager;
    window.__NEXUS_HEALER__ = SelfHealer;
    window.__NEXUS_KEY_ROUTER__ = SmartKeyRouter;
    window.__NEXUS_TUNNEL__ = TunnelHealthChecker;
    
    // ═══════════════════════════════════════════════════════════════════════════
    // GLOBAL CONVENIENCE FUNCTIONS (Easy Access)
    // ═══════════════════════════════════════════════════════════════════════════
    
    // Full diagnostic - shows all issues with AI, Terminal, and Environment
    window.diagnose = async function() {
        return await SelfHealer.printDiagnosticReport();
    };
    
    // Auto-heal all fixable issues
    window.heal = async function() {
        console.log('%c🔧 Running auto-heal...', 'color: #818cf8; font-weight: bold;');
        const results = await SelfHealer.healAll();
        
        const fixed = results.filter(r => r.fixed).length;
        const failed = results.filter(r => !r.fixed).length;
        
        console.log(`%c✅ Fixed: ${fixed} | ❌ Failed: ${failed}`, 
            fixed > 0 ? 'color: #22c55e;' : 'color: #f59e0b;');
        
        if (results.length > 0) {
            console.table(results);
        }
        
        return results;
    };
    
    // Reconnect terminal and AI
    window.reconnect = async function() {
        console.log('%c🔄 Reconnecting all services...', 'color: #818cf8; font-weight: bold;');
        
        // Reset retry counts
        ConnectionManager.terminal.retryCount = 0;
        ConnectionManager.ai.isValidated = false;
        
        // Reconnect
        await ConnectionManager.autoReconnect();
        
        // Show status
        const status = ConnectionManager.getStatus();
        console.log(`%cTerminal: ${status.terminal.connected ? '✅ Connected' : '❌ Disconnected'}`, 
            status.terminal.connected ? 'color: #22c55e;' : 'color: #f43f5e;');
        console.log(`%cAI: ${status.ai.connected ? '✅ Connected' : '❌ Not connected'}`,
            status.ai.connected ? 'color: #22c55e;' : 'color: #f43f5e;');
        
        return status;
    };
    
    // Quick status check
    window.nexusStatus = function() {
        const connStatus = ConnectionManager.getStatus();
        const healStatus = SelfHealer.getStatus();
        
        console.log('%c╔══════════════════════════════════════════════════════════════════╗', 'color: #818cf8;');
        console.log('%c║                    📊 NEXUS STATUS                               ║', 'color: #818cf8; font-weight: bold;');
        console.log('%c╚══════════════════════════════════════════════════════════════════╝', 'color: #818cf8;');
        
        // Terminal
        console.log(`%c\n🔌 Terminal: ${connStatus.terminal.connected ? '✅ CONNECTED' : '❌ DISCONNECTED'}`, 
            connStatus.terminal.connected ? 'color: #22c55e; font-weight: bold;' : 'color: #f43f5e; font-weight: bold;');
        if (connStatus.terminal.url) {
            console.log(`%c   URL: ${connStatus.terminal.url.substring(0, 50)}...`, 'color: #94a3b8;');
        }
        if (connStatus.terminal.tunnelAge) {
            const ageColor = connStatus.terminal.tunnelExpiringSoon ? '#f59e0b' : '#94a3b8';
            console.log(`%c   Tunnel Age: ${connStatus.terminal.tunnelAge}h ${connStatus.terminal.tunnelExpiringSoon ? '⚠️ EXPIRING SOON!' : ''}`, `color: ${ageColor};`);
        }
        
        // AI
        console.log(`%c\n🤖 AI: ${connStatus.ai.connected ? '✅ CONNECTED' : '❌ NOT CONFIGURED'}`,
            connStatus.ai.connected ? 'color: #22c55e; font-weight: bold;' : 'color: #f43f5e; font-weight: bold;');
        if (connStatus.ai.provider) {
            const config = SmartKeyRouter.getConfig(connStatus.ai.provider);
            console.log(`%c   Provider: ${config.icon} ${config.name}`, 'color: #94a3b8;');
        }
        
        // Issues
        if (healStatus.issueCount > 0) {
            console.log(`%c\n⚠️ Issues: ${healStatus.issueCount} (${healStatus.criticalIssues.length} critical)`, 'color: #f59e0b;');
            console.log('%c   Run diagnose() for details, heal() to fix', 'color: #94a3b8;');
        } else {
            console.log('%c\n✅ No issues detected', 'color: #22c55e;');
        }
        
        console.log('%c\n═══════════════════════════════════════════════════════════════════', 'color: #475569;');
        
        return { connection: connStatus, health: healStatus };
    };
    
    // Check API key and show what provider it's for
    window.checkKey = function(key) {
        if (!key) {
            key = localStorage.getItem('nexus_ai_key');
            if (!key) {
                console.log('%c❌ No key provided. Usage: checkKey("YOUR_API_KEY")', 'color: #f43f5e;');
                return;
            }
        }
        
        const diagnosis = SmartKeyRouter.diagnoseKey(key);
        
        console.log('%c╔══════════════════════════════════════════════════════════════════╗', 'color: #818cf8;');
        console.log('%c║                    🔑 API KEY ANALYSIS                           ║', 'color: #818cf8; font-weight: bold;');
        console.log('%c╚══════════════════════════════════════════════════════════════════╝', 'color: #818cf8;');
        console.log(`%c   Key: ${diagnosis.key}`, 'color: #94a3b8;');
        console.log(`%c   Detected Provider: ${diagnosis.icon} ${diagnosis.providerName}`, 'color: #22c55e; font-weight: bold;');
        console.log(`%c   API Endpoint: ${diagnosis.endpoint}`, 'color: #94a3b8;');
        console.log(`%c   Format Valid: ${diagnosis.isValidFormat ? '✅ Yes' : '⚠️ No'}`, 
            diagnosis.isValidFormat ? 'color: #22c55e;' : 'color: #f59e0b;');
        console.log(`%c   ${diagnosis.suggestion}`, 'color: #3b82f6;');
        
        return diagnosis;
    };
    
    // Check tunnel health
    window.checkTunnel = async function() {
        console.log('%c🔍 Checking tunnel health...', 'color: #818cf8;');
        const diagnosis = await TunnelHealthChecker.diagnose();
        
        console.log(`%c\n${diagnosis.message}`, 
            diagnosis.status === 'HEALTHY' ? 'color: #22c55e; font-weight: bold;' : 
            diagnosis.status === 'EXPIRED' ? 'color: #f43f5e; font-weight: bold;' : 
            'color: #f59e0b; font-weight: bold;');
        
        if (diagnosis.suggestions?.length > 0) {
            console.log('%c\nSuggestions:', 'color: #3b82f6; font-weight: bold;');
            diagnosis.suggestions.forEach(s => console.log(`%c   ${s}`, 'color: #94a3b8;'));
        }
        
        return diagnosis;
    };
    
    return instance;
})();

