                // Sections
                listCritical: document.getElementById('list-critical'),
                listLive: document.getElementById('list-live'),
                listPending: document.getElementById('list-pending'),
                listExploitable: document.getElementById('list-exploitable'),
                cntCritical: document.getElementById('cnt-critical'),
                cntLive: document.getElementById('cnt-live'),
                cntPending: document.getElementById('cnt-pending'),
                cntExploitable: document.getElementById('cnt-exploitable'),
                exploitResults: document.getElementById('exploit-results'),
                sessionInfo: document.getElementById('session-info'),
                // Terminal Control Elements
                terminalCtrl: document.getElementById('nx-terminal-ctrl'),
                termStatus: document.getElementById('nx-term-status'),
