        // MONGODB
        // ══════════════════════════════════════════════════════════════
        MONGODB_URI: async (uri) => {
            // Parse URI to check format
            if (uri.includes('@') && uri.includes('mongodb')) {
                const [, userPass] = uri.match(/:\/\/([^@]+)@/) || [];
                if (userPass) {
                    const [user] = userPass.split(':');
                    return { 
                        live: true, 
                        message: `⚠️ MongoDB URI with credentials! User: ${user}`,
                        exploitable: true
                    };
                }
            }
            return { live: false, message: 'MongoDB URI detected', pending: true };
        },

