// ══════════════════════════════════════════════════════════════════════════════
// SECTION 1: MULTI-PROVIDER AI CONFIGURATION WITH CSP BYPASS
// ══════════════════════════════════════════════════════════════════════════════

// ══════════════════════════════════════════════════════════════════════════════
// BROWSER AI MEMORY SYSTEM - Persistent learning in localStorage
// ══════════════════════════════════════════════════════════════════════════════

const BrowserAIMemory = {
    STORAGE_KEY: 'nexus_ai_memory',
    
    // Default data structure
    data: {
        learnedPatterns: [],
        tokenDatabase: {},
        serviceSignatures: {},
        totalTokensAnalyzed: 0,
        totalExploitsFound: 0,
        lastUpdated: null,
        aiConversations: [],
        version: '1.0'
    },
    
    // Load from localStorage
    load() {
        try {
            const saved = localStorage.getItem(this.STORAGE_KEY);
            if (saved) {
                const parsed = JSON.parse(saved);
                this.data = { ...this.data, ...parsed };
                console.log(`%c📚 AI Memory loaded: ${this.data.totalTokensAnalyzed} tokens, ${this.data.totalExploitsFound} exploits`, 'color: #22c55e;');
                return true;
            }
        } catch(e) {
            console.log('%c⚠️ Could not load AI memory', 'color: #f59e0b;');
        }
        return false;
    },
    
    // Save to localStorage
    save() {
        try {
            this.data.lastUpdated = new Date().toISOString();
            localStorage.setItem(this.STORAGE_KEY, JSON.stringify(this.data));
            return true;
        } catch(e) {
            console.log('%c⚠️ Could not save AI memory', 'color: #f59e0b;');
            return false;
        }
    },
    
    // Learn from a token
    learnFromToken(token, type, analysis, result) {
        const hash = this.hashToken(token);
        
        this.data.tokenDatabase[hash] = {
            type,
            prefix: token.substring(0, 10),
            length: token.length,
            analysis: analysis ? {
                service: analysis.service,
                impact: analysis.impact,
                risk: analysis.risk
            } : null,
            result: result ? {
                success: result.success,
                live: result.live
            } : null,
            timestamp: new Date().toISOString()
        };
        
        this.data.totalTokensAnalyzed++;
        
        if (result?.success || result?.live) {
            this.data.totalExploitsFound++;
            
            // Learn service signature
            const service = analysis?.service || type;
            if (!this.data.serviceSignatures[service]) {
                this.data.serviceSignatures[service] = {
                    patterns: [],
                    prefixes: [],
                    avgLength: 0
                };
            }
            
            const sig = this.data.serviceSignatures[service];
            if (!sig.patterns.includes(type)) sig.patterns.push(type);
            if (!sig.prefixes.includes(token.substring(0, 10))) sig.prefixes.push(token.substring(0, 10));
            sig.avgLength = ((sig.avgLength * (sig.prefixes.length - 1)) + token.length) / sig.prefixes.length;
        }
        
        // Auto-save periodically
        if (this.data.totalTokensAnalyzed % 5 === 0) {
            this.save();
        }
    },
    
    // Record AI conversation
    recordConversation(from, to, message, response) {
        this.data.aiConversations.push({
            from, to,
            message: typeof message === 'string' ? message.substring(0, 500) : JSON.stringify(message).substring(0, 500),
            response: typeof response === 'string' ? response.substring(0, 500) : JSON.stringify(response).substring(0, 500),
            timestamp: new Date().toISOString()
        });
        
        // Keep only last 100 conversations
        if (this.data.aiConversations.length > 100) {
            this.data.aiConversations = this.data.aiConversations.slice(-100);
        }
    },
    
    // Find similar tokens
    findSimilar(token) {
        const prefix = token.substring(0, 10);
        const similar = [];
        
        for (const [hash, data] of Object.entries(this.data.tokenDatabase)) {
            if (data.prefix === prefix || Math.abs(data.length - token.length) < 5) {
                similar.push(data);
            }
        }
        
        return similar;
    },
    
    // Get stats
    getStats() {
        return {
            totalTokens: this.data.totalTokensAnalyzed,
            totalExploits: this.data.totalExploitsFound,
            servicesLearned: Object.keys(this.data.serviceSignatures).length,
            conversationsRecorded: this.data.aiConversations.length,
            lastUpdated: this.data.lastUpdated
        };
    },
    
    // Simple hash
    hashToken(token) {
        let hash = 0;
        for (let i = 0; i < token.length; i++) {
            const char = token.charCodeAt(i);
            hash = ((hash << 5) - hash) + char;
            hash = hash & hash;
        }
        return hash.toString(16);
    },
    
    // Guess token type from pattern
    guessType(token) {
        if (token.startsWith('AKIA')) return 'AWS_ACCESS_KEY_ID';
        if (token.startsWith('AIza')) return 'GOOGLE_API_KEY';
        if (token.startsWith('ghp_')) return 'GITHUB_PAT';
        if (token.startsWith('gho_')) return 'GITHUB_OAUTH';
        if (token.startsWith('sk_live_')) return 'STRIPE_SECRET_KEY';
        if (token.startsWith('sk-ant-')) return 'ANTHROPIC_API_KEY';
        if (token.startsWith('gsk_')) return 'GROQ_API_KEY';
        if (token.startsWith('sk-')) return 'OPENAI_API_KEY';
        if (token.startsWith('xoxb-')) return 'SLACK_BOT_TOKEN';
        if (token.startsWith('xoxp-')) return 'SLACK_USER_TOKEN';
        if (token.includes('.firebaseio.com')) return 'FIREBASE_DB_URL';
        return 'UNKNOWN';
    }
};

