const TokenResearchBrowser = {
    // Service database
    serviceDB: {
        'AWS_ACCESS_KEY_ID': { service: 'Amazon Web Services', bounty: '$500-$5000', impact: 'Full AWS account access' },
        'GOOGLE_API_KEY': { service: 'Google Cloud Platform', bounty: '$100-$1000', impact: 'Depends on enabled APIs' },
        'FIREBASE_API_KEY': { service: 'Firebase', bounty: '$100-$1000', impact: 'Firebase services access' },
        'GITHUB_PAT': { service: 'GitHub', bounty: '$500-$3000', impact: 'Repository access, code commits' },
        'STRIPE_SECRET_KEY': { service: 'Stripe', bounty: '$1000-$5000', impact: 'Payment processing, customer data' },
        'SLACK_BOT_TOKEN': { service: 'Slack', bounty: '$500-$2000', impact: 'Workspace messages, user info' },
        'OPENAI_API_KEY': { service: 'OpenAI', bounty: '$100-$500', impact: 'API billing, model access' },
        'GROQ_API_KEY': { service: 'Groq AI', bounty: '$50-$200', impact: 'API access' },
        'ANTHROPIC_API_KEY': { service: 'Anthropic Claude', bounty: '$100-$500', impact: 'API billing' }
    },
    
    // Research a token
    research(token, type) {
        const info = this.serviceDB[type] || {};
        return {
            token: token.substring(0, 10) + '...',
            type,
            service: info.service || 'Unknown',
            bountyEstimate: info.bounty || 'Unknown',
            impact: info.impact || 'Unknown',
            similar: BrowserAIMemory.findSimilar(token)
        };
    },
    
    // Generate test command hints
    getTestCommands(type, token) {
        const commands = [];
        switch(type) {
            case 'AWS_ACCESS_KEY_ID':
                commands.push(`aws sts get-caller-identity`);
                break;
            case 'GITHUB_PAT':
                commands.push(`curl -H "Authorization: token ${token.substring(0,10)}..." https://api.github.com/user`);
                break;
            case 'STRIPE_SECRET_KEY':
                commands.push(`curl -u ${token.substring(0,10)}...: https://api.stripe.com/v1/balance`);
                break;
            case 'SLACK_BOT_TOKEN':
                commands.push(`curl -H "Authorization: Bearer ${token.substring(0,10)}..." https://slack.com/api/auth.test`);
                break;
        }
        return commands;
    }
};

