    // Get findings by category
    getFindingsByCategory() {
        const vault = window.__NEXUS__?.Vault?.secrets || new Map();
        const categories = {};
        
        for (const [catKey, cat] of Object.entries(this.VULN_CATEGORIES)) {
            categories[catKey] = {
                ...cat,
                findings: [],
                count: 0
            };
        }
        
        vault.forEach((entry, value) => {
            for (const [catKey, cat] of Object.entries(this.VULN_CATEGORIES)) {
                if (cat.patterns.includes(entry.type)) {
                    categories[catKey].findings.push({ value, ...entry });
                    categories[catKey].count++;
                    break;
                }
            }
        });
        
        return categories;
    },

    // Professional Vulnerability Dashboard
    showVulnDashboard() {
        console.clear();
        console.log('%c╔═══════════════════════════════════════════════════════════════════════════════════════════════════════╗', 'color: #f43f5e;');
        console.log('%c║                       🎯 NEXUS VULNERABILITY DASHBOARD - Bug Bounty Hunter Pro                        ║', 'color: #f43f5e; font-weight: bold;');
        console.log('%c║                              Categorized Security Assessment Report                                    ║', 'color: #f43f5e;');
        console.log('%c╚═══════════════════════════════════════════════════════════════════════════════════════════════════════╝', 'color: #f43f5e;');
        console.log('');
        
        const categories = this.getFindingsByCategory();
        const summary = [];
        let totalFindings = 0;
        let criticalCount = 0;
        let highCount = 0;
        let mediumCount = 0;
        let lowCount = 0;
        
        for (const [catKey, cat] of Object.entries(categories)) {
            if (cat.count > 0) {
                totalFindings += cat.count;
                if (cat.severity === 'CRITICAL') criticalCount += cat.count;
                else if (cat.severity === 'HIGH') highCount += cat.count;
                else if (cat.severity === 'MEDIUM') mediumCount += cat.count;
                else lowCount += cat.count;
                
                summary.push({
                    'Category': cat.name,
                    'Severity': cat.severity,
                    'Found': cat.count,
                    'Bounty Range': cat.bountyRange
                });
            }
        }
        
        if (summary.length === 0) {
            console.log('%c⚠️ No vulnerabilities detected yet. Run start() to begin scanning.', 'color: #f59e0b; font-size: 14px;');
            return;
        }
        
        console.log('%c📊 VULNERABILITY SUMMARY BY CATEGORY', 'color: #c084fc; font-weight: bold; font-size: 16px;');
        console.log('');
        console.table(summary);
        
        console.log('');
        console.log('%c╔════════════════════════════════════════════════════════════════════╗', 'color: #22c55e;');
        console.log('%c║                    📈 SEVERITY BREAKDOWN                           ║', 'color: #22c55e; font-weight: bold;');
        console.log('%c╚════════════════════════════════════════════════════════════════════╝', 'color: #22c55e;');
        console.table([{
            '🔴 CRITICAL': criticalCount,
            '🟠 HIGH': highCount,
            '🟡 MEDIUM': mediumCount,
            '🟢 LOW/INFO': lowCount,
            '📊 TOTAL': totalFindings
        }]);
        
        console.log('');
        console.log('%c💡 TIP: Use showCategory("DOM_XSS") to see details of specific category', 'color: #94a3b8;');
        console.log('%c💡 Categories: ' + Object.keys(this.VULN_CATEGORIES).join(', '), 'color: #64748b; font-size: 10px;');
        
        return { categories, summary, totalFindings, criticalCount, highCount, mediumCount, lowCount };
    },

    // Show specific category details
    showCategory(categoryName) {
        console.clear();
        const categories = this.getFindingsByCategory();
        const cat = categories[categoryName?.toUpperCase()];
        
        if (!cat) {
            console.log('%c❌ Invalid category. Available:', 'color: #f43f5e;');
            console.log(Object.keys(this.VULN_CATEGORIES).join(', '));
            return;
        }
        
        console.log(`%c╔══════════════════════════════════════════════════════════════════════════════════════╗`, 'color: #818cf8;');
        console.log(`%c║  ${cat.name.padEnd(80)}║`, 'color: #818cf8; font-weight: bold;');
        console.log(`%c║  Severity: ${cat.severity} | Bounty Range: ${cat.bountyRange.padEnd(55)}║`, 'color: #818cf8;');
        console.log(`%c╚══════════════════════════════════════════════════════════════════════════════════════╝`, 'color: #818cf8;');
        console.log('');
        
        if (cat.findings.length === 0) {
            console.log('%c⚠️ No findings in this category', 'color: #f59e0b;');
            return cat;
        }
        
        const findings = cat.findings.map(f => ({
            'Type': f.type.substring(0, 30),
            'Value Preview': f.value.substring(0, 40) + (f.value.length > 40 ? '...' : ''),
            'Source': f.source.substring(0, 35),
            'Severity': f.severity,
            'Status': f.status || 'pending'
        }));
        
        console.table(findings);
        console.log(`%c\n📊 Total: ${findings.length} findings`, 'color: #22c55e; font-weight: bold;');
        
        return cat;
    },

