    // Get POC for key type
    getPOC(keyType) {
        // Check exact match first
        if (this.pocDatabase[keyType]) return this.pocDatabase[keyType];
        
        // Check partial matches
        for (const [type, poc] of Object.entries(this.pocDatabase)) {
            if (keyType.includes(type) || type.includes(keyType)) {
                return poc;
            }
        }
        
        // Check category matches
        if (keyType.includes('AWS')) return this.pocDatabase.AWS_ACCESS_KEY_ID;
        if (keyType.includes('FIREBASE') || keyType.includes('GCP')) return this.pocDatabase.FIREBASE_API_KEY;
        if (keyType.includes('GITHUB')) return this.pocDatabase.GITHUB_PAT;
        if (keyType.includes('STRIPE')) return this.pocDatabase.STRIPE_SECRET_KEY;
        if (keyType.includes('SLACK')) return this.pocDatabase.SLACK_TOKEN;
        if (keyType.includes('JWT') || keyType.includes('TOKEN')) return this.pocDatabase.JWT_TOKEN;
        if (keyType.includes('MONGO')) return this.pocDatabase.MONGODB_URI;
        if (keyType.includes('POSTGRES') || keyType.includes('MYSQL') || keyType.includes('SQL')) return this.pocDatabase.POSTGRES_URI;
        if (keyType.includes('PRIVATE_KEY') || keyType.includes('RSA')) return this.pocDatabase.PRIVATE_KEY_RSA;
        
        return null;
    },

    async analyzeKeyAdvanced(key, type, source, entry) {
        const poc = this.getPOC(type);
        const keyPreview = key.length > 40 ? key.substring(0, 20) + '...' + key.substring(key.length - 10) : key;
        
        // Build comprehensive prompt
        const prompt = `You are an expert penetration tester analyzing leaked credentials. Analyze this API key/secret and provide exploitation guidance.

TYPE: ${type}
KEY (preview): ${keyPreview}
SOURCE: ${source || 'Web Application'}
ENTROPY: ${entry?.entropy?.toFixed(2) || 'N/A'}
VALIDATION STATUS: ${entry?.status || 'pending'}

Analyze and respond in this EXACT JSON format:
{
    "risk": "CRITICAL/HIGH/MEDIUM/LOW",
    "exploitable": true/false,
    "service": "exact service name",
    "confirmed_type": "actual credential type",
    "impact": "specific impact description",
    "attack_vectors": ["attack 1", "attack 2", "attack 3"],
    "poc_curl": "curl command to test if possible",
    "data_at_risk": "what data could be accessed",
    "remediation": "how to fix/revoke"
}

Be specific and actionable.`;

        const result = await AIAgent.query(prompt, true);
        
        let analysis = null;
        if (result) {
            try {
                const jsonMatch = result.match(/\{[\s\S]*?\}/);
                if (jsonMatch) analysis = JSON.parse(jsonMatch[0]);
            } catch (e) { }
        }

        // Merge with POC database
        if (analysis && poc) {
            analysis.known_poc = poc.commands;
            analysis.known_description = poc.description;
            if (!analysis.risk || analysis.risk === 'UNKNOWN') {
                analysis.risk = poc.risk;
            }
        } else if (poc && !analysis) {
            // Use POC database as fallback
            analysis = {
                risk: poc.risk,
                exploitable: true,
                service: poc.description,
                confirmed_type: type,
                impact: poc.impact,
                attack_vectors: poc.commands.slice(0, 3),
                known_poc: poc.commands,
                data_at_risk: 'See attack vectors',
                remediation: 'Rotate key immediately'
            };
        }

        return analysis;
    },

