            console.log(`%c[${index}/${total}] 🔍 Analyzing: ${entry.type}`, 'color: #c084fc; font-weight: bold; font-size: 13px;');
            console.log(`%c   Key: ${keyPreview}`, 'color: #94a3b8;');
            console.log(`%c   Source: ${entry.source}`, 'color: #64748b;');

            const template = this.getTemplate(entry.type);
            
