// SECTION 5: SCAN CONTROL
// ══════════════════════════════════════════════════════════════════════════════

const ScanController = {
    isScanning: false,
    scanInterval: null,
    
    start() {
        if (this.isScanning) {
            console.log('%c⚠️ Scan already running', 'color: #f59e0b;');
            return;
        }
        
        this.isScanning = true;
        GlobalConfig.isRunning = true;
        console.log('%c▶️ SCAN STARTED - Press STOP to end', 'color: #22c55e; font-weight: bold; font-size: 14px;');
        
        this.updateButton();
        
        // Run initial scan
        if (window.__NEXUS_SCAN__) {
            window.__NEXUS_SCAN__();
        }
        
        // Set up interval for continuous scanning
        this.scanInterval = setInterval(() => {
            if (this.isScanning && GlobalConfig.isRunning && window.__NEXUS_SCAN__) {
                window.__NEXUS_SCAN__();
            }
        }, GlobalConfig.scanInterval);
        
        GlobalConfig.scanIntervalId = this.scanInterval;
    },
    
    stop() {
        this.isScanning = false;
        GlobalConfig.isRunning = false;
        
        if (this.scanInterval) {
            clearInterval(this.scanInterval);
            this.scanInterval = null;
        }
        
        if (GlobalConfig.scanIntervalId) {
            clearInterval(GlobalConfig.scanIntervalId);
            GlobalConfig.scanIntervalId = null;
        }
        
        console.log('%c⏹️ SCAN STOPPED', 'color: #ef4444; font-weight: bold; font-size: 14px;');
        this.updateButton();
        
        // Show summary
        this.showSummary();
    },
    
    showSummary() {
        const vault = window.__NEXUS__?.Vault?.secrets || new Map();
        console.log('%c\n📊 SCAN SUMMARY', 'color: #818cf8; font-weight: bold; font-size: 14px;');
        console.table([{
            'Total Found': vault.size,
            'Status': 'Stopped',
            'Time': new Date().toLocaleTimeString()
        }]);
    },
    
    lastToggleTime: 0,
    
    toggle() {
        // Debounce: prevent rapid toggling (wait 500ms between toggles)
        const now = Date.now();
        if (now - this.lastToggleTime < 500) {
            console.log('%c⚠️ Please wait...', 'color: #f59e0b;');
            return;
        }
        this.lastToggleTime = now;
        
        if (this.isScanning) {
            this.stop();
        } else {
            this.start();
        }
    },
    
    updateButton() {
        const btn = document.getElementById('btn-scan');
        if (btn) {
            // Clear existing content
            while (btn.firstChild) btn.removeChild(btn.firstChild);
            
            // Create icon span
            const icon = document.createElement('span');
            icon.className = 'nx-btn-icon';
            
            if (this.isScanning) {
                icon.textContent = '⏹️';
                btn.appendChild(icon);
                btn.appendChild(document.createTextNode('Stop'));
                btn.style.background = 'linear-gradient(135deg, #ef4444, #dc2626)';
                btn.classList.add('scanning');
            } else {
                icon.textContent = '🔄';
                btn.appendChild(icon);
                btn.appendChild(document.createTextNode('Scan'));
                btn.style.background = 'linear-gradient(135deg, #6366f1, #4f46e5)';
                btn.classList.remove('scanning');
            }
        }
    }
};

