// Safe HTML setter - Uses the UNIVERSAL setInnerHTML from Phase 1
function safeSetHTML(element, html) {
    // Use the universal function if available
    if (typeof window.__NEXUS_SET_HTML__ === 'function') {
        return window.__NEXUS_SET_HTML__(element, html);
    }
    if (typeof window.setInnerHTML === 'function') {
        return window.setInnerHTML(element, html);
    }
    
    // Fallback implementation
    if (!element) return false;
    try {
        // Try with global safeHTML
        if (typeof window.__NEXUS_SAFE_HTML__ === 'function') {
            element.innerHTML = window.__NEXUS_SAFE_HTML__(html);
            return true;
        }
        element.innerHTML = html;
        return true;
    } catch (e) {
        // DOMParser fallback for strict CSP
        try {
            while (element.firstChild) element.removeChild(element.firstChild);
            const parser = new DOMParser();
            const doc = parser.parseFromString(`<body>${html}</body>`, 'text/html');
            Array.from(doc.body.childNodes).forEach(node => {
                element.appendChild(document.importNode(node, true));
            });
            return true;
        } catch (e2) {
            element.textContent = html.replace(/<[^>]*>/g, '');
            return false;
        }
    }
}

