window.connectAI = async function() {
    const key = document.getElementById('ai-key-input')?.value?.trim();
    
    if (!key) {
        alert('Please enter an API key');
        return;
    }
    
    closeAIModal();
    const result = await AIAgent.init(key, selectedProvider);
    if (!result) {
        console.log('%c💡 TIP: Get a free Gemini API key from: https://aistudio.google.com/app/apikey', 'color: #818cf8;');
    } else {
        // ═══ AUTO-CONNECT TO NEXUS TERMINAL ═══
        console.log('%c\n🔗 AI Connected — Attempting auto-connect to Nexus Terminal...', 'color: #818cf8; font-weight: bold;');
        await autoConnectTerminalAndSync();
    }
};

// ══════════════════════════════════════════════════════════════════════════════
// AUTO-CONNECT TO NEXUS TERMINAL & SYNC FINDINGS
// ══════════════════════════════════════════════════════════════════════════════

async function autoConnectTerminalAndSync() {
    try {
        // Check if already connected
        if (window.TerminalBridge?.isConnected()) {
            console.log('%c✅ Terminal already connected — syncing findings...', 'color: #22c55e; font-weight: bold;');
            await syncFindingsToTerminal();
            return;
        }
        
        // Try to auto-connect using saved credentials
        const savedUrl = localStorage.getItem('nexus_terminal_url') || 'ws://localhost:9999';
        const savedToken = localStorage.getItem('nexus_terminal_token');
        
        if (!savedToken) {
            console.log('%c⚠️ No terminal token saved. Use connectTerminal(url, token) to connect manually.', 'color: #f59e0b;');
            console.log('%c   Or click the Terminal button in the UI panel.', 'color: #94a3b8;');
            console.log('%c   After connecting, findings will auto-sync to terminal.', 'color: #94a3b8;');
            return;
        }
        
        console.log(`%c🔌 Auto-connecting to terminal: ${savedUrl}`, 'color: #818cf8;');
        
        const connected = await window.connectTerminal(savedUrl, savedToken);
        
        if (connected) {
            console.log('%c✅ Terminal auto-connected successfully!', 'color: #22c55e; font-weight: bold;');
            await syncFindingsToTerminal();
        } else {
            console.log('%c⚠️ Terminal auto-connect failed. Connect manually with connectTerminal(url, token)', 'color: #f59e0b;');
        }
    } catch(e) {
        console.log(`%c⚠️ Terminal auto-connect: ${e.message}`, 'color: #f59e0b;');
        console.log('%c   Start terminal server: node nexus-terminal.js', 'color: #94a3b8;');
    }
}

// === SYNC CONTROL - PREVENT DUPLICATE SENDS ===
let _syncInProgress = false;
let _lastSyncTime = 0;
let _syncedFindingsHash = '';
const MIN_SYNC_INTERVAL = 5000; // 5 seconds minimum between syncs

// Hash findings to detect duplicates
function hashFindings(findings) {
    return findings.map(f => `${f.type}:${f.value?.substring(0,20)}`).sort().join('|');
}

// Sync all current findings to the connected terminal (ENHANCED with AI Research)
async function syncFindingsToTerminal() {
    // Prevent duplicate sync
    if (_syncInProgress) {
        console.log('%c⏳ Sync already in progress, skipping...', 'color: #f59e0b;');
        return;
    }
    
    // Rate limit syncs
    const now = Date.now();
    if (now - _lastSyncTime < MIN_SYNC_INTERVAL) {
        console.log('%c⏳ Sync too frequent, waiting...', 'color: #f59e0b;');
        return;
    }
    
    if (!window.TerminalBridge?.isConnected()) {
        console.log('%c❌ Terminal not connected — cannot sync findings', 'color: #f43f5e;');
        return;
    }
    
    _syncInProgress = true;
    _lastSyncTime = now;
    
    try {
        // Gather all findings from Vault
        const allFindings = [];
        
        if (window.__NEXUS__?.Vault) {
            const vault = window.__NEXUS__.Vault;
            if (vault.all && typeof vault.all === 'function') {
                const vaultItems = vault.all();
                if (Array.isArray(vaultItems)) {
                    vaultItems.forEach(item => {
                        const type = item.type || item.patternName || BrowserAIMemory.guessType(item.value || '');
                        const research = TokenResearchBrowser.research(item.value || '', type);
                        
                        allFindings.push({
                            type,
                            value: item.value || item.key || '',
                            severity: item.severity || 'medium',
                            source: item.source || item.context || 'browser-scan',
                            live: item.live || false,
                            validated: item.validated || false,
                            timestamp: item.timestamp || new Date().toISOString(),
                            // Enhanced research data
                            research: {
                                service: research.service,
                                bountyEstimate: research.bountyEstimate,
                                impact: research.impact,
                                similarTokens: research.similar?.length || 0,
                                testCommands: TokenResearchBrowser.getTestCommands(type, item.value || '')
                            }
                        });
                    });
                }
            }
            // Also try the secrets map
            if (vault.secrets && vault.secrets instanceof Map) {
                vault.secrets.forEach((val, key) => {
                    const finding = typeof val === 'object' ? val : { value: val };
                    const value = finding.value || key;
                    
                    if (!allFindings.some(f => f.value === value)) {
                        const type = finding.type || finding.patternName || BrowserAIMemory.guessType(value);
                        const research = TokenResearchBrowser.research(value, type);
                        
                        allFindings.push({
                            type,
                            value,
                            severity: finding.severity || 'medium',
                            source: finding.source || 'vault',
                            live: finding.live || false,
                            validated: finding.validated || false,
                            timestamp: finding.timestamp || new Date().toISOString(),
                            research: {
                                service: research.service,
                                bountyEstimate: research.bountyEstimate,
                                impact: research.impact,
                                similarTokens: research.similar?.length || 0,
                                testCommands: TokenResearchBrowser.getTestCommands(type, value)
                            }
                        });
                    }
                });
            }
        }
        
        // Also try PatternTracker findings
        if (window.PatternTracker) {
            try {
                const ptFindings = PatternTracker.getAllFindings?.() || [];
                ptFindings.forEach(f => {
                    if (!allFindings.some(af => af.value === f.value)) {
                        const type = f.type || BrowserAIMemory.guessType(f.value || '');
                        const research = TokenResearchBrowser.research(f.value || '', type);
                        
                        allFindings.push({
                            ...f,
                            type,
                            research: {
                                service: research.service,
                                bountyEstimate: research.bountyEstimate,
                                impact: research.impact,
                                testCommands: TokenResearchBrowser.getTestCommands(type, f.value || '')
                            }
                        });
                    }
                });
            } catch(e) {}
        }
        
        if (allFindings.length === 0) {
            console.log('%c📭 No findings to sync yet. Run start() to scan first.', 'color: #94a3b8;');
            _syncInProgress = false;
            return;
        }
        
        // Check if findings are same as last sync (duplicate detection)
        const currentHash = hashFindings(allFindings);
        if (currentHash === _syncedFindingsHash) {
            console.log('%c⏳ Findings unchanged since last sync, skipping...', 'color: #f59e0b;');
            _syncInProgress = false;
            return;
        }
        _syncedFindingsHash = currentHash;
        
        // Send findings to terminal with AI memory stats
        console.log(`%c📤 Sending ${allFindings.length} findings to terminal (with research data)...`, 'color: #818cf8; font-weight: bold;');
        
        const sendResult = await window.TerminalBridge.send({
            type: 'findings',
            findings: allFindings,
            browserData: {
                url: location.href,
                domain: location.hostname,
                title: document.title,
                timestamp: new Date().toISOString(),
                aiMemoryStats: BrowserAIMemory.getStats()
            }
        });
        
        // Record conversation
        BrowserAIMemory.recordConversation('browser', 'terminal', 
            { findingsCount: allFindings.length, domain: location.hostname },
            { sent: true }
        );
        BrowserAIMemory.save();
        
        console.log('%c✅ Findings synced to terminal!', 'color: #22c55e; font-weight: bold;');
        console.log(`%c   Total sent: ${allFindings.length} findings`, 'color: #94a3b8;');
        console.log(`%c   Live keys: ${allFindings.filter(f => f.live).length}`, 'color: #22c55e;');
        console.log(`%c   High severity: ${allFindings.filter(f => f.severity === 'critical' || f.severity === 'high' || f.severity === 'CRITICAL' || f.severity === 'HIGH').length}`, 'color: #f43f5e;');
        console.log(`%c   AI Memory: ${BrowserAIMemory.data.totalTokensAnalyzed} tokens learned`, 'color: #8b5cf6;');
        
        _syncInProgress = false;
        return sendResult;
    } catch(e) {
        console.log(`%c❌ Sync error: ${e.message}`, 'color: #f43f5e;');
        _syncInProgress = false;
    }
}

