        console.log('%c║    2. 📍 Track SOURCE of each token (which JS/DOM/API)                                                ║', 'color: #94a3b8;');
        console.log('%c║    3. 🧪 TEST each token against relevant APIs                                                        ║', 'color: #94a3b8;');
