// ══════════════════════════════════════════════════════════════════════════════
// ADVANCED DEEP SCANNER - Scans every corner
// ══════════════════════════════════════════════════════════════════════════════

const DeepScanner = {
    // Scan all window properties
    scanWindowProperties() {
        const secrets = [];
        const sensitivePatterns = /key|token|secret|password|api|auth|credential|session/i;
        
        const scanObject = (obj, path = 'window', depth = 0) => {
            if (depth > 3 || !obj) return;
            try {
                for (const key of Object.keys(obj)) {
                    try {
                        const val = obj[key];
                        const fullPath = `${path}.${key}`;
                        
                        if (sensitivePatterns.test(key)) {
                            if (typeof val === 'string' && val.length > 10 && val.length < 500) {
                                secrets.push({ path: fullPath, value: val, type: 'WINDOW_PROPERTY' });
                            }
                        }
                        
                        if (typeof val === 'object' && val !== null && val !== window) {
                            scanObject(val, fullPath, depth + 1);
                        }
                    } catch (e) {}
                }
            } catch (e) {}
        };
        
        // Scan common config locations
        ['config', 'CONFIG', 'env', 'ENV', 'settings', 'SETTINGS', 'app', 'APP', '__CONFIG__', '__ENV__'].forEach(prop => {
            if (window[prop]) scanObject(window[prop], `window.${prop}`);
        });
        
        return secrets;
    },
    
    // Scan all script contents
    async scanAllScripts() {
        const scripts = document.querySelectorAll('script[src]');
        for (const script of scripts) {
            try {
                const response = await fetch(script.src);
                const text = await response.text();
                if (window.__NEXUS__?.Scanner?.scan) {
                    window.__NEXUS__.Scanner.scan(text, `SCRIPT:${script.src.split('/').pop()}`);
                }
            } catch (e) {}
        }
    },
    
    // Scan localStorage and sessionStorage
    scanStorage() {
        const secrets = [];
        
        // localStorage
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            const val = localStorage.getItem(key);
            if (/key|token|secret|password|api|auth/i.test(key) || (val && val.length > 20 && val.length < 500)) {
                secrets.push({ path: `localStorage.${key}`, value: val, type: 'LOCAL_STORAGE' });
            }
        }
        
        // sessionStorage
        for (let i = 0; i < sessionStorage.length; i++) {
            const key = sessionStorage.key(i);
            const val = sessionStorage.getItem(key);
            if (/key|token|secret|password|api|auth/i.test(key) || (val && val.length > 20 && val.length < 500)) {
                secrets.push({ path: `sessionStorage.${key}`, value: val, type: 'SESSION_STORAGE' });
            }
        }
        
        return secrets;
    },
    
    // Scan IndexedDB
    async scanIndexedDB() {
        const secrets = [];
        try {
            const dbs = await indexedDB.databases();
            for (const db of dbs) {
                // Just log for now, full scan is complex
                secrets.push({ path: `IndexedDB.${db.name}`, value: `DB v${db.version}`, type: 'INDEXED_DB' });
            }
        } catch (e) {}
        return secrets;
    },
    
    // Scan cookies
    scanCookies() {
        const secrets = [];
        document.cookie.split(';').forEach(cookie => {
            const [key, val] = cookie.split('=').map(s => s.trim());
            if (/key|token|secret|session|auth/i.test(key) && val && val.length > 10) {
                secrets.push({ path: `cookie.${key}`, value: val, type: 'COOKIE' });
            }
        });
        return secrets;
    },
    
    // Scan Network: intercepted requests
    getNetworkFindings() {
        return window.__NEXUS__?.Vault?.networkLogs || [];
    },
    
    // Run deep scan
    async runDeepScan() {
        console.log('%c🔍 Running Deep Scan - Checking every corner...', 'color: #818cf8; font-weight: bold;');
        
        const allFindings = [];
        
        // Window properties
        const windowSecrets = this.scanWindowProperties();
        windowSecrets.forEach(s => {
            allFindings.push(s);
            if (window.__NEXUS__?.Scanner?.scan) {
                window.__NEXUS__.Scanner.scan(s.value, s.path);
            }
        });
        console.log(`%c   📦 Window Properties: ${windowSecrets.length} findings`, 'color: #94a3b8;');
        
        // Storage
        const storageSecrets = this.scanStorage();
        storageSecrets.forEach(s => {
            allFindings.push(s);
            if (window.__NEXUS__?.Scanner?.scan) {
                window.__NEXUS__.Scanner.scan(s.value, s.path);
            }
        });
        console.log(`%c   💾 Storage: ${storageSecrets.length} findings`, 'color: #94a3b8;');
        
        // Cookies
        const cookieSecrets = this.scanCookies();
        cookieSecrets.forEach(s => {
            allFindings.push(s);
            if (window.__NEXUS__?.Scanner?.scan) {
                window.__NEXUS__.Scanner.scan(s.value, s.path);
            }
        });
        console.log(`%c   🍪 Cookies: ${cookieSecrets.length} findings`, 'color: #94a3b8;');
        
        // Scripts (async)
        await this.scanAllScripts();
        console.log('%c   📜 Scripts: Scanned', 'color: #94a3b8;');
        
        console.log(`%c✅ Deep Scan Complete - Total: ${allFindings.length} raw findings`, 'color: #22c55e; font-weight: bold;');
        
        return allFindings;
    }
};

window.deepScan = () => DeepScanner.runDeepScan();
window.DeepScanner = DeepScanner;

// ══════════════════════════════════════════════════════════════════════════════
// ADVANCED MODULE 1: NETWORK INTERCEPTOR
// ══════════════════════════════════════════════════════════════════════════════

const NetworkInterceptor = {
    originalFetch: null,
    originalXHR: null,
    isActive: false,
    capturedRequests: [],
    capturedResponses: [],
    
    // Start intercepting all network traffic
    start() {
        if (this.isActive) return;
        this.isActive = true;
        
        // Intercept Fetch
        this.originalFetch = window.fetch;
        window.fetch = async (...args) => {
            const [url, options = {}] = args;
            const requestInfo = {
                type: 'fetch',
                url: url.toString(),
                method: options.method || 'GET',
                headers: options.headers || {},
                body: options.body,
                timestamp: Date.now()
            };
            
            // Check for secrets in request
            this.scanRequest(requestInfo);
            this.capturedRequests.push(requestInfo);
            
            try {
                const response = await this.originalFetch.apply(window, args);
                const clone = response.clone();
                
                // Try to capture response body
                try {
                    const text = await clone.text();
                    if (text && text.length < 100000) {
                        this.scanResponse(text, url.toString());
                    }
                } catch (e) {}
                
                return response;
            } catch (e) {
                throw e;
            }
        };
        
        // Intercept XMLHttpRequest
        this.originalXHR = window.XMLHttpRequest.prototype.open;
        const self = this;
        window.XMLHttpRequest.prototype.open = function(method, url, ...args) {
            this._nexus_url = url;
            this._nexus_method = method;
            
            this.addEventListener('load', function() {
                try {
                    if (this.responseText && this.responseText.length < 100000) {
                        self.scanResponse(this.responseText, this._nexus_url);
                    }
                } catch (e) {}
            });
            
            return self.originalXHR.apply(this, [method, url, ...args]);
        };
        
        console.log('%c🌐 Network Interceptor: ACTIVE', 'color: #22c55e; font-weight: bold;');
    },
    
    stop() {
        if (!this.isActive) return;
        
        if (this.originalFetch) window.fetch = this.originalFetch;
        if (this.originalXHR) window.XMLHttpRequest.prototype.open = this.originalXHR;
        
        this.isActive = false;
        console.log('%c🌐 Network Interceptor: STOPPED', 'color: #f43f5e;');
    },
    
    scanRequest(requestInfo) {
        // Scan headers for auth tokens
        const headers = requestInfo.headers;
        if (headers) {
            for (const [key, value] of Object.entries(headers)) {
                if (/auth|token|key|bearer|api/i.test(key) && value && value.length > 10) {
                    if (window.__NEXUS__?.Scanner?.scan) {
                        window.__NEXUS__.Scanner.scan(value, `HTTP_HEADER:${key}`);
                    }
                }
            }
        }
        
        // Scan body
        if (requestInfo.body && typeof requestInfo.body === 'string') {
            if (window.__NEXUS__?.Scanner?.scan) {
                window.__NEXUS__.Scanner.scan(requestInfo.body, `HTTP_BODY:${requestInfo.url.substring(0, 50)}`);
            }
        }
    },
    
    scanResponse(text, url) {
        if (window.__NEXUS__?.Scanner?.scan) {
            window.__NEXUS__.Scanner.scan(text, `HTTP_RESPONSE:${url.substring(0, 50)}`);
        }
    },
    
    // Get all captured data
    getCaptured() {
        return {
            requests: this.capturedRequests,
            count: this.capturedRequests.length
        };
    },
    
    // Show captured requests
    showCaptured() {
        console.log('%c📡 CAPTURED NETWORK REQUESTS:', 'color: #818cf8; font-weight: bold;');
        console.table(this.capturedRequests.slice(-20).map(r => ({
            Method: r.method,
            URL: r.url.substring(0, 60) + '...',
            Time: new Date(r.timestamp).toLocaleTimeString()
        })));
    }
};

// ══════════════════════════════════════════════════════════════════════════════
// ADVANCED MODULE 2: DOM MUTATION OBSERVER - REAL-TIME SCANNING
// ══════════════════════════════════════════════════════════════════════════════

const RealtimeScanner = {
    observer: null,
    isActive: false,
    
    start() {
        if (this.isActive) return;
        
        this.observer = new MutationObserver((mutations) => {
            for (const mutation of mutations) {
                // Scan added nodes
                for (const node of mutation.addedNodes) {
                    this.scanNode(node);
                }
                
                // Scan attribute changes
                if (mutation.type === 'attributes') {
                    const value = mutation.target.getAttribute(mutation.attributeName);
                    if (value && value.length > 20) {
                        if (window.__NEXUS__?.Scanner?.scan) {
                            window.__NEXUS__.Scanner.scan(value, `DOM_ATTR:${mutation.attributeName}`);
                        }
                    }
                }
            }
        });
        
        this.observer.observe(document.body, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: ['data-token', 'data-key', 'data-api', 'data-secret', 'value']
        });
        
        this.isActive = true;
        console.log('%c👁️ Realtime DOM Scanner: ACTIVE', 'color: #22c55e; font-weight: bold;');
    },
    
    stop() {
        if (this.observer) {
            this.observer.disconnect();
            this.observer = null;
        }
        this.isActive = false;
        console.log('%c👁️ Realtime DOM Scanner: STOPPED', 'color: #f43f5e;');
    },
    
    scanNode(node) {
        if (!node) return;
        
        // Text content
        if (node.nodeType === Node.TEXT_NODE && node.textContent) {
            if (window.__NEXUS__?.Scanner?.scan) {
                window.__NEXUS__.Scanner.scan(node.textContent, 'DOM_TEXT');
            }
        }
        
        // Element attributes
        if (node.nodeType === Node.ELEMENT_NODE) {
            // Check data attributes
            if (node.dataset) {
                for (const [key, value] of Object.entries(node.dataset)) {
                    if (value && value.length > 20) {
                        if (window.__NEXUS__?.Scanner?.scan) {
                            window.__NEXUS__.Scanner.scan(value, `DOM_DATA:${key}`);
                        }
                    }
                }
            }
            
            // Check input values
            if (node.tagName === 'INPUT' && node.type !== 'password') {
                const value = node.value;
                if (value && value.length > 20) {
                    if (window.__NEXUS__?.Scanner?.scan) {
                        window.__NEXUS__.Scanner.scan(value, 'DOM_INPUT');
                    }
                }
            }
            
            // Recurse into children
            if (node.childNodes) {
                for (const child of node.childNodes) {
                    this.scanNode(child);
                }
            }
        }
    }
};

// ══════════════════════════════════════════════════════════════════════════════
// ADVANCED MODULE 3: WEBSOCKET INTERCEPTOR
// ══════════════════════════════════════════════════════════════════════════════

const WebSocketInterceptor = {
    originalWS: null,
    isActive: false,
    capturedMessages: [],
    
    start() {
        if (this.isActive) return;
        
        this.originalWS = window.WebSocket;
        const self = this;
        
        window.WebSocket = function(url, protocols) {
            const ws = new self.originalWS(url, protocols);
            
            ws.addEventListener('message', (event) => {
                self.capturedMessages.push({
                    direction: 'incoming',
                    url: url,
                    data: event.data,
                    timestamp: Date.now()
                });
                
                // Scan message
                if (typeof event.data === 'string' && event.data.length < 50000) {
                    if (window.__NEXUS__?.Scanner?.scan) {
                        window.__NEXUS__.Scanner.scan(event.data, `WS_MSG:${url.substring(0, 30)}`);
                    }
                }
            });
            
            const originalSend = ws.send.bind(ws);
            ws.send = function(data) {
                self.capturedMessages.push({
                    direction: 'outgoing',
                    url: url,
                    data: data,
                    timestamp: Date.now()
                });
                
                // Scan outgoing
                if (typeof data === 'string' && data.length < 50000) {
                    if (window.__NEXUS__?.Scanner?.scan) {
                        window.__NEXUS__.Scanner.scan(data, `WS_SEND:${url.substring(0, 30)}`);
                    }
                }
                
                return originalSend(data);
            };
            
            return ws;
        };
        
        this.isActive = true;
        console.log('%c🔌 WebSocket Interceptor: ACTIVE', 'color: #22c55e; font-weight: bold;');
    },
    
    stop() {
        if (this.originalWS) {
            window.WebSocket = this.originalWS;
        }
        this.isActive = false;
        console.log('%c🔌 WebSocket Interceptor: STOPPED', 'color: #f43f5e;');
    },
    
    showCaptured() {
        console.log('%c🔌 CAPTURED WEBSOCKET MESSAGES:', 'color: #818cf8; font-weight: bold;');
        console.table(this.capturedMessages.slice(-20).map(m => ({
            Direction: m.direction === 'incoming' ? '⬇️ IN' : '⬆️ OUT',
            URL: m.url.substring(0, 40),
            Data: (typeof m.data === 'string' ? m.data.substring(0, 50) : '[binary]') + '...',
            Time: new Date(m.timestamp).toLocaleTimeString()
        })));
    }
};

// ══════════════════════════════════════════════════════════════════════════════
// ADVANCED MODULE 4: API ENDPOINT DISCOVERY
// ══════════════════════════════════════════════════════════════════════════════

const APIDiscovery = {
    discoveredEndpoints: new Set(),
    
    // Extract API endpoints from page
    extractFromPage() {
        const endpoints = new Set();
        
        // From script contents
        const scripts = document.querySelectorAll('script:not([src])');
        scripts.forEach(script => {
            const text = script.textContent;
            
            // Match URLs
            const urlPatterns = [
                /['"`](https?:\/\/[^'"`\s]+\/api[^'"`\s]*?)['"`]/g,
                /['"`](\/api\/[^'"`\s]+)['"`]/g,
                /['"`](https?:\/\/api\.[^'"`\s]+)['"`]/g,
                /fetch\s*\(\s*['"`]([^'"`]+)['"`]/g,
                /axios\.[a-z]+\s*\(\s*['"`]([^'"`]+)['"`]/g,
                /\.get\s*\(\s*['"`]([^'"`]+)['"`]/g,
                /\.post\s*\(\s*['"`]([^'"`]+)['"`]/g
            ];
            
            urlPatterns.forEach(pattern => {
                let match;
                while ((match = pattern.exec(text)) !== null) {
                    endpoints.add(match[1]);
                }
            });
        });
        
        // From link/anchor tags
        document.querySelectorAll('a[href*="api"], link[href*="api"]').forEach(el => {
            endpoints.add(el.href);
        });
        
        this.discoveredEndpoints = new Set([...this.discoveredEndpoints, ...endpoints]);
        return Array.from(endpoints);
    },
    
    // Find GraphQL endpoints
    findGraphQL() {
        const graphqlEndpoints = [];
        const patterns = ['/graphql', '/gql', '/query', '/api/graphql'];
        
        patterns.forEach(p => {
            const url = window.location.origin + p;
            graphqlEndpoints.push(url);
        });
        
        // Check inline scripts for GraphQL
        document.querySelectorAll('script').forEach(script => {
            if (script.textContent && script.textContent.includes('graphql')) {
                const matches = script.textContent.match(/['"`](https?:\/\/[^'"`]*graphql[^'"`]*)['"`]/gi);
                if (matches) {
                    matches.forEach(m => graphqlEndpoints.push(m.replace(/['"`]/g, '')));
                }
            }
        });
        
        return [...new Set(graphqlEndpoints)];
    },
    
    // Scan for API documentation
    findAPIDocs() {
        const docPaths = [
            '/swagger', '/swagger-ui', '/swagger.json', '/api-docs', '/openapi.json',
            '/docs', '/documentation', '/api/docs', '/api/v1/docs', '/graphiql'
        ];
        
        return docPaths.map(p => window.location.origin + p);
    },
    
    // Test if endpoint is accessible
    async testEndpoint(url) {
        try {
            const response = await fetch(url, { method: 'HEAD', mode: 'no-cors' });
            return { url, accessible: true };
        } catch (e) {
            return { url, accessible: false };
        }
    },
    
    // Run full discovery
    async runDiscovery() {
        console.log('%c🔍 API ENDPOINT DISCOVERY', 'color: #818cf8; font-weight: bold; font-size: 14px;');
        console.log('');
        
        const endpoints = this.extractFromPage();
        console.log(`%c📡 Found ${endpoints.length} API endpoints in page`, 'color: #22c55e;');
        
        if (endpoints.length > 0) {
            console.log('%c\nDiscovered Endpoints:', 'color: #818cf8;');
            endpoints.slice(0, 20).forEach(ep => {
                console.log(`%c   ${ep}`, 'color: #a78bfa; font-family: monospace;');
            });
        }
        
        const graphql = this.findGraphQL();
        console.log(`%c\n📊 GraphQL Endpoints: ${graphql.length}`, 'color: #f59e0b;');
        graphql.forEach(ep => console.log(`%c   ${ep}`, 'color: #fde68a;'));
        
        const docs = this.findAPIDocs();
        console.log(`%c\n📚 Potential API Docs:`, 'color: #3b82f6;');
        docs.forEach(ep => console.log(`%c   ${ep}`, 'color: #93c5fd;'));
        
        return { endpoints, graphql, docs };
    }
};

