// ADVANCED MODULE 8: SESSION ANALYZER
// ══════════════════════════════════════════════════════════════════════════════

const SessionAnalyzer = {
    // Analyze all session-related data
    analyzeSession() {
        console.log('%c🔐 SESSION ANALYSIS', 'color: #818cf8; font-weight: bold; font-size: 14px;');
        console.log('');
        
        const session = {
            cookies: [],
            storage: [],
            tokens: []
        };
        
        // Cookies
        console.log('%c🍪 COOKIES:', 'color: #f59e0b; font-weight: bold;');
        document.cookie.split(';').forEach(cookie => {
            const [key, value] = cookie.split('=').map(s => s.trim());
            const isSession = /session|token|auth|jwt|sid/i.test(key);
            console.log(`%c   ${key}: ${value?.substring(0, 40) || ''}... ${isSession ? '⚠️ SENSITIVE' : ''}`, 
                isSession ? 'color: #f43f5e;' : 'color: #94a3b8;');
            if (isSession) session.cookies.push({ key, value });
        });
        
        // Local Storage
        console.log('%c\n💾 LOCAL STORAGE:', 'color: #3b82f6; font-weight: bold;');
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            const value = localStorage.getItem(key);
            const isSession = /session|token|auth|jwt|user/i.test(key);
            console.log(`%c   ${key}: ${value?.substring(0, 40) || ''}... ${isSession ? '⚠️ SENSITIVE' : ''}`, 
                isSession ? 'color: #f43f5e;' : 'color: #94a3b8;');
            if (isSession) session.storage.push({ key, value });
        }
        
        // Session Storage
        console.log('%c\n📦 SESSION STORAGE:', 'color: #8b5cf6; font-weight: bold;');
        for (let i = 0; i < sessionStorage.length; i++) {
            const key = sessionStorage.key(i);
            const value = sessionStorage.getItem(key);
            const isSession = /session|token|auth|jwt|user/i.test(key);
            console.log(`%c   ${key}: ${value?.substring(0, 40) || ''}... ${isSession ? '⚠️ SENSITIVE' : ''}`, 
                isSession ? 'color: #f43f5e;' : 'color: #94a3b8;');
            if (isSession) session.storage.push({ key, value });
        }
        
        // JWT Analysis
        console.log('%c\n🔑 JWT TOKENS FOUND:', 'color: #22c55e; font-weight: bold;');
        const allTokens = [...session.cookies, ...session.storage];
        allTokens.forEach(item => {
            if (item.value && item.value.split('.').length === 3) {
                const decoded = AutoExploiter.decodeJWT(item.value);
                if (decoded) {
                    console.log(`%c   ${item.key}:`, 'color: #818cf8;');
                    console.log(`%c      Issuer: ${decoded.issuer}`, 'color: #94a3b8;');
                    console.log(`%c      Subject: ${decoded.subject}`, 'color: #94a3b8;');
                    console.log(`%c      Expired: ${decoded.expired}`, decoded.expired ? 'color: #f43f5e;' : 'color: #22c55e;');
                    session.tokens.push({ key: item.key, decoded });
                }
            }
        });
        
        return session;
    },
    
    // Hijack session (copy all session data)
    copySession() {
        const sessionData = {
            url: window.location.href,
            cookies: document.cookie,
            localStorage: {},
            sessionStorage: {}
        };
        
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            sessionData.localStorage[key] = localStorage.getItem(key);
        }
        
        for (let i = 0; i < sessionStorage.length; i++) {
            const key = sessionStorage.key(i);
            sessionData.sessionStorage[key] = sessionStorage.getItem(key);
        }
        
        const json = JSON.stringify(sessionData, null, 2);
        navigator.clipboard.writeText(json);
        
        console.log('%c✅ Session data copied to clipboard!', 'color: #22c55e; font-weight: bold;');
        console.log('%c⚠️ This contains all session tokens - use responsibly!', 'color: #f59e0b;');
        
        return sessionData;
    }
};

