// ULTRA MODULE 1: SERVICE WORKER SCANNER
// ══════════════════════════════════════════════════════════════════════════════

const ServiceWorkerScanner = {
    async scan() {
        console.log('%c🔧 Scanning Service Workers...', 'color: #818cf8; font-weight: bold;');
        const findings = [];
        
        if ('serviceWorker' in navigator) {
            const registrations = await navigator.serviceWorker.getRegistrations();
            
            for (const reg of registrations) {
                console.log(`%c[SW] ${reg.scope}`, 'color: #3b82f6;');
                
                // Try to fetch SW script
                try {
                    const response = await fetch(reg.active?.scriptURL || reg.installing?.scriptURL);
                    const code = await response.text();
                    
                    // Scan for secrets
                    const secrets = SecretExtractor.scanText(code);
                    if (secrets.length > 0) {
                        findings.push(...secrets);
                        console.log(`%c  ⚠️ Found ${secrets.length} secrets in SW!`, 'color: #f43f5e;');
                    }
                } catch(e) {}
            }
        }
        
        console.log(`%c✅ SW Scan complete. Found ${findings.length} secrets.`, 'color: #22c55e;');
        return findings;
    }
};

// ══════════════════════════════════════════════════════════════════════════════
// ULTRA MODULE 2: INDEXEDDB SCANNER
// ══════════════════════════════════════════════════════════════════════════════

const IndexedDBScanner = {
    async scan() {
        console.log('%c💾 Scanning IndexedDB...', 'color: #818cf8; font-weight: bold;');
        const findings = [];
        
        try {
            const databases = await indexedDB.databases();
            
            for (const dbInfo of databases) {
                console.log(`%c[IDB] Database: ${dbInfo.name}`, 'color: #8b5cf6;');
                
                try {
                    const request = indexedDB.open(dbInfo.name);
                    
                    await new Promise((resolve, reject) => {
                        request.onerror = reject;
                        request.onsuccess = async () => {
                            const db = request.result;
                            const stores = Array.from(db.objectStoreNames);
                            
                            for (const storeName of stores) {
                                console.log(`%c  [Store] ${storeName}`, 'color: #a78bfa;');
                                
                                try {
                                    const tx = db.transaction(storeName, 'readonly');
                                    const store = tx.objectStore(storeName);
                                    const all = await new Promise((res, rej) => {
                                        const req = store.getAll();
                                        req.onsuccess = () => res(req.result);
                                        req.onerror = rej;
                                    });
                                    
                                    // Scan all values
                                    const text = JSON.stringify(all);
                                    const secrets = SecretExtractor.scanText(text);
                                    findings.push(...secrets);
                                    
                                    if (secrets.length > 0) {
                                        console.log(`%c    ⚠️ Found ${secrets.length} secrets!`, 'color: #f43f5e;');
                                    }
                                } catch(e) {}
                            }
                            
                            db.close();
                            resolve();
                        };
                    });
                } catch(e) {}
            }
        } catch(e) {
            console.log('%c  ℹ️ IndexedDB not accessible', 'color: #64748b;');
        }
        
        console.log(`%c✅ IDB Scan complete. Found ${findings.length} secrets.`, 'color: #22c55e;');
        return findings;
    }
};

