// ULTRA MODULE 7: TOKEN HIJACKER & SESSION ANALYZER
// ══════════════════════════════════════════════════════════════════════════════

const TokenHijacker = {
    tokens: [],
    
    findAllTokens() {
        console.log('%c🔐 Hunting for Tokens...', 'color: #f43f5e; font-weight: bold;');
        this.tokens = [];
        
        // LocalStorage
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            const value = localStorage.getItem(key);
            
            if (this.isToken(key, value)) {
                this.tokens.push({ source: 'localStorage', key, value: value.substring(0, 100) });
            }
        }
        
        // SessionStorage
        for (let i = 0; i < sessionStorage.length; i++) {
            const key = sessionStorage.key(i);
            const value = sessionStorage.getItem(key);
            
            if (this.isToken(key, value)) {
                this.tokens.push({ source: 'sessionStorage', key, value: value.substring(0, 100) });
            }
        }
        
        // Cookies
        document.cookie.split(';').forEach(cookie => {
            const [key, value] = cookie.trim().split('=');
            if (this.isToken(key, value)) {
                this.tokens.push({ source: 'cookie', key, value: value?.substring(0, 100) });
            }
        });
        
        // Meta tags
        document.querySelectorAll('meta').forEach(meta => {
            const name = meta.getAttribute('name') || meta.getAttribute('property');
            const content = meta.getAttribute('content');
            if (this.isToken(name, content)) {
                this.tokens.push({ source: 'meta', key: name, value: content?.substring(0, 100) });
            }
        });
        
        // Window object
        const tokenProps = ['token', 'accessToken', 'access_token', 'authToken', 'auth_token', 
                          'apiKey', 'api_key', 'jwt', 'bearer', 'csrf', 'csrfToken'];
        tokenProps.forEach(prop => {
            if (window[prop]) {
                this.tokens.push({ source: 'window', key: prop, value: String(window[prop]).substring(0, 100) });
            }
        });
        
        // Display results
        console.log(`%c✅ Found ${this.tokens.length} tokens:`, 'color: #22c55e;');
        this.tokens.forEach(t => {
            console.log(`%c   [${t.source}] ${t.key}: ${t.value}...`, 'color: #fca5a5;');
        });
        
        return this.tokens;
    },
    
    isToken(key, value) {
        if (!key || !value) return false;
        const keyLower = key.toLowerCase();
        const valueLower = value?.toLowerCase() || '';
        
        const tokenKeywords = ['token', 'jwt', 'auth', 'bearer', 'session', 'csrf', 'api', 'key', 'secret', 'access'];
        const isTokenKey = tokenKeywords.some(k => keyLower.includes(k));
        
        // Check if value looks like a token
        const looksLikeToken = value?.length > 20 && /^[A-Za-z0-9_\-\.]+$/.test(value);
        const isJWT = value?.includes('.') && value?.split('.').length === 3;
        
        return isTokenKey || looksLikeToken || isJWT;
    },
    
    copyAllTokens() {
        const data = JSON.stringify(this.tokens, null, 2);
        navigator.clipboard.writeText(data).then(() => {
            console.log('%c✅ All tokens copied to clipboard!', 'color: #22c55e; font-weight: bold;');
        });
        return data;
    }
};

