// ══════════════════════════════════════════════════════════════════════════════
// MODULE 1: CONTEXT ANALYSIS ENGINE
// Evaluates WHERE, HOW, WHO, and WHETHER a finding is security-relevant
// ══════════════════════════════════════════════════════════════════════════════

const ContextAnalyzer = {
    // Context weight factors
    contextWeights: {
        // WHERE - Location context (0-30 points)
        location: {
            'Authorization': 30,
            'X-API-Key': 28,
            'Cookie:session': 25,
            'Cookie:auth': 25,
            'localStorage:token': 22,
            'localStorage:auth': 22,
            'sessionStorage:token': 20,
            'Header:Bearer': 28,
            'URL:token': 18,
            'URL:key': 15,
            'Body:password': 25,
            'Body:secret': 22,
            'DOM:script': 12,
            'DOM:meta': 10,
            'DOM:data-attr': 8,
            'Network:request': 20,
            'Network:response': 18,
            'WebSocket': 15,
            'IndexedDB': 12,
            'ServiceWorker': 10,
            'default': 5
        },
        
        // HOW - Usage context (0-25 points)
        usage: {
            'authentication': 25,
            'authorization': 25,
            'payment': 25,
            'session': 22,
            'api_call': 20,
            'webhook': 18,
            'admin': 25,
            'user_data': 20,
            'config': 12,
            'analytics': 3,
            'tracking': 2,
            'experiment': 2,
            'feature_flag': 3,
            'cdn': 1,
            'cache': 2,
            'logging': 5,
            'default': 8
        },
        
        // WHO - Ownership context (0-25 points)
        ownership: {
            'user_specific': 25,
            'session_bound': 22,
            'account_wide': 20,
            'org_wide': 18,
            'app_wide': 10,
            'public': 2,
            'third_party': 8,
            'default': 10
        },
        
        // WHETHER - Security impact (0-20 points)
        impact: {
            'auth_bypass': 20,
            'data_access': 18,
            'privilege_escalation': 20,
            'financial': 20,
            'pii_exposure': 18,
            'account_takeover': 20,
            'lateral_movement': 15,
            'information_disclosure': 10,
            'none': 0,
            'default': 8
        }
    },
    
    // CDN and safe patterns to ignore
    safePatterns: [
        // CDN paths
        /cloudfront\.net/i,
        /cdn\.(cloudflare|akamai|fastly|jsdelivr|unpkg)/i,
        /\.cloudinary\.com\/[^\/]+\/image/i,
        /images\.(unsplash|pexels|pixabay)/i,
        /static\.(xx|yy|zz)\./i,
        
        // Image/Asset IDs
        /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i, // UUID for assets
        /\.(jpg|jpeg|png|gif|svg|webp|ico|woff|woff2|ttf|eot)$/i,
        
        // Analytics/Tracking
        /^UA-\d{4,}-\d{1,}$/i, // Google Analytics
        /^G-[A-Z0-9]{10}$/i, // GA4
        /^GTM-[A-Z0-9]{6,}$/i, // GTM
        /^fb\.\d\.\d+\.\d+$/i, // Facebook pixel
        /^_ga=[^;]+/i,
        
        // Experiment/Feature flags
        /^exp_[a-z0-9_]+$/i,
        /^feature_[a-z0-9_]+$/i,
        /^ab_test_[a-z0-9_]+$/i,
        /^variant_[a-z0-9]+$/i,
        
        // Cache/Version IDs
        /^v\d+\.\d+\.\d+$/i,
        /^[a-f0-9]{6,8}$/, // Short hashes (build IDs)
        /^cache_[a-z0-9]+$/i,
        
        // Common non-sensitive Base64
        /^eyJ[a-zA-Z0-9_-]*$/, // Check if JWT-like but actually just encoded metadata
    ],
    
    // Analyze context of a finding
    analyze(value, source, patternName, additionalContext = {}) {
        const analysis = {
            value: value.substring(0, 50) + (value.length > 50 ? '...' : ''),
            source,
            patternName,
            
            // Context scores
            locationScore: 0,
            usageScore: 0,
            ownershipScore: 0,
            impactScore: 0,
            totalScore: 0,
            
            // Context details
            location: this.detectLocation(source),
            usage: this.detectUsage(value, source, patternName),
            ownership: this.detectOwnership(value, source, patternName),
            impact: this.detectImpact(patternName, additionalContext),
            
            // Verdict
            isSecurityRelevant: false,
            shouldIgnore: false,
            ignoreReason: null,
            confidence: 'LOW',
            
            // AI analysis placeholder
            aiAnalysis: null
        };
        
        // Check if should be ignored first
        const ignoreCheck = this.shouldIgnore(value, source, patternName);
        if (ignoreCheck.ignore) {
            analysis.shouldIgnore = true;
            analysis.ignoreReason = ignoreCheck.reason;
            analysis.isSecurityRelevant = false;
            analysis.confidence = 'IGNORED';
            return analysis;
        }
        
        // Calculate scores
        analysis.locationScore = this.contextWeights.location[analysis.location] || this.contextWeights.location.default;
        analysis.usageScore = this.contextWeights.usage[analysis.usage] || this.contextWeights.usage.default;
        analysis.ownershipScore = this.contextWeights.ownership[analysis.ownership] || this.contextWeights.ownership.default;
        analysis.impactScore = this.contextWeights.impact[analysis.impact] || this.contextWeights.impact.default;
        
        analysis.totalScore = analysis.locationScore + analysis.usageScore + analysis.ownershipScore + analysis.impactScore;
        
        // Determine security relevance (threshold: 40/100)
        if (analysis.totalScore >= 70) {
            analysis.isSecurityRelevant = true;
            analysis.confidence = 'HIGH';
        } else if (analysis.totalScore >= 50) {
            analysis.isSecurityRelevant = true;
            analysis.confidence = 'MEDIUM';
        } else if (analysis.totalScore >= 40) {
            analysis.isSecurityRelevant = true;
            analysis.confidence = 'LOW';
        } else {
            analysis.isSecurityRelevant = false;
            analysis.confidence = 'NOISE';
        }
        
        return analysis;
    },
    
    // Detect location context
    detectLocation(source) {
        const src = source.toLowerCase();
        
        if (src.includes('authorization') || src.includes('auth-header')) return 'Authorization';
        if (src.includes('x-api-key')) return 'X-API-Key';
        if (src.includes('cookie') && src.includes('session')) return 'Cookie:session';
        if (src.includes('cookie') && src.includes('auth')) return 'Cookie:auth';
        if (src.includes('localstorage') && src.includes('token')) return 'localStorage:token';
        if (src.includes('localstorage') && src.includes('auth')) return 'localStorage:auth';
        if (src.includes('sessionstorage') && src.includes('token')) return 'sessionStorage:token';
        if (src.includes('bearer')) return 'Header:Bearer';
        if (src.includes('url') && src.includes('token')) return 'URL:token';
        if (src.includes('url') && src.includes('key')) return 'URL:key';
        if (src.includes('network') || src.includes('fetch') || src.includes('xhr')) return 'Network:request';
        if (src.includes('response')) return 'Network:response';
        if (src.includes('websocket') || src.includes('ws:')) return 'WebSocket';
        if (src.includes('indexeddb') || src.includes('idb')) return 'IndexedDB';
        if (src.includes('serviceworker') || src.includes('sw:')) return 'ServiceWorker';
        if (src.includes('script')) return 'DOM:script';
        if (src.includes('meta')) return 'DOM:meta';
        if (src.includes('data-')) return 'DOM:data-attr';
        
        return 'default';
    },
    
    // Detect usage context
    detectUsage(value, source, patternName) {
        const pattern = patternName.toLowerCase();
        const src = source.toLowerCase();
        
        // Authentication patterns
        if (pattern.includes('auth') || pattern.includes('bearer') || pattern.includes('jwt')) return 'authentication';
        if (pattern.includes('session') || pattern.includes('sid')) return 'session';
        if (pattern.includes('admin')) return 'admin';
        if (pattern.includes('payment') || pattern.includes('stripe') || pattern.includes('paypal')) return 'payment';
        if (pattern.includes('api') && pattern.includes('key')) return 'api_call';
        if (pattern.includes('webhook')) return 'webhook';
        
        // Analytics patterns
        if (pattern.includes('analytics') || pattern.includes('ga_') || pattern.includes('gtm')) return 'analytics';
        if (pattern.includes('tracking') || pattern.includes('pixel')) return 'tracking';
        if (pattern.includes('experiment') || pattern.includes('ab_test')) return 'experiment';
        if (pattern.includes('feature') || pattern.includes('flag')) return 'feature_flag';
        
        // CDN/Cache patterns
        if (src.includes('cdn') || src.includes('static') || src.includes('assets')) return 'cdn';
        if (pattern.includes('cache') || src.includes('cache')) return 'cache';
        
        return 'default';
    },
    
    // Detect ownership context
    detectOwnership(value, source, patternName) {
        const pattern = patternName.toLowerCase();
        
        // User-specific indicators
        if (pattern.includes('user') || pattern.includes('account')) return 'user_specific';
        if (pattern.includes('session')) return 'session_bound';
        if (pattern.includes('org') || pattern.includes('team')) return 'org_wide';
        if (pattern.includes('app') || pattern.includes('client')) return 'app_wide';
        
        // JWT analysis
        if (value.includes('.') && value.split('.').length === 3) {
            try {
                const payload = JSON.parse(atob(value.split('.')[1]));
                if (payload.sub || payload.user_id || payload.uid) return 'user_specific';
                if (payload.org_id || payload.team_id) return 'org_wide';
            } catch(e) {}
        }
        
        // Public key indicators
        if (pattern.includes('public') || pattern.includes('anon')) return 'public';
        
        return 'default';
    },
    
    // Detect potential impact
    detectImpact(patternName, additionalContext = {}) {
        const pattern = patternName.toLowerCase();
        
        if (pattern.includes('admin') || pattern.includes('root')) return 'privilege_escalation';
        if (pattern.includes('password') || pattern.includes('credential')) return 'auth_bypass';
        if (pattern.includes('payment') || pattern.includes('stripe') || pattern.includes('financial')) return 'financial';
        if (pattern.includes('ssn') || pattern.includes('credit_card') || pattern.includes('pii')) return 'pii_exposure';
        if (pattern.includes('session') || pattern.includes('refresh')) return 'account_takeover';
        if (pattern.includes('api') && (pattern.includes('secret') || pattern.includes('private'))) return 'data_access';
        if (pattern.includes('internal') || pattern.includes('private_ip')) return 'lateral_movement';
        
        // Check additional context
        if (additionalContext.canAccessUserData) return 'data_access';
        if (additionalContext.canModify) return 'privilege_escalation';
        
        return 'default';
    },
    
    // Check if value should be ignored
    shouldIgnore(value, source, patternName) {
        // Check against safe patterns
        for (const pattern of this.safePatterns) {
            if (pattern.test(value)) {
                return { ignore: true, reason: `Matches safe pattern: ${pattern.toString().substring(0, 50)}` };
            }
        }
        
        // Decode Base64 and check if it's non-sensitive metadata
        if (value.length > 20 && /^[A-Za-z0-9+/=]+$/.test(value)) {
            try {
                const decoded = atob(value);
                // Check if decoded content is just JSON metadata
                if (decoded.startsWith('{') || decoded.startsWith('[')) {
                    const json = JSON.parse(decoded);
                    const keys = Object.keys(json).join(',').toLowerCase();
                    
                    // Non-sensitive metadata patterns
                    const metadataPatterns = ['city', 'zone', 'region', 'locale', 'theme', 'preference', 'setting', 'config', 'version', 'timestamp', 'device', 'browser', 'os'];
                    const isMetadata = metadataPatterns.some(p => keys.includes(p));
                    
                    if (isMetadata && !keys.includes('token') && !keys.includes('key') && !keys.includes('secret') && !keys.includes('password')) {
                        return { ignore: true, reason: `Base64 decodes to non-sensitive metadata: ${keys.substring(0, 50)}` };
                    }
                }
            } catch(e) {}
        }
        
        // Check for common false positive patterns
        const value_lower = value.toLowerCase();
        
        // Image/asset references
        if (/\.(jpg|jpeg|png|gif|svg|webp|mp4|mp3|pdf|doc|zip)$/i.test(value)) {
            return { ignore: true, reason: 'File extension indicates asset, not secret' };
        }
        
        // Very short hashes that are likely build IDs
        if (/^[a-f0-9]{6,8}$/i.test(value) && !source.toLowerCase().includes('token')) {
            return { ignore: true, reason: 'Short hex string likely a build/version ID' };
        }
        
        // Common frontend identifiers
        if (/^(component|module|chunk|bundle|vendor|main|app|index)[-_][a-f0-9]+$/i.test(value)) {
            return { ignore: true, reason: 'Frontend build artifact identifier' };
        }
        
        return { ignore: false, reason: null };
    },
    
    // Run AI analysis on context
    async aiAnalyzeContext(finding) {
        if (!window.AIAgent || !window.AIAgent.config?.apiKey) {
            return { error: 'No AI configured. Use setAI(key) first.' };
        }
        
        const prompt = `You are a senior bug bounty triager. Analyze this finding for security relevance.

FINDING:
- Type: ${finding.patternName}
- Value (partial): ${finding.value.substring(0, 30)}...
- Source: ${finding.source}
- Context Score: ${finding.totalScore}/100
- Location: ${finding.location}
- Usage: ${finding.usage}
- Ownership: ${finding.ownership}

QUESTIONS:
1. Is this a real security issue or false positive? (REAL/FALSE_POSITIVE)
2. Why? (1 sentence)
3. Exploitability (0-100)
4. Recommended action (REPORT/INVESTIGATE/IGNORE)

Respond in JSON: {"verdict": "...", "reason": "...", "exploitability": 0, "action": "..."}`;

        try {
            const response = await AIAgent.callAI(prompt);
            return JSON.parse(response.match(/\{[\s\S]*\}/)?.[0] || '{}');
        } catch(e) {
            return { error: e.message };
        }
    }
};

// ══════════════════════════════════════════════════════════════════════════════
// MODULE 2: TOKEN & SECRET CLASSIFICATION ENGINE
// Classifies every finding with detailed metadata
// ══════════════════════════════════════════════════════════════════════════════

const TokenClassifier = {
    // Classification rules by pattern
    classificationRules: {
        // Auth Tokens
        JWT: { type: 'authToken', userBound: true, scope: 'unknown', expiry: 'short', replayable: true },
        BEARER_TOKEN: { type: 'authToken', userBound: true, scope: 'unknown', expiry: 'short', replayable: true },
        SESSION_ID: { type: 'sessionId', userBound: true, scope: 'read', expiry: 'short', replayable: true },
        REFRESH_TOKEN: { type: 'refreshToken', userBound: true, scope: 'write', expiry: 'long', replayable: true },
        
        // API Keys
        AWS_ACCESS_KEY_ID: { type: 'apiKey', userBound: false, scope: 'admin', expiry: 'none', replayable: true },
        GOOGLE_API_KEY: { type: 'apiKey', userBound: false, scope: 'read', expiry: 'none', replayable: true },
        STRIPE_SECRET_KEY: { type: 'apiKey', userBound: false, scope: 'payment', expiry: 'none', replayable: true },
        STRIPE_PUBLISHABLE_KEY: { type: 'publicIdentifier', userBound: false, scope: 'read', expiry: 'none', replayable: false },
        GITHUB_PAT: { type: 'apiKey', userBound: true, scope: 'write', expiry: 'long', replayable: true },
        DISCORD_TOKEN: { type: 'authToken', userBound: true, scope: 'admin', expiry: 'long', replayable: true },
        SLACK_TOKEN: { type: 'apiKey', userBound: false, scope: 'write', expiry: 'none', replayable: true },
        
        // Payment
        CREDIT_CARD: { type: 'sensitiveData', userBound: true, scope: 'payment', expiry: 'none', replayable: true },
        
        // Metadata (low risk)
        GOOGLE_ANALYTICS: { type: 'metadata', userBound: false, scope: 'read', expiry: 'none', replayable: false },
        GTM_ID: { type: 'metadata', userBound: false, scope: 'read', expiry: 'none', replayable: false },
        FACEBOOK_PIXEL: { type: 'metadata', userBound: false, scope: 'read', expiry: 'none', replayable: false },
        
        // Public identifiers
        ALGOLIA_APP_ID: { type: 'publicIdentifier', userBound: false, scope: 'read', expiry: 'none', replayable: false },
        FIREBASE_PROJECT_ID: { type: 'publicIdentifier', userBound: false, scope: 'read', expiry: 'none', replayable: false },
        
        // Default
        DEFAULT: { type: 'unknown', userBound: false, scope: 'unknown', expiry: 'unknown', replayable: false }
    },
    
    // Classify a finding
    classify(value, patternName, source) {
        const classification = {
            value: value.substring(0, 50) + (value.length > 50 ? '...' : ''),
            patternName,
            source,
            
            // Core classification
            type: 'unknown',
            userBound: false,
            scope: 'unknown',
            expiry: 'unknown',
            replayable: false,
            
            // Additional analysis
            isJWT: false,
            jwtPayload: null,
            jwtExpiry: null,
            jwtClaims: [],
            
            // Risk factors
            riskFactors: [],
            riskLevel: 'LOW'
        };
        
        // Get base classification from rules
        const baseRule = this.classificationRules[patternName] || this.classificationRules.DEFAULT;
        Object.assign(classification, baseRule);
        
        // Enhanced JWT analysis
        if (value.includes('.') && value.split('.').length === 3) {
            classification.isJWT = true;
            try {
                const payload = JSON.parse(atob(value.split('.')[1]));
                classification.jwtPayload = payload;
                
                // Expiry analysis
                if (payload.exp) {
                    const expDate = new Date(payload.exp * 1000);
                    classification.jwtExpiry = expDate.toISOString();
                    const now = new Date();
                    
                    if (expDate < now) {
                        classification.riskFactors.push('JWT_EXPIRED');
                    } else {
                        const hoursToExpiry = (expDate - now) / (1000 * 60 * 60);
                        if (hoursToExpiry < 1) classification.expiry = 'short';
                        else if (hoursToExpiry < 24) classification.expiry = 'medium';
                        else classification.expiry = 'long';
                    }
                } else {
                    classification.riskFactors.push('NO_EXPIRY_CLAIM');
                    classification.expiry = 'none';
                }
                
                // User binding analysis
                if (payload.sub || payload.user_id || payload.uid || payload.email) {
                    classification.userBound = true;
                    classification.jwtClaims.push('user_identity');
                }
                
                // Scope analysis
                if (payload.scope) {
                    classification.jwtClaims.push(`scope:${payload.scope}`);
                    if (payload.scope.includes('admin')) classification.scope = 'admin';
                    else if (payload.scope.includes('write')) classification.scope = 'write';
                    else if (payload.scope.includes('read')) classification.scope = 'read';
                }
                
                if (payload.role) {
                    classification.jwtClaims.push(`role:${payload.role}`);
                    if (payload.role === 'admin' || payload.role === 'superuser') {
                        classification.scope = 'admin';
                        classification.riskFactors.push('ADMIN_ROLE');
                    }
                }
                
            } catch(e) {
                classification.riskFactors.push('JWT_PARSE_ERROR');
            }
        }
        
        // Determine risk level
        classification.riskLevel = this.calculateRiskLevel(classification);
        
        return classification;
    },
    
    // Calculate overall risk level
    calculateRiskLevel(classification) {
        let riskScore = 0;
        
        // Type-based risk
        const typeRisk = { 
            authToken: 30, refreshToken: 35, apiKey: 25, sessionId: 28, 
            sensitiveData: 40, publicIdentifier: 5, metadata: 2, unknown: 15 
        };
        riskScore += typeRisk[classification.type] || 10;
        
        // Scope-based risk
        const scopeRisk = { admin: 30, payment: 35, write: 20, read: 10, unknown: 15 };
        riskScore += scopeRisk[classification.scope] || 10;
        
        // User binding (higher if user-specific)
        if (classification.userBound) riskScore += 15;
        
        // Replayability
        if (classification.replayable) riskScore += 10;
        
        // Expiry
        if (classification.expiry === 'none' || classification.expiry === 'long') riskScore += 10;
        
        // Risk factors
        riskScore += classification.riskFactors.length * 5;
        
        if (riskScore >= 70) return 'CRITICAL';
        if (riskScore >= 50) return 'HIGH';
        if (riskScore >= 30) return 'MEDIUM';
        return 'LOW';
    },
    
    // AI-enhanced classification
    async aiClassify(finding) {
        if (!window.AIAgent || !window.AIAgent.config?.apiKey) {
            return { error: 'No AI configured' };
        }
        
        const prompt = `You are a security engineer. Classify this secret/token.

VALUE (partial): ${finding.value.substring(0, 40)}...
TYPE DETECTED: ${finding.patternName}
SOURCE: ${finding.source}

Classify as JSON:
{
  "type": "authToken|apiKey|sessionId|refreshToken|metadata|publicIdentifier|sensitiveData",
  "userBound": true/false,
  "scope": "read|write|admin|payment|unknown",
  "expiry": "short|medium|long|none",
  "replayable": true/false,
  "canCauseHarm": true/false,
  "harmDescription": "what can attacker do with this"
}`;

        try {
            const response = await AIAgent.callAI(prompt);
            return JSON.parse(response.match(/\{[\s\S]*\}/)?.[0] || '{}');
        } catch(e) {
            return { error: e.message };
        }
    }
};

// ══════════════════════════════════════════════════════════════════════════════
// MODULE 3: EXPLOITABILITY SCORE ENGINE
// Calculates real exploitability (0-100), not just severity
// ══════════════════════════════════════════════════════════════════════════════

const ExploitabilityScorer = {
    // Score factors (each 0-20 points, total 100)
    factors: {
        authBypass: { weight: 20, description: 'Can bypass authentication' },
        crossUserAccess: { weight: 20, description: 'Can access other users data (IDOR)' },
        financialImpact: { weight: 20, description: 'Can cause financial damage' },
        automationPotential: { weight: 20, description: 'Can be automated at scale' },
        scopeEscalation: { weight: 20, description: 'Can escalate to higher privileges' }
    },
    
    // Calculate exploitability score
    calculate(finding, classification, context) {
        const score = {
            finding: finding.value?.substring(0, 30) + '...',
            type: finding.patternName || finding.type,
            
            // Individual factor scores
            authBypass: 0,
            crossUserAccess: 0,
            financialImpact: 0,
            automationPotential: 0,
            scopeEscalation: 0,
            
            // Total
            totalScore: 0,
            
            // Explanation
            factors: [],
            exploitPath: null,
            
            // Verdict
            exploitability: 'NONE',
            recommendation: ''
        };
        
        const pattern = (finding.patternName || finding.type || '').toLowerCase();
        
        // === AUTH BYPASS (0-20) ===
        if (classification?.type === 'authToken' || classification?.type === 'sessionId') {
            score.authBypass = 18;
            score.factors.push({ factor: 'authBypass', score: 18, reason: 'Token can be used to authenticate as user' });
        } else if (classification?.type === 'refreshToken') {
            score.authBypass = 20;
            score.factors.push({ factor: 'authBypass', score: 20, reason: 'Refresh token can mint new access tokens' });
        } else if (pattern.includes('password') || pattern.includes('credential')) {
            score.authBypass = 20;
            score.factors.push({ factor: 'authBypass', score: 20, reason: 'Direct password/credential exposure' });
        } else if (classification?.type === 'apiKey' && classification?.scope !== 'read') {
            score.authBypass = 12;
            score.factors.push({ factor: 'authBypass', score: 12, reason: 'API key provides authenticated access' });
        }
        
        // === CROSS-USER ACCESS / IDOR (0-20) ===
        if (classification?.userBound) {
            score.crossUserAccess = 15;
            score.factors.push({ factor: 'crossUserAccess', score: 15, reason: 'User-specific token could access other user data' });
            
            // JWT without proper validation
            if (classification?.isJWT && !classification?.jwtClaims?.includes('aud')) {
                score.crossUserAccess = 18;
                score.factors.push({ factor: 'crossUserAccess', score: 3, reason: 'JWT lacks audience claim - potential IDOR' });
            }
        }
        if (pattern.includes('internal') || pattern.includes('admin')) {
            score.crossUserAccess = Math.max(score.crossUserAccess, 16);
            score.factors.push({ factor: 'crossUserAccess', score: 16, reason: 'Internal/admin access implies multi-user access' });
        }
        
        // === FINANCIAL IMPACT (0-20) ===
        if (pattern.includes('stripe') || pattern.includes('paypal') || pattern.includes('payment')) {
            score.financialImpact = 20;
            score.factors.push({ factor: 'financialImpact', score: 20, reason: 'Payment system access' });
        } else if (pattern.includes('credit_card') || pattern.includes('bank')) {
            score.financialImpact = 20;
            score.factors.push({ factor: 'financialImpact', score: 20, reason: 'Financial data exposure' });
        } else if (pattern.includes('aws') || pattern.includes('gcp') || pattern.includes('azure')) {
            score.financialImpact = 15;
            score.factors.push({ factor: 'financialImpact', score: 15, reason: 'Cloud provider - potential resource abuse' });
        } else if (classification?.scope === 'payment') {
            score.financialImpact = 18;
            score.factors.push({ factor: 'financialImpact', score: 18, reason: 'Payment scope access' });
        }
        
        // === AUTOMATION POTENTIAL (0-20) ===
        if (classification?.replayable) {
            score.automationPotential = 15;
            score.factors.push({ factor: 'automationPotential', score: 15, reason: 'Token can be replayed automatically' });
        }
        if (classification?.expiry === 'none' || classification?.expiry === 'long') {
            score.automationPotential = Math.min(20, score.automationPotential + 5);
            score.factors.push({ factor: 'automationPotential', score: 5, reason: 'Long/no expiry allows extended automation' });
        }
        if (pattern.includes('api') && classification?.type === 'apiKey') {
            score.automationPotential = Math.min(20, score.automationPotential + 8);
            score.factors.push({ factor: 'automationPotential', score: 8, reason: 'API keys are designed for automation' });
        }
        
        // === SCOPE ESCALATION (0-20) ===
        if (classification?.scope === 'admin') {
            score.scopeEscalation = 20;
            score.factors.push({ factor: 'scopeEscalation', score: 20, reason: 'Admin scope - maximum privilege' });
        } else if (classification?.scope === 'write') {
            score.scopeEscalation = 12;
            score.factors.push({ factor: 'scopeEscalation', score: 12, reason: 'Write scope - can modify data' });
        } else if (pattern.includes('github') || pattern.includes('gitlab')) {
            score.scopeEscalation = 14;
            score.factors.push({ factor: 'scopeEscalation', score: 14, reason: 'Code repo access - potential supply chain attack' });
        } else if (pattern.includes('aws') && pattern.includes('secret')) {
            score.scopeEscalation = 18;
            score.factors.push({ factor: 'scopeEscalation', score: 18, reason: 'AWS secret key - potential cloud takeover' });
        }
        
        // === CALCULATE TOTAL ===
        score.totalScore = score.authBypass + score.crossUserAccess + score.financialImpact + 
                          score.automationPotential + score.scopeEscalation;
        
        // === DETERMINE EXPLOITABILITY LEVEL ===
        if (score.totalScore >= 80) {
            score.exploitability = 'CRITICAL';
            score.recommendation = 'IMMEDIATE ACTION: Report to security team and revoke immediately';
        } else if (score.totalScore >= 60) {
            score.exploitability = 'HIGH';
            score.recommendation = 'URGENT: Verify exploitability and prepare bug bounty report';
        } else if (score.totalScore >= 40) {
            score.exploitability = 'MEDIUM';
            score.recommendation = 'INVESTIGATE: Test in controlled environment, may be exploitable';
        } else if (score.totalScore >= 20) {
            score.exploitability = 'LOW';
            score.recommendation = 'MONITOR: Low risk but keep in findings for context';
        } else {
            score.exploitability = 'NONE';
            score.recommendation = 'IGNORE: Not exploitable or public information';
        }
        
        return score;
    },
    
    // AI-enhanced exploitability analysis
    async aiAnalyze(finding, classification) {
        if (!window.AIAgent || !window.AIAgent.config?.apiKey) {
            return { error: 'No AI configured' };
        }
        
        const prompt = `You are a bug bounty expert. Calculate REAL exploitability score for this finding.

FINDING:
- Type: ${finding.patternName || finding.type}
- Value (partial): ${(finding.value || '').substring(0, 30)}...
- Classification: ${JSON.stringify(classification, null, 2)}

Score each factor 0-20:
1. Auth Bypass: Can this bypass authentication?
2. Cross-User Access: Can this access other users' data (IDOR)?
3. Financial Impact: Can this cause financial damage?
4. Automation Potential: Can attacks be automated?
5. Scope Escalation: Can this lead to privilege escalation?

Also provide:
- Real-world exploit scenario (1-2 sentences)
- Is this reportable to bug bounty? (YES/NO)
- Proof of concept outline

Respond in JSON:
{
  "authBypass": 0-20,
  "crossUserAccess": 0-20,
  "financialImpact": 0-20,
  "automationPotential": 0-20,
  "scopeEscalation": 0-20,
  "totalScore": 0-100,
  "exploitScenario": "...",
  "isBugBountyWorthy": true/false,
  "pocOutline": "..."
}`;

        try {
            const response = await AIAgent.callAI(prompt);
            return JSON.parse(response.match(/\{[\s\S]*\}/)?.[0] || '{}');
        } catch(e) {
            return { error: e.message };
        }
    }
};

// ══════════════════════════════════════════════════════════════════════════════
// MODULE 4: FALSE POSITIVE KILLER
// Aggressively filters noise with explanations
// ══════════════════════════════════════════════════════════════════════════════

const FalsePositiveKiller = {
    // Killed findings with reasons
    killedFindings: [],
    
    // Kill rules
    rules: [
        {
            name: 'CDN_ASSET_PATH',
            check: (value, source) => /cloudfront|cloudflare|akamai|fastly|jsdelivr|unpkg|cdnjs/i.test(value),
            reason: 'CDN asset path - not a secret'
        },
        {
            name: 'IMAGE_VIDEO_ID',
            check: (value, source) => /\.(jpg|jpeg|png|gif|svg|webp|mp4|mp3|wav|pdf|doc|docx|xls|xlsx)(\?|$)/i.test(value),
            reason: 'Media/document file reference - not exploitable'
        },
        {
            name: 'CATALOG_ID',
            check: (value, source) => /^(product|item|sku|catalog|category|article)[-_]?[a-z0-9]{4,12}$/i.test(value),
            reason: 'Product/catalog identifier - public data'
        },
        {
            name: 'SHORT_HASH_BUILD_ID',
            check: (value, source) => /^[a-f0-9]{6,10}$/i.test(value) && !source.includes('token'),
            reason: 'Short hash - likely build/chunk ID, not a secret'
        },
        {
            name: 'ANALYTICS_TRACKER',
            check: (value, source) => /^(UA-|G-|GTM-|AW-|DC-)[A-Z0-9-]+$/i.test(value),
            reason: 'Analytics tracking ID - public by design'
        },
        {
            name: 'EXPERIMENT_FLAG',
            check: (value, source) => /^(exp_|experiment_|ab_|test_|variant_|feature_)[a-z0-9_]+$/i.test(value),
            reason: 'A/B test or feature flag - not security relevant'
        },
        {
            name: 'LOCALE_TIMEZONE',
            check: (value, source) => /^(en-US|en-GB|fr-FR|de-DE|ja-JP|zh-CN|America\/|Europe\/|Asia\/)/i.test(value),
            reason: 'Locale or timezone string - not a secret'
        },
        {
            name: 'VERSION_STRING',
            check: (value, source) => /^v?\d+\.\d+(\.\d+)?(-[a-z]+\.\d+)?$/i.test(value),
            reason: 'Version string - not a secret'
        },
        {
            name: 'CSS_COLOR_HASH',
            check: (value, source) => /^#[a-f0-9]{3,6}$/i.test(value),
            reason: 'CSS color code - not a secret'
        },
        {
            name: 'FRONTEND_CHUNK',
            check: (value, source) => /^(chunk|bundle|vendor|main|app|runtime|polyfill)[-.]?[a-f0-9]+$/i.test(value),
            reason: 'Frontend bundle chunk ID - build artifact'
        },
        {
            name: 'BASE64_METADATA',
            check: (value, source) => {
                if (value.length < 20 || !/^[A-Za-z0-9+/=]+$/.test(value)) return false;
                try {
                    const decoded = atob(value);
                    if (decoded.startsWith('{') || decoded.startsWith('[')) {
                        const json = JSON.parse(decoded);
                        const keys = Object.keys(json).join(' ').toLowerCase();
                        return /city|zone|region|locale|theme|device|browser|os|screen|viewport/i.test(keys) &&
                               !/token|key|secret|password|auth/i.test(keys);
                    }
                } catch(e) {}
                return false;
            },
            reason: 'Base64 decodes to non-sensitive metadata (device info, locale, etc.)'
        },
        {
            name: 'PUBLIC_FIREBASE_CONFIG',
            check: (value, source) => /^[A-Za-z0-9_-]{30,50}$/.test(value) && source.includes('firebase') && 
                                      !source.includes('secret') && !source.includes('admin'),
            reason: 'Firebase public config - intended for client-side use'
        },
        {
            name: 'RECAPTCHA_SITE_KEY',
            check: (value, source) => /^6L[a-zA-Z0-9_-]{38}$/.test(value) && source.includes('recaptcha'),
            reason: 'reCAPTCHA site key - public by design'
        }
    ],
    
    // Check if finding should be killed
    shouldKill(value, source, patternName) {
        for (const rule of this.rules) {
            if (rule.check(value, source, patternName)) {
                return { kill: true, rule: rule.name, reason: rule.reason };
            }
        }
        return { kill: false };
    },
    
    // Process and filter findings
    filterFindings(findings) {
        const filtered = [];
        this.killedFindings = [];
        
        for (const finding of findings) {
            const result = this.shouldKill(finding.value, finding.source, finding.type);
            
            if (result.kill) {
                this.killedFindings.push({
                    ...finding,
                    killedBy: result.rule,
                    killReason: result.reason
                });
            } else {
                filtered.push(finding);
            }
        }
        
        return filtered;
    },
    
    // Show killed findings with reasons
    showKilled() {
        console.log('%c🗑️ FALSE POSITIVES KILLED:', 'color: #f59e0b; font-weight: bold; font-size: 14px;');
        console.log(`%c   Total: ${this.killedFindings.length} findings filtered out\n`, 'color: #94a3b8;');
        
        if (this.killedFindings.length === 0) {
            console.log('%c   No false positives detected.', 'color: #22c55e;');
            return;
        }
        
        // Group by rule
        const byRule = {};
        this.killedFindings.forEach(f => {
            byRule[f.killedBy] = byRule[f.killedBy] || [];
            byRule[f.killedBy].push(f);
        });
        
        for (const [rule, items] of Object.entries(byRule)) {
            console.log(`%c   [${rule}] - ${items.length} items`, 'color: #f59e0b;');
            console.log(`%c      Reason: ${items[0].killReason}`, 'color: #64748b;');
            items.slice(0, 3).forEach(item => {
                console.log(`%c      • ${item.value.substring(0, 40)}...`, 'color: #94a3b8;');
            });
            if (items.length > 3) {
                console.log(`%c      ... and ${items.length - 3} more`, 'color: #64748b;');
            }
        }
    },
    
    // AI analysis for borderline cases
    async aiAnalyze(finding) {
        if (!window.AIAgent || !window.AIAgent.config?.apiKey) {
            return { error: 'No AI configured' };
        }
        
        const prompt = `You are a senior bug bounty triager. Determine if this is a FALSE POSITIVE.

FINDING:
- Value: ${finding.value.substring(0, 50)}
- Type: ${finding.type || finding.patternName}
- Source: ${finding.source}

Common false positives:
- CDN paths, image IDs, catalog identifiers
- Analytics/experiment IDs
- Build hashes, version strings
- Public config keys (Firebase, reCAPTCHA)
- Base64 that decodes to device/locale metadata

Is this a FALSE POSITIVE?

Respond in JSON:
{
  "isFalsePositive": true/false,
  "confidence": "HIGH|MEDIUM|LOW",
  "reason": "why it is or isn't a false positive",
  "category": "CDN|ANALYTICS|BUILD_ARTIFACT|PUBLIC_CONFIG|METADATA|REAL_SECRET"
}`;

        try {
            const response = await AIAgent.callAI(prompt);
            return JSON.parse(response.match(/\{[\s\S]*\}/)?.[0] || '{}');
        } catch(e) {
            return { error: e.message };
        }
    }
};

// Export Part 1 modules
window.ContextAnalyzer = ContextAnalyzer;
window.TokenClassifier = TokenClassifier;
window.ExploitabilityScorer = ExploitabilityScorer;
window.FalsePositiveKiller = FalsePositiveKiller;

// Quick access functions
window.analyzeContext = (value, source, pattern) => ContextAnalyzer.analyze(value, source, pattern);
window.classifyToken = (value, pattern, source) => TokenClassifier.classify(value, pattern, source);
window.scoreExploit = (finding, classification, context) => ExploitabilityScorer.calculate(finding, classification, context);
window.killFalsePositives = (findings) => FalsePositiveKiller.filterFindings(findings);
window.showKilled = () => FalsePositiveKiller.showKilled();

console.log('%c✅ Bug Bounty Upgrade Part 1 Loaded: Context Analysis, Classification, Exploitability, FP Killer', 'color: #22c55e; font-weight: bold;');

