// MODULE 6: DETERMINISTIC ATTACK CHAIN BUILDER
// Builds explainable attack paths - no AI hallucination
// ══════════════════════════════════════════════════════════════════════════════

const AttackChainBuilder = {
    // Predefined attack chains based on finding combinations
    chainTemplates: {
        // API Key + CORS = Token theft
        API_KEY_CORS: {
            name: 'API Key Exfiltration via CORS',
            steps: [
                { prerequisite: 'Public API key exposed', action: 'Attacker finds API key in JavaScript', result: 'API key extracted' },
                { prerequisite: 'Weak CORS policy', action: 'Create malicious page that calls API', result: 'Cross-origin request succeeds' },
                { prerequisite: 'API returns sensitive data', action: 'Exfiltrate user data', result: 'Data stolen to attacker server' }
            ],
            impact: 'User data theft, potential account compromise',
            requires: ['API_KEY', 'CORS_MISCONFIGURATION']
        },
        
        // JWT + No Expiry = Session Hijacking
        JWT_HIJACK: {
            name: 'JWT Session Hijacking',
            steps: [
                { prerequisite: 'JWT exposed in client', action: 'Extract JWT from localStorage/response', result: 'JWT token obtained' },
                { prerequisite: 'No/long expiry on JWT', action: 'Use JWT in attacker\'s browser', result: 'Session replayed successfully' },
                { prerequisite: 'JWT contains user identity', action: 'Access victim\'s account', result: 'Account takeover achieved' }
            ],
            impact: 'Full account takeover, access to all user data',
            requires: ['JWT', 'LONG_EXPIRY']
        },
        
        // AWS Keys = Cloud Takeover
        AWS_TAKEOVER: {
            name: 'AWS Cloud Account Compromise',
            steps: [
                { prerequisite: 'AWS access key exposed', action: 'Configure AWS CLI with stolen keys', result: 'Authenticated to AWS' },
                { prerequisite: 'Keys have permissions', action: 'Enumerate accessible resources', result: 'S3 buckets, EC2 instances found' },
                { prerequisite: 'Write permissions exist', action: 'Deploy crypto miner or exfil data', result: 'Financial loss or data breach' }
            ],
            impact: 'Cloud infrastructure takeover, financial damage, data breach',
            requires: ['AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY']
        },
        
        // Stripe Secret = Financial Fraud
        STRIPE_FRAUD: {
            name: 'Payment System Compromise',
            steps: [
                { prerequisite: 'Stripe secret key exposed', action: 'Use key to call Stripe API', result: 'Full Stripe access obtained' },
                { prerequisite: 'Key can read customers', action: 'Extract customer payment data', result: 'PII and partial card data stolen' },
                { prerequisite: 'Key can create charges', action: 'Create fraudulent charges', result: 'Direct financial theft' }
            ],
            impact: 'Financial fraud, PCI compliance violation, reputation damage',
            requires: ['STRIPE_SECRET_KEY']
        },
        
        // GitHub PAT = Supply Chain Attack
        GITHUB_SUPPLY_CHAIN: {
            name: 'Supply Chain Attack via GitHub',
            steps: [
                { prerequisite: 'GitHub PAT exposed', action: 'Authenticate to GitHub API', result: 'Repository access obtained' },
                { prerequisite: 'PAT has write access', action: 'Modify source code', result: 'Malicious code injected' },
                { prerequisite: 'Code is deployed', action: 'Wait for CI/CD pipeline', result: 'Backdoor deployed to production' }
            ],
            impact: 'Supply chain compromise, all users affected, persistent backdoor',
            requires: ['GITHUB_PAT']
        },
        
        // IDOR Chain
        IDOR_ESCALATION: {
            name: 'IDOR to Full Data Access',
            steps: [
                { prerequisite: 'User ID exposed in response', action: 'Identify ID pattern (sequential, UUID)', result: 'ID enumeration possible' },
                { prerequisite: 'API accepts arbitrary IDs', action: 'Modify ID in request', result: 'Other user data returned' },
                { prerequisite: 'No rate limiting', action: 'Automate extraction', result: 'Mass data scraping' }
            ],
            impact: 'Access to all user data in database',
            requires: ['USER_ID_EXPOSURE', 'NO_AUTHORIZATION_CHECK']
        },
        
        // Auth Bypass
        AUTH_BYPASS: {
            name: 'Authentication Bypass',
            steps: [
                { prerequisite: 'Admin token/key exposed', action: 'Extract token from client-side', result: 'Admin credential obtained' },
                { prerequisite: 'Token is valid', action: 'Use token in API request', result: 'Admin access granted' },
                { prerequisite: 'Admin has elevated permissions', action: 'Access admin functionality', result: 'Full application control' }
            ],
            impact: 'Administrative access, can modify any data or user',
            requires: ['ADMIN_TOKEN']
        }
    },
    
    // Build attack chain from findings
    buildChain(findings) {
        const chains = [];
        const findingTypes = findings.map(f => f.patternName || f.type);
        
        // Check each template
        for (const [chainId, template] of Object.entries(this.chainTemplates)) {
            const matchedRequirements = template.requires.filter(req => 
                findingTypes.some(t => t?.toUpperCase().includes(req.replace(/_/g, '')))
            );
            
            if (matchedRequirements.length === template.requires.length) {
                // Full match
                chains.push({
                    ...template,
                    confidence: 'HIGH',
                    matchedFindings: findings.filter(f => 
                        template.requires.some(req => 
                            (f.patternName || f.type || '').toUpperCase().includes(req.replace(/_/g, ''))
                        )
                    )
                });
            } else if (matchedRequirements.length > 0) {
                // Partial match
                chains.push({
                    ...template,
                    confidence: 'PARTIAL',
                    missingRequirements: template.requires.filter(r => !matchedRequirements.includes(r)),
                    matchedFindings: findings.filter(f => 
                        matchedRequirements.some(req => 
                            (f.patternName || f.type || '').toUpperCase().includes(req.replace(/_/g, ''))
                        )
                    )
                });
            }
        }
        
        return chains;
    },
    
    // Display attack chain
    displayChain(chain) {
        console.log(`%c⛓️ ATTACK CHAIN: ${chain.name}`, 'color: #f43f5e; font-weight: bold; font-size: 14px;');
        console.log(`%c   Confidence: ${chain.confidence}`, chain.confidence === 'HIGH' ? 'color: #22c55e;' : 'color: #f59e0b;');
        console.log('');
        
        chain.steps.forEach((step, i) => {
            console.log(`%c   Step ${i + 1}:`, 'color: #818cf8; font-weight: bold;');
            console.log(`%c      Prerequisite: ${step.prerequisite}`, 'color: #94a3b8;');
            console.log(`%c      Action: ${step.action}`, 'color: #3b82f6;');
            console.log(`%c      Result: ${step.result}`, 'color: #22c55e;');
        });
        
        console.log(`%c\n   💥 IMPACT: ${chain.impact}`, 'color: #f43f5e; font-weight: bold;');
        
        if (chain.missingRequirements?.length > 0) {
            console.log(`%c   ⚠️ Missing for full chain: ${chain.missingRequirements.join(', ')}`, 'color: #f59e0b;');
        }
    },
    
    // Analyze all findings and build chains
    analyze(findings) {
        console.log('%c⛓️ ATTACK CHAIN ANALYSIS', 'color: #f43f5e; font-weight: bold; font-size: 16px;');
        console.log('%c══════════════════════════════════════════', 'color: #475569;');
        
        const chains = this.buildChain(findings || this.getAllFindings());
        
        if (chains.length === 0) {
            console.log('%c   No attack chains detected from current findings.', 'color: #94a3b8;');
            return [];
        }
        
        const highConfidence = chains.filter(c => c.confidence === 'HIGH');
        const partial = chains.filter(c => c.confidence === 'PARTIAL');
        
        console.log(`%c   Found ${highConfidence.length} confirmed chains, ${partial.length} partial chains\n`, 'color: #94a3b8;');
        
        // Display high confidence first
        highConfidence.forEach(chain => this.displayChain(chain));
        
        // Show partial chains summary
        if (partial.length > 0) {
            console.log('%c\n📋 PARTIAL CHAINS (need more findings):', 'color: #f59e0b; font-weight: bold;');
            partial.forEach(chain => {
                console.log(`%c   • ${chain.name}`, 'color: #f59e0b;');
                console.log(`%c     Missing: ${chain.missingRequirements.join(', ')}`, 'color: #64748b;');
            });
        }
        
        return chains;
    },
    
    // Get findings from vault
    getAllFindings() {
        const findings = [];
        const vault = window.__NEXUS__?.Vault?.secrets;
        if (vault) {
            vault.forEach((data, key) => {
                findings.push({ value: key, ...data });
            });
        }
        return findings;
    },
    
    // AI-enhanced chain analysis
    async aiAnalyze(findings) {
        if (!window.AIAgent || !window.AIAgent.config?.apiKey) {
            return { error: 'No AI configured' };
        }
        
        const prompt = `You are a senior pentester. Analyze these findings and build REALISTIC attack chains.

FINDINGS:
${findings.map(f => `- ${f.patternName || f.type}: ${(f.value || '').substring(0, 30)}... (source: ${f.source})`).join('\n')}

Build attack chains that are:
1. REALISTIC - no speculation
2. STEP-BY-STEP - clear progression
3. IMPACTFUL - explain business impact

For each chain provide:
- Chain name
- Steps (prerequisite → action → result)
- Required findings
- Impact statement
- Confidence (HIGH/MEDIUM/LOW)

Respond in JSON:
{
  "chains": [
    {
      "name": "...",
      "steps": [{"prerequisite": "...", "action": "...", "result": "..."}],
      "impact": "...",
      "confidence": "HIGH|MEDIUM|LOW"
    }
  ]
}`;

        try {
            const response = await AIAgent.callAI(prompt);
            return JSON.parse(response.match(/\{[\s\S]*\}/)?.[0] || '{"chains":[]}');
        } catch(e) {
            return { error: e.message };
        }
    }
};

