// MODULE 7: PROOF-OF-CONCEPT (POC) GENERATOR
// Generates reproducible POCs for every finding
// ══════════════════════════════════════════════════════════════════════════════

const POCGenerator = {
    // Generate curl command
    generateCurl(finding, classification) {
        const key = finding.value;
        const type = (finding.patternName || finding.type || '').toLowerCase();
        
        const templates = {
            github_pat: `curl -H "Authorization: token ${key}" https://api.github.com/user`,
            aws_access_key: `# Configure: aws configure\n# Then run:\naws sts get-caller-identity`,
            stripe_secret: `curl https://api.stripe.com/v1/balance -u ${key}:`,
            stripe_publishable: `# This is a publishable key - client-side only, limited risk`,
            discord_token: `curl -H "Authorization: ${key}" https://discord.com/api/v10/users/@me`,
            slack_token: `curl -H "Authorization: Bearer ${key}" https://slack.com/api/auth.test`,
            telegram_bot: `curl "https://api.telegram.org/bot${key}/getMe"`,
            openai: `curl https://api.openai.com/v1/models -H "Authorization: Bearer ${key}"`,
            sendgrid: `curl -H "Authorization: Bearer ${key}" https://api.sendgrid.com/v3/user/account`,
            twilio: `# Need Account SID + Auth Token\ncurl -u "ACCOUNT_SID:${key}" https://api.twilio.com/2010-04-01/Accounts.json`,
            firebase: `# Firebase API key - check if app has insecure rules\ncurl "https://[PROJECT].firebaseio.com/.json?auth=${key}"`,
            jwt: `# Decode JWT:\necho "${key}" | cut -d. -f2 | base64 -d 2>/dev/null`,
            generic: `# Verify this token by checking the service documentation\n# Value: ${key.substring(0, 20)}...`
        };
        
        // Find matching template
        for (const [pattern, cmd] of Object.entries(templates)) {
            if (type.includes(pattern.replace(/_/g, ''))) {
                return cmd;
            }
        }
        
        return templates.generic;
    },
    
    // Generate fetch() JavaScript POC
    generateFetch(finding, classification) {
        const key = finding.value;
        const type = (finding.patternName || finding.type || '').toLowerCase();
        
        const templates = {
            github_pat: `
fetch('https://api.github.com/user', {
    headers: { 'Authorization': 'token ${key}' }
})
.then(r => r.json())
.then(data => console.log('GitHub User:', data));`,

            stripe_secret: `
fetch('https://api.stripe.com/v1/balance', {
    headers: { 'Authorization': 'Bearer ${key}' }
})
.then(r => r.json())
.then(data => console.log('Stripe Balance:', data));`,

            discord_token: `
fetch('https://discord.com/api/v10/users/@me', {
    headers: { 'Authorization': '${key}' }
})
.then(r => r.json())
.then(data => console.log('Discord User:', data));`,

            slack_token: `
fetch('https://slack.com/api/auth.test', {
    headers: { 'Authorization': 'Bearer ${key}' }
})
.then(r => r.json())
.then(data => console.log('Slack Auth:', data));`,

            jwt: `
// Decode and analyze JWT
const jwt = '${key}';
const [header, payload, sig] = jwt.split('.');
console.log('Header:', JSON.parse(atob(header)));
console.log('Payload:', JSON.parse(atob(payload)));
// Check expiry
const exp = JSON.parse(atob(payload)).exp;
console.log('Expired:', exp ? new Date(exp * 1000) < new Date() : 'No expiry');`,

            generic: `
// Test token validity
// You may need to adjust the endpoint and headers based on the service
const token = '${key.substring(0, 30)}...';
console.log('Token to test:', token);
// Add appropriate API call here`
        };
        
        for (const [pattern, code] of Object.entries(templates)) {
            if (type.includes(pattern.replace(/_/g, ''))) {
                return code;
            }
        }
        
        return templates.generic;
    },
    
    // Generate Python exploit script
    generatePython(finding, classification) {
        const key = finding.value;
        const type = (finding.patternName || finding.type || '').toLowerCase();
        
        return `#!/usr/bin/env python3
"""
POC Script for ${finding.patternName || finding.type}
Generated by NEXUS Scanner
"""
import requests

TOKEN = "${key}"

def test_token():
    # Modify endpoint based on token type
    endpoints = {
        'github': ('https://api.github.com/user', {'Authorization': f'token {TOKEN}'}),
        'stripe': ('https://api.stripe.com/v1/balance', {'Authorization': f'Bearer {TOKEN}'}),
        'discord': ('https://discord.com/api/v10/users/@me', {'Authorization': TOKEN}),
        'slack': ('https://slack.com/api/auth.test', {'Authorization': f'Bearer {TOKEN}'})
    }
    
    for service, (url, headers) in endpoints.items():
        if '${type}'.find(service) >= 0:
            try:
                resp = requests.get(url, headers=headers, timeout=10)
                print(f"[+] {service.upper()} Response: {resp.status_code}")
                print(f"[+] Data: {resp.json()}")
                return resp.status_code == 200
            except Exception as e:
                print(f"[-] Error: {e}")
                return False
    
    print("[!] Unknown token type - manual testing required")
    return None

if __name__ == "__main__":
    test_token()
`;
    },
    
    // Generate full POC report
    generate(finding, classification) {
        const poc = {
            finding: {
                type: finding.patternName || finding.type,
                value: finding.value?.substring(0, 50) + '...',
                source: finding.source
            },
            
            curlCommand: this.generateCurl(finding, classification),
            fetchCode: this.generateFetch(finding, classification),
            pythonScript: this.generatePython(finding, classification),
            
            reproducibility: this.assessReproducibility(finding, classification),
            
            testingNotes: this.getTestingNotes(finding, classification)
        };
        
        return poc;
    },
    
    // Assess reproducibility
    assessReproducibility(finding, classification) {
        if (!classification) {
            return { reproducible: 'UNKNOWN', reason: 'No classification available' };
        }
        
        if (classification.type === 'metadata' || classification.type === 'publicIdentifier') {
            return { reproducible: 'NO', reason: 'Public identifier, not exploitable' };
        }
        
        if (classification.replayable) {
            return { reproducible: 'YES', reason: 'Token can be replayed in different context' };
        }
        
        if (classification.expiry === 'short') {
            return { reproducible: 'LIMITED', reason: 'Short expiry - reproduce quickly' };
        }
        
        return { reproducible: 'YES', reason: 'Token appears replayable' };
    },
    
    // Get testing notes
    getTestingNotes(finding, classification) {
        const type = (finding.patternName || finding.type || '').toLowerCase();
        
        const notes = {
            github: '⚠️ Testing GitHub tokens may trigger security alerts. Use on test accounts.',
            aws: '⚠️ AWS key testing can incur costs. Check permissions with get-caller-identity first.',
            stripe: '⚠️ Use test mode keys (sk_test_) to avoid real transactions.',
            discord: '⚠️ Discord may ban accounts for token theft. Only test on your own accounts.',
            jwt: '⚡ Check if JWT signature is verified server-side. Try modifying claims.',
            default: '⚠️ Test responsibly within authorized scope only.'
        };
        
        for (const [key, note] of Object.entries(notes)) {
            if (type.includes(key)) return note;
        }
        
        return notes.default;
    },
    
    // Display POC
    display(finding, classification) {
        const poc = this.generate(finding, classification);
        
        console.log('%c🔬 PROOF OF CONCEPT', 'color: #22c55e; font-weight: bold; font-size: 14px;');
        console.log(`%c   Type: ${poc.finding.type}`, 'color: #818cf8;');
        console.log(`%c   Source: ${poc.finding.source}`, 'color: #94a3b8;');
        console.log(`%c   Reproducible: ${poc.reproducibility.reproducible} - ${poc.reproducibility.reason}`, 
            poc.reproducibility.reproducible === 'YES' ? 'color: #22c55e;' : 'color: #f59e0b;');
        
        console.log('%c\n📋 CURL Command:', 'color: #3b82f6; font-weight: bold;');
        console.log(`%c${poc.curlCommand}`, 'color: #94a3b8; font-family: monospace;');
        
        console.log('%c\n📋 JavaScript (fetch):', 'color: #f59e0b; font-weight: bold;');
        console.log(`%c${poc.fetchCode}`, 'color: #94a3b8; font-family: monospace;');
        
        console.log(`%c\n${poc.testingNotes}`, 'color: #f59e0b;');
        
        return poc;
    }
};

