    // Get safe HTML function - uses global policy
    safeHTML: (html) => {
        if (typeof html !== 'string') html = String(html || '');
        
        // Use global NEXUS safeHTML if available
        if (typeof window.__NEXUS_SAFE_HTML__ === 'function') {
            try {
                return window.__NEXUS_SAFE_HTML__(html);
            } catch(e) {}
        }
        
        // Use global policy if available
        if (window.__NEXUS_POLICY__ && typeof window.__NEXUS_POLICY__.createHTML === 'function') {
            try {
                return window.__NEXUS_POLICY__.createHTML(html);
            } catch(e) {}
        }
        
        // Try creating a new policy with unique name
        if (window.trustedTypes?.createPolicy) {
            try {
                const p = window.trustedTypes.createPolicy('bounty-' + Date.now(), { createHTML: s => s });
                return p.createHTML(html);
            } catch(e) {}
        }
        
        return html;
    },
    
    // Safe innerHTML setter with DOMParser fallback for strict CSP
    safeInnerHTML(element, html) {
        if (!element) return false;
        
        // Use universal setInnerHTML if available
        if (typeof window.__NEXUS_SET_HTML__ === 'function') {
            return window.__NEXUS_SET_HTML__(element, html);
        }
        
        // Try with this.safeHTML
        try {
            element.innerHTML = this.safeHTML(html);
            return true;
        } catch(e) {
            // DOMParser fallback
            try {
                while (element.firstChild) element.removeChild(element.firstChild);
                const parser = new DOMParser();
                const doc = parser.parseFromString(`<body>${html}</body>`, 'text/html');
                Array.from(doc.body.childNodes).forEach(node => {
                    element.appendChild(document.importNode(node, true));
                });
                return true;
            } catch(e2) {
                element.textContent = html.replace(/<[^>]*>/g, '');
                return false;
            }
        }
    },
    
