    // ══════════════════════════════════════════════════════════════════════════════
    // MAIN RUN FUNCTION
    // ══════════════════════════════════════════════════════════════════════════════
    async run(options = {}) {
        if (this.isRunning) {
            console.log('%c⚠️ Analysis already running...', 'color: #f59e0b;');
            return;
        }
        
        this.isRunning = true;
        const useAI = options.ai !== false && window.AIAgent?.config?.apiKey && window.AIAgent?.config?.isActive;
        
        console.log('%c🎯 NEXUS PROFESSIONAL BOUNTY ANALYSIS v2.0', 'color: #f43f5e; font-weight: bold; font-size: 18px;');
        console.log('%c═══════════════════════════════════════════════════════════════', 'color: #475569;');
        console.log(`%c🤖 AI Mode: ${useAI ? 'ENABLED (Autonomous)' : 'DISABLED'}`, useAI ? 'color: #8b5cf6;' : 'color: #64748b;');
        
        const startTime = Date.now();
        const results = {
            timestamp: new Date().toISOString(),
            url: window.location.href,
            aiEnabled: useAI,
            rawFindings: [],
            filteredFindings: [],
            falsePositives: [],
            exploitResults: [],
            curlCommands: [],
            aiDecisions: null,
            proofs: [],
            summary: {}
        };
        
        try {
            // Phase 1: Gather findings
            this.updateUIText('bounty-summary', '🔍 Phase 1: Gathering findings...');
            const vault = window.__NEXUS__?.Vault?.secrets;
            if (vault) {
                vault.forEach((data, key) => {
                    results.rawFindings.push({ value: key, ...data });
                });
            }
            console.log(`%c[1/6] ✅ Gathered ${results.rawFindings.length} findings`, 'color: #22c55e;');
            
            // Phase 2: Filter false positives
            this.updateUIText('bounty-summary', '🗑️ Phase 2: Filtering false positives...');
            if (window.FalsePositiveKiller) {
                results.filteredFindings = FalsePositiveKiller.filterFindings(results.rawFindings);
                results.falsePositives = FalsePositiveKiller.killedFindings || [];
            } else {
                results.filteredFindings = results.rawFindings;
            }
            console.log(`%c[2/6] ✅ Filtered to ${results.filteredFindings.length} (killed ${results.falsePositives.length} FP)`, 'color: #22c55e;');
            
            // Phase 3: Run exploits
            this.updateUIText('bounty-summary', '💀 Phase 3: Running exploits...');
            results.exploitResults = await this.runExploits(results.filteredFindings);
            results.curlCommands = [...this.curlCommands];
            console.log(`%c[3/6] ✅ Tested ${results.exploitResults.length} endpoints`, 'color: #22c55e;');
            
            // Phase 4: Score exploitability
            this.updateUIText('bounty-summary', '📊 Phase 4: Scoring exploitability...');
            for (const finding of results.filteredFindings) {
                if (window.ExploitabilityScorer) {
                    const classification = window.TokenClassifier?.classify(finding.value, finding.type, finding.source) || {};
                    const context = window.ContextAnalyzer?.analyze(finding.value, finding.source, finding.type) || {};
                    finding.exploitability = ExploitabilityScorer.calculate(finding, classification, context);
                }
            }
            const highExploit = results.filteredFindings.filter(f => f.exploitability?.totalScore >= 60);
            console.log(`%c[4/6] ✅ ${highExploit.length} high exploitability findings`, 'color: #f43f5e; font-weight: bold;');
            
            // Phase 5: Build attack chains
            this.updateUIText('bounty-summary', '⛓️ Phase 5: Building attack chains...');
            if (window.AttackChainBuilder) {
                results.attackChains = AttackChainBuilder.buildChain(results.filteredFindings);
            }
            console.log(`%c[5/6] ✅ ${results.attackChains?.length || 0} attack chains`, 'color: #8b5cf6;');
            
            // Phase 6: AI Autonomous Analysis
            if (useAI) {
                this.updateUIText('bounty-summary', '🤖 Phase 6: AI Autonomous Analysis...');
                results.aiDecisions = await this.aiAutonomousAnalysis(results.filteredFindings, results.exploitResults);
                console.log(`%c[6/6] ✅ AI analysis complete`, 'color: #8b5cf6;');
            } else {
                console.log('%c[6/6] ⏭️ AI skipped (no API key)', 'color: #64748b;');
            }
            
            // Generate summary
            const elapsed = Date.now() - startTime;
            results.summary = {
                totalRaw: results.rawFindings.length,
                falsePositives: results.falsePositives.length,
                valid: results.filteredFindings.length,
                exploitsRun: results.exploitResults.length,
                liveExploits: results.exploitResults.filter(e => e.success).length,
                highExploitability: highExploit.length,
                attackChains: results.attackChains?.length || 0,
                curlCommands: results.curlCommands.length,
                aiInsights: results.aiDecisions?.findings?.length || 0,
                analysisTime: `${elapsed}ms`
            };
            
            // Update UI
            this.updateUIWithResults(results);
            
            // Display all curl commands with proper formatting
            if (results.curlCommands.length > 0) {
                console.log('%c\n═══════════════════════════════════════════════════════════════', 'color: #475569;');
                console.log('%c📋 ALL CURL COMMANDS (Copy-Paste Ready):', 'color: #22c55e; font-weight: bold; font-size: 14px;');
                console.log('%c   Commands are formatted for terminal use', 'color: #64748b;');
                
                results.curlCommands.forEach(cmd => {
                    console.log(`%c\n╔═══ ${cmd.api} (${cmd.key}) ═══╗`, 'color: #818cf8; font-weight: bold;');
                    
                    // Split commands by newline and print each separately
                    const lines = cmd.commands.split('\n');
                    lines.forEach(line => {
                        if (line.trim().startsWith('#')) {
                            console.log(`%c${line}`, 'color: #64748b; font-style: italic;');
                        } else if (line.trim().startsWith('curl')) {
                            console.log(`%c$ ${line}`, 'color: #22c55e; font-family: monospace;');
                        } else if (line.trim()) {
                            console.log(`%c  ${line}`, 'color: #94a3b8; font-family: monospace;');
                        }
                    });
                });
                
                // Copy all to clipboard
                const allCmds = results.curlCommands.map(c => `### ${c.api} ###\n${c.commands}`).join('\n\n');
                navigator.clipboard.writeText(allCmds).then(() => {
                    console.log('%c\n✅ All curl commands copied to clipboard!', 'color: #22c55e; font-weight: bold;');
                }).catch(() => {});
            }
            
            // Final summary
            this.displayFinalSummary(results);
            
            // Store results
            this.lastResults = results;
            
        } catch(e) {
            console.log(`%c❌ Analysis error: ${e.message}`, 'color: #f43f5e;');
            this.updateUIText('bounty-summary', `❌ Error: ${e.message}`);
        }
        
        this.isRunning = false;
        return results;
    },
    
