// Full vulnerability scan
window.vulnScan = async () => {
    console.log('%c\n🔥 FULL VULNERABILITY SCAN', 'color: #f43f5e; font-weight: bold; font-size: 16px;');
    console.log('%c═══════════════════════════════════════════════════════════════', 'color: #475569;');
    
    const results = { modules: [], findings: 0, errors: [] };
    
    // Run all scan modules
    const scanModules = [
        { name: 'Service Workers', fn: window.scanSW },
        { name: 'IndexedDB', fn: window.scanIDB },
        { name: 'Prototype Pollution', fn: window.detectPP },
        { name: 'XSS Vectors', fn: window.xssVectors },
        { name: 'Endpoint Enumeration', fn: window.enumEndpoints },
        { name: 'CORS Misconfig', fn: window.detectCORS }
    ];
    
    for (const mod of scanModules) {
        if (typeof mod.fn === 'function') {
            console.log(`%c\n🔍 Scanning: ${mod.name}...`, 'color: #818cf8;');
            try {
                const result = await mod.fn();
                results.modules.push({ name: mod.name, result, success: true });
                console.log(`%c   ✅ ${mod.name} complete`, 'color: #22c55e;');
            } catch(e) {
                results.errors.push({ name: mod.name, error: e.message });
                console.log(`%c   ❌ ${mod.name} failed: ${e.message}`, 'color: #f43f5e;');
            }
        } else {
            console.log(`%c   ⏭️ ${mod.name} not available`, 'color: #64748b;');
        }
    }
    
    // Also run main scan
    if (typeof window.start === 'function') {
        console.log('%c\n🔍 Running main secret scanner...', 'color: #818cf8;');
        await window.start();
    }
    
    console.log('%c\n✅ VULNERABILITY SCAN COMPLETE', 'color: #22c55e; font-weight: bold;');
    console.log(`%c   Modules Run: ${results.modules.length}`, 'color: #94a3b8;');
    console.log(`%c   Errors: ${results.errors.length}`, results.errors.length > 0 ? 'color: #f43f5e;' : 'color: #94a3b8;');
    
    return results;
};

