// AI Attack Chain Generation
window.aiChains = async () => {
    if (!window.AIAgent?.config?.apiKey || !window.AIAgent?.config?.isActive) {
        console.log('%c❌ AI not configured. Use setAI(key) first.', 'color: #f43f5e;');
        return null;
    }
    
    console.log('%c\n⛓️ AI ATTACK CHAIN GENERATION', 'color: #8b5cf6; font-weight: bold; font-size: 14px;');
    console.log('%c═══════════════════════════════════════════════════════════════', 'color: #475569;');
    
    // Gather findings
    const findings = [];
    if (window.Vault?.secrets) {
        window.Vault.secrets.forEach((entry, key) => {
            findings.push({ value: key, ...entry });
        });
    }
    
    if (findings.length === 0) {
        console.log('%c⚠️ No findings to analyze. Run start() first.', 'color: #f59e0b;');
        return null;
    }
    
    const prompt = `You are an ELITE PENETRATION TESTER. Analyze these findings and generate sophisticated ATTACK CHAINS.

FINDINGS (${findings.length} total):
${findings.slice(0, 20).map((f, i) => `${i+1}. Type: ${f.patternName || f.type || 'unknown'}
   Value Preview: ${(f.value || '').substring(0, 40)}...
   Source: ${f.source || 'unknown'}`).join('\n\n')}

WEBSITE CONTEXT:
- URL: ${location.href}
- Domain: ${location.hostname}
- Protocol: ${location.protocol}

Generate REALISTIC attack chains that combine these findings. For each chain:
1. Name the attack
2. List exact steps
3. Explain impact
4. Provide proof-of-concept commands
5. Estimate difficulty and likelihood of success

Respond in JSON:
{
  "chains": [
    {
      "name": "Attack Chain Name",
      "severity": "CRITICAL|HIGH|MEDIUM|LOW",
      "difficulty": "EASY|MEDIUM|HARD",
      "successLikelihood": "HIGH|MEDIUM|LOW",
      "findingsUsed": [1, 3, 5],
      "steps": [
        {"step": 1, "action": "...", "command": "curl ..."},
        {"step": 2, "action": "...", "command": "..."}
      ],
      "impact": "What happens if successful",
      "mitigation": "How to prevent this"
    }
  ],
  "recommendations": ["..."],
  "immediateRisks": ["..."]
}`;

    try {
        const response = await window.AIAgent.callAI(prompt);
        const jsonMatch = response.match(/\{[\s\S]*\}/);
        
        if (jsonMatch) {
            const result = JSON.parse(jsonMatch[0]);
            
            if (result.chains?.length) {
                console.log(`%c\n🔗 Generated ${result.chains.length} Attack Chains:`, 'color: #8b5cf6; font-weight: bold;');
                
                result.chains.forEach((chain, i) => {
                    const color = chain.severity === 'CRITICAL' ? '#f43f5e' :
                                  chain.severity === 'HIGH' ? '#f59e0b' : '#818cf8';
                    
                    console.log(`%c\n[${i+1}] ${chain.name}`, `color: ${color}; font-weight: bold;`);
                    console.log(`%c    Severity: ${chain.severity} | Difficulty: ${chain.difficulty}`, 'color: #94a3b8;');
                    console.log(`%c    Success Likelihood: ${chain.successLikelihood}`, 'color: #94a3b8;');
                    
                    if (chain.steps?.length) {
                        console.log('%c    Steps:', 'color: #64748b;');
                        chain.steps.forEach(s => {
                            console.log(`%c      ${s.step}. ${s.action}`, 'color: #94a3b8;');
                            if (s.command) console.log(`%c         $ ${s.command}`, 'color: #67e8f9; font-family: monospace;');
                        });
                    }
                    
                    console.log(`%c    Impact: ${chain.impact}`, 'color: #fca5a5;');
                });
                
                if (result.immediateRisks?.length) {
                    console.log('%c\n🚨 IMMEDIATE RISKS:', 'color: #f43f5e; font-weight: bold;');
                    result.immediateRisks.forEach(r => console.log(`%c   ⚠️ ${r}`, 'color: #fca5a5;'));
                }
            }
            
            return result;
        }
    } catch(e) {
        console.log(`%c❌ AI Chain Generation error: ${e.message}`, 'color: #f43f5e;');
    }
    
    return null;
};

// AI Report Enhancement
window.aiReport = async (report) => {
    if (!window.AIAgent?.config?.apiKey) {
        console.log('%c❌ AI not configured. Use setAI(key) first.', 'color: #f43f5e;');
        return null;
    }
    
    const reportData = report || window.BountyEngine?.lastResults;
    if (!reportData) {
        console.log('%c⚠️ No report data. Run bounty() first.', 'color: #f59e0b;');
        return null;
    }
    
    console.log('%c\n📝 AI REPORT ENHANCEMENT', 'color: #8b5cf6; font-weight: bold;');
    
    const prompt = `Enhance this bug bounty report to be more professional and impactful:

${JSON.stringify(reportData, null, 2)}

Rewrite the report with:
1. Executive summary
2. Technical details with proper CVE references
3. Step-by-step reproduction
4. Impact assessment
5. Remediation recommendations
6. Timeline for disclosure

Make it ready for submission to HackerOne/Bugcrowd.`;

    try {
        const response = await window.AIAgent.callAI(prompt);
        console.log('%c\n📄 ENHANCED REPORT:', 'color: #22c55e; font-weight: bold;');
        console.log(response);
        
        // Copy to clipboard
        navigator.clipboard.writeText(response).then(() => {
            console.log('%c\n✅ Report copied to clipboard!', 'color: #22c55e;');
        });
        
        return response;
    } catch(e) {
        console.log(`%c❌ AI Report error: ${e.message}`, 'color: #f43f5e;');
    }
    
    return null;
};

// ══════════════════════════════════════════════════════════════════════════════
// TERMINAL BRIDGE - CONNECT TO LINUX TERMINAL VIA WEBSOCKET + HTTP BRIDGE
