// Run ALL bounty curl commands on Linux
window.runAllCurls = async function() {
    if (!TerminalBridge.isConnected()) {
        console.log('%c❌ Not connected. Use connectTerminal() first.', 'color: #f43f5e;');
        return null;
    }
    
    const bountyResults = window.BountyEngine?.lastResults;
    if (!bountyResults || !bountyResults.curlCommands || bountyResults.curlCommands.length === 0) {
        console.log('%c❌ No curl commands. Run bounty() first.', 'color: #f43f5e;');
        return null;
    }
    
    console.log('%c\n🔥 EXECUTING ALL CURL COMMANDS ON LINUX!', 'color: #f43f5e; font-weight: bold; font-size: 16px;');
    console.log('%c═══════════════════════════════════════════════════════════════', 'color: #475569;');
    
    const allResults = [];
    
    for (const cmdGroup of bountyResults.curlCommands) {
        console.log(`%c\n╔═══ ${cmdGroup.api} ═══╗`, 'color: #818cf8; font-weight: bold;');
        
        // Extract curl commands from the group
        const lines = cmdGroup.commands.split('\n');
        const curlLines = lines.filter(l => l.trim().startsWith('curl') && !l.trim().startsWith('#'));
        
        for (const curlCmd of curlLines) {
            console.log(`%c$ ${curlCmd.substring(0, 80)}...`, 'color: #67e8f9; font-family: monospace;');
            
            const result = await TerminalBridge.curl(curlCmd);
            allResults.push({
                api: cmdGroup.api,
                command: curlCmd,
                ...result
            });
            
            if (result.success) {
                console.log('%c   ✅ SUCCESS', 'color: #22c55e; font-weight: bold;');
                
                // Try to parse JSON
                try {
                    const json = JSON.parse(result.stdout);
                    console.log(json);
                    result.json = json;
                } catch(e) {
                    if (result.stdout && result.stdout.length < 500) {
                        console.log(`%c   ${result.stdout}`, 'color: #94a3b8;');
                    }
                }
            } else {
                console.log(`%c   ❌ ${result.error || 'Failed'}`, 'color: #f43f5e;');
            }
            
            // Rate limiting
            await new Promise(r => setTimeout(r, 500));
        }
    }
    
    // Summary
    const successful = allResults.filter(r => r.success).length;
    console.log('%c\n═══════════════════════════════════════════════════════════════', 'color: #475569;');
    console.log(`%c📊 EXECUTION COMPLETE: ${successful}/${allResults.length} successful`, 
        successful > 0 ? 'color: #22c55e; font-weight: bold; font-size: 14px;' : 'color: #f43f5e; font-weight: bold;');
    
    // If AI is enabled, analyze results
    if (window.AIAgent?.config?.apiKey && window.AIAgent?.config?.isActive) {
        console.log('%c\n🤖 AI ANALYZING REAL RESULTS...', 'color: #8b5cf6; font-weight: bold;');
        
        const successfulResults = allResults.filter(r => r.success);
        if (successfulResults.length > 0) {
            const aiPrompt = `You are an ELITE BUG BOUNTY HUNTER. Analyze these REAL API responses from command execution:

${successfulResults.slice(0, 10).map(r => `
API: ${r.api}
Command: ${r.command.substring(0, 100)}
Response: ${(r.stdout || '').substring(0, 500)}
`).join('\n---\n')}

ANALYZE:
1. Are any of these APIs LIVE and EXPLOITABLE?
2. What sensitive data is exposed?
3. Calculate CVSS score for each finding
4. What's the potential bug bounty payout?
5. What are immediate next steps?

Respond in JSON format:
{
  "liveAPIs": [...],
  "criticalFindings": [...],
  "totalBountyEstimate": "$X,XXX",
  "immediateActions": [...]
}`;

            const aiResult = await window.AIAgent.callAI(aiPrompt);
            if (aiResult) {
                console.log('%c📊 AI ANALYSIS OF REAL RESULTS:', 'color: #8b5cf6; font-weight: bold;');
                console.log(aiResult);
            }
        }
    }
    
    return allResults;
};

