// Safe delay helper
const _aiDelay = ms => new Promise(r => setTimeout(r, ms));

// Chat with AI from browser (uses browser AI or terminal AI)
window.ai = async function(prompt, options = {}) {
    const { silent = false, timeout = 60000 } = options;
    
    if (!silent) {
        console.log('%c\n💬 AI QUERY:', 'color: #8b5cf6; font-weight: bold; font-size: 14px;');
        console.log(`%c> ${prompt}`, 'color: #94a3b8;');
    }
    
    // Check if rate limited
    if (window.AIAgent?.isRateLimited?.()) {
        const waitTime = Math.ceil((window.AIAgent.rateLimitUntil - Date.now()) / 1000);
        if (!silent) {
            console.log(`%c⏳ Rate limited. Wait ${waitTime}s or use terminal AI.`, 'color: #f59e0b;');
        }
        // Try terminal if available
        if (TerminalBridge.isConnected()) {
            return await window._aiFromTerminal(prompt, silent, timeout);
        }
        return null;
    }
    
    // Try browser AI first
    if (window.AIAgent?.config?.isValidated && window.AIAgent?.config?.apiKey) {
        if (!silent) console.log('%c   Using: Browser AI (Gemini)', 'color: #818cf8;');
        try {
            const result = await window.AIAgent.callAI(prompt, true);
            if (result) {
                if (!silent) {
                    console.log('%c\n🤖 AI RESPONSE:', 'color: #22c55e; font-weight: bold;');
                    console.log(result);
                }
                return result;
            }
        } catch(e) {
            if (!silent) console.log('%c   Browser AI failed, trying terminal...', 'color: #f59e0b;');
        }
    }
    
    // Fallback to terminal AI
    return await window._aiFromTerminal(prompt, silent, timeout);
};

// Helper: Get AI response from terminal
window._aiFromTerminal = async function(prompt, silent = false, timeout = 60000) {
    if (!TerminalBridge.isConnected()) {
        if (!silent) console.log('%c❌ No AI available. Set API key with setAI() or connect to terminal.', 'color: #f43f5e;');
        return null;
    }
    
    if (!silent) console.log('%c   Using: Terminal AI', 'color: #818cf8;');
    
    try {
        const result = await Promise.race([
            TerminalBridge._send({ type: 'ai_query', query: prompt }),
            new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), timeout))
        ]);
        
        if (result?.error) {
            if (!silent) {
                console.log('%c⚠️ AI Error:', 'color: #f59e0b;');
                console.log(result.error);
            }
            return null;
        }
        
        if (!silent) {
            console.log('%c\n🤖 AI RESPONSE (from Terminal):', 'color: #22c55e; font-weight: bold;');
            console.log(result.response);
        }
        return result.response;
    } catch(e) {
        if (!silent) console.log('%c❌ Terminal AI failed: ' + e.message, 'color: #f43f5e;');
        return null;
    }
};

