// 🤖 AI-TO-AI COMMUNICATION SYSTEM
// ══════════════════════════════════════════════════════════════════════════════
// Browser AI ↔ Terminal AI collaboration for advanced security analysis
// ══════════════════════════════════════════════════════════════════════════════

window.AIBridge = {
    // Ask Terminal AI a question
    async askTerminalAI(question) {
        if (!TerminalBridge.isConnected()) {
            console.log('%c❌ Terminal not connected', 'color: #f43f5e;');
            return null;
        }
        
        console.log('%c🤖 BROWSER → TERMINAL AI', 'color: #8b5cf6; font-weight: bold;');
        console.log(`%c   Question: ${question.substring(0, 100)}...`, 'color: #94a3b8;');
        
        const result = await TerminalBridge.send({
            type: 'ai_query',
            query: question,
            from: 'browser'
        });
        
        if (result?.response) {
            console.log('%c🤖 TERMINAL AI RESPONSE:', 'color: #22c55e; font-weight: bold;');
            console.log(result.response);
            return result.response;
        }
        
        return result;
    },
    
    // Full collaboration - both AIs work together
    async collaborate(findings) {
        const data = findings || window.DataStore?.getAll?.() || [];
        
        if (data.length === 0) {
            console.log('%c❌ No findings to analyze. Run start() first.', 'color: #f43f5e;');
            return null;
        }
        
        console.log('%c\n🔥 AI-TO-AI COLLABORATION MODE', 'color: #ec4899; font-weight: bold; font-size: 18px;');
        console.log('%c═══════════════════════════════════════════════════════════════', 'color: #475569;');
        console.log('%c   Browser AI + Terminal AI working together...', 'color: #94a3b8;');
        
        // Step 1: Browser AI analyzes findings
        console.log('%c\n📍 STEP 1: Browser AI Initial Analysis...', 'color: #3b82f6; font-weight: bold;');
        
        let browserAnalysis = null;
        if (window.AIAgent?.config?.isActive) {
            const browserPrompt = `Analyze these ${data.length} security findings from browser scan. 
Identify the TOP 5 most exploitable ones and explain WHY:

${JSON.stringify(data.slice(0, 20), null, 2)}

Respond as JSON: { "top5": [...], "attackVectors": [...], "questions_for_terminal_ai": [...] }`;
            
            browserAnalysis = await window.AIAgent.callAI(browserPrompt);
            console.log('%c   Browser AI:', 'color: #3b82f6;');
            console.log(browserAnalysis);
        } else {
            console.log('%c   ⚠️ Browser AI not active, using default analysis', 'color: #f59e0b;');
            browserAnalysis = {
                top5: data.slice(0, 5).map(f => f.value),
                questions_for_terminal_ai: [
                    "Can you validate these API keys with real requests?",
                    "What exploits can you run against these endpoints?",
                    "Check if any of these are live and exploitable"
                ]
            };
        }
        
        // Step 2: Send to Terminal AI for validation
        console.log('%c\n📍 STEP 2: Terminal AI Validation...', 'color: #8b5cf6; font-weight: bold;');
        
        if (!TerminalBridge.isConnected()) {
            console.log('%c   ❌ Terminal not connected. Connect first!', 'color: #f43f5e;');
            return browserAnalysis;
        }
        
        const terminalQuery = `Browser AI analyzed a security scan and found:

${typeof browserAnalysis === 'string' ? browserAnalysis : JSON.stringify(browserAnalysis, null, 2)}

YOUR TASK AS TERMINAL AI:
1. Validate these findings using real commands (curl, nmap, etc.)
2. Check which API keys/secrets are LIVE
3. Suggest exploitation commands
4. Calculate real bounty potential

Respond with actionable commands and analysis.`;
        
        const terminalResponse = await this.askTerminalAI(terminalQuery);
        
        // Step 3: Browser AI processes terminal response
        console.log('%c\n📍 STEP 3: Browser AI Final Report...', 'color: #22c55e; font-weight: bold;');
        
        let finalReport = null;
        if (window.AIAgent?.config?.isActive && terminalResponse) {
            const finalPrompt = `Terminal AI validated our findings and responded:

${typeof terminalResponse === 'string' ? terminalResponse : JSON.stringify(terminalResponse)}

Based on Terminal AI's validation:
1. Which findings are CONFIRMED exploitable?
2. What's the final bounty estimate?
3. Generate a professional bug bounty report

Respond as JSON: { "confirmed": [...], "bountyEstimate": "$X,XXX", "report": "..." }`;
            
            finalReport = await window.AIAgent.callAI(finalPrompt);
        } else {
            finalReport = {
                browserAnalysis,
                terminalResponse,
                status: 'Collaboration complete'
            };
        }
        
        console.log('%c\n═══════════════════════════════════════════════════════════════', 'color: #475569;');
        console.log('%c🎯 AI COLLABORATION COMPLETE!', 'color: #22c55e; font-weight: bold; font-size: 16px;');
        console.log(finalReport);
        
        return {
            browserAnalysis,
            terminalResponse,
            finalReport
        };
    },
    
    // Quick validate - ask terminal to validate a specific finding
    async validate(finding) {
        const target = typeof finding === 'number' 
            ? window.DataStore?.findings?.[finding] 
            : finding;
            
        if (!target) {
            console.log('%c❌ Finding not found', 'color: #f43f5e;');
            return null;
        }
        
        console.log('%c🔍 Asking Terminal AI to validate...', 'color: #8b5cf6;');
        
        return await this.askTerminalAI(`Validate this security finding:
Type: ${target.type}
Value: ${target.value}
Source: ${target.source}

Run real commands to check if this is exploitable. Return validation result.`);
    },
    
    // Execute AI-suggested command
    async executeAISuggestion(suggestion) {
        console.log('%c🤖 Executing AI suggestion...', 'color: #8b5cf6;');
        
        // Extract command from suggestion
        const cmdMatch = suggestion.match(/```(?:bash|sh)?\n?([\s\S]*?)```/) ||
                        suggestion.match(/\$\s*(.+)/) ||
                        suggestion.match(/curl\s+.+/);
                        
        if (cmdMatch) {
            const cmd = cmdMatch[1] || cmdMatch[0];
            console.log(`%c$ ${cmd}`, 'color: #22d3ee; font-family: monospace;');
            return await terminalRun(cmd.trim());
        }
        
        console.log('%c❌ No executable command found in suggestion', 'color: #f59e0b;');
        return null;
    }
};

// Quick shortcuts
window.aiCollab = () => AIBridge.collaborate();
window.askTerminal = (q) => AIBridge.askTerminalAI(q);
window.aiValidate = (n) => AIBridge.validate(n);

