// ══════════════════════════════════════════════════════════════════════════════
// GLOBAL CURL EXECUTOR - RUNS CURL COMMANDS AS REAL API CALLS
// ══════════════════════════════════════════════════════════════════════════════

window.runCurl = async function(curlCommand) {
    // If terminal is connected, use that instead
    if (TerminalBridge.isConnected()) {
        return await terminalCurl(curlCommand);
    }
    
    console.log('%c🚀 EXECUTING CURL COMMAND...', 'color: #3b82f6; font-weight: bold;');
    console.log(`%c$ ${curlCommand}`, 'color: #64748b; font-family: monospace;');
    
    try {
        // Parse curl command
        const urlMatch = curlCommand.match(/curl\s+(?:['"](https?:\/\/[^'"]+)['"]|(https?:\/\/\S+))/i) ||
                        curlCommand.match(/(https?:\/\/\S+)/);
        
        if (!urlMatch) {
            console.log('%c❌ Could not parse URL from curl command', 'color: #f43f5e;');
            return null;
        }
        
        const url = urlMatch[1] || urlMatch[2];
        const headers = {};
        
        // Extract headers
        const headerMatches = curlCommand.matchAll(/-H\s+['"]([^:]+):\s*([^'"]+)['"]/gi);
        for (const match of headerMatches) {
            headers[match[1].trim()] = match[2].trim();
        }
        
        // Extract Authorization
        const authMatch = curlCommand.match(/(?:-u|--user)\s+['"]?([^'"\s]+)['"]?/);
        if (authMatch) {
            headers['Authorization'] = 'Basic ' + btoa(authMatch[1]);
        }
        
        // Determine method
        let method = 'GET';
        if (curlCommand.includes('-X POST') || curlCommand.includes('-d') || curlCommand.includes('--data')) {
            method = 'POST';
        } else if (curlCommand.includes('-X PUT')) {
            method = 'PUT';
        } else if (curlCommand.includes('-X DELETE')) {
            method = 'DELETE';
        }
        
        // Extract body data
        let body = null;
        const dataMatch = curlCommand.match(/(?:-d|--data)\s+['"](.+?)['"]/s);
        if (dataMatch) {
            body = dataMatch[1];
        }
        
        console.log('%c📡 Making request:', 'color: #818cf8;');
        console.log(`%c   Method: ${method}`, 'color: #94a3b8;');
        console.log(`%c   URL: ${url}`, 'color: #94a3b8;');
        console.log(`%c   Headers: ${JSON.stringify(headers)}`, 'color: #94a3b8;');
        
        const fetchOptions = {
            method: method,
            headers: headers,
            mode: 'cors'
        };
        
        if (body && (method === 'POST' || method === 'PUT')) {
            fetchOptions.body = body;
        }
        
        const response = await fetch(url, fetchOptions);
        const status = response.status;
        
        let data;
        const contentType = response.headers.get('content-type') || '';
        if (contentType.includes('json')) {
            data = await response.json();
        } else {
            data = await response.text();
        }
        
        const success = status >= 200 && status < 300;
        
        if (success) {
            console.log(`%c\n✅ SUCCESS - HTTP ${status}`, 'color: #22c55e; font-weight: bold; font-size: 14px;');
        } else if (status === 401 || status === 403) {
            console.log(`%c\n🔒 AUTH REQUIRED - HTTP ${status}`, 'color: #f59e0b; font-weight: bold;');
        } else {
            console.log(`%c\n❌ FAILED - HTTP ${status}`, 'color: #f43f5e; font-weight: bold;');
        }
        
        console.log('%c📦 RESPONSE:', 'color: #3b82f6; font-weight: bold;');
        if (typeof data === 'object') {
            console.log(data);
        } else {
            console.log(`%c${data}`, 'color: #94a3b8;');
        }
        
        return { success, status, data, url, method };
        
    } catch(e) {
        console.log(`%c❌ Request failed: ${e.message}`, 'color: #f43f5e;');
        return { success: false, error: e.message };
    }
};

// Execute multiple curl commands
window.runCurls = async function(curlCommands) {
    if (!Array.isArray(curlCommands)) {
        curlCommands = curlCommands.split('\n').filter(c => c.trim().startsWith('curl'));
    }
    
    console.log(`%c🚀 EXECUTING ${curlCommands.length} CURL COMMANDS...`, 'color: #3b82f6; font-weight: bold; font-size: 16px;');
    console.log('%c═══════════════════════════════════════════════════════════════', 'color: #475569;');
    
    const results = [];
    for (let i = 0; i < curlCommands.length; i++) {
        const cmd = curlCommands[i].trim();
        if (!cmd || !cmd.includes('curl')) continue;
        
        console.log(`%c\n[${i+1}/${curlCommands.length}]`, 'color: #818cf8; font-weight: bold;');
        const result = await window.runCurl(cmd);
        results.push(result);
        
        // Rate limiting
        await new Promise(r => setTimeout(r, 300));
    }
    
    // Summary
    console.log('%c\n═══════════════════════════════════════════════════════════════', 'color: #475569;');
    const success = results.filter(r => r?.success).length;
    console.log(`%c📊 SUMMARY: ${success}/${results.length} successful`, success > 0 ? 'color: #22c55e; font-weight: bold;' : 'color: #64748b;');
    
    return results;
};

// Global AI analyze function
window.aiAnalyze = async function(data) {
    if (!window.AIAgent?.config?.apiKey) {
        console.log('%c⚠️ AI not configured. Use setAI("your-key") first.', 'color: #f59e0b;');
        return null;
    }
    
    // If data not provided, use last bounty results
    if (!data && window.BountyEngine?.lastResults) {
        const results = window.BountyEngine.lastResults;
        return await window.AIAgent.autonomousAnalyze(
            results.filteredFindings || results.rawFindings || [],
            results.exploitResults || []
        );
    }
    
    // If data is provided, analyze it
    if (data) {
        const prompt = `Analyze this security data and provide insights:\n\n${JSON.stringify(data, null, 2)}\n\nProvide CVSS score, exploitability, attack scenarios, and recommendations.`;
        const response = await window.AIAgent.query(prompt);
        console.log('%c🤖 AI ANALYSIS:', 'color: #8b5cf6; font-weight: bold; font-size: 14px;');
        console.log(response);
        return response;
    }
    
    console.log('%c⚠️ No data to analyze. Run bounty() first.', 'color: #f59e0b;');
    return null;
};

