// Auto-reconnect terminal
window.reconnect = async function() {
    console.log('%c🔌 Reconnecting...', 'color: #3b82f6; font-weight: bold;');
    
    const conn = window.__NEXUS_CONNECTION__;
    if (conn) {
        await conn.connectTerminal(null, null, { forceReconnect: true });
        await conn.connectAI();
    } else {
        // Fallback to existing methods
        if (window.TerminalBridge?.connect) {
            const url = localStorage.getItem('nexus_terminal_url');
            const token = localStorage.getItem('nexus_terminal_token');
            if (url && token) {
                await window.TerminalBridge.connect(url, token);
            } else {
                console.log('%c⚠️ No saved credentials. Use terminal() to connect.', 'color: #f59e0b;');
            }
        }
    }
};

